import { parseScriptTitle, toFileNameSlug } from "./luaCompletionContext";

// Resolves a sanitised base name for exported files (thumbnails, recordings).
// Strictly prefers the metadata title ("-- @title ..."), falling back to the
// script file name / URI base when no title metadata is declared.
export function exportBaseName(scriptSource: string | undefined, luaUri: string): string {
  const titleSlug = scriptSource !== undefined ? toFileNameSlug(parseScriptTitle(scriptSource)) : "";
  if (titleSlug !== "") {
    return titleSlug;
  }
  const cleanUri = luaUri.replace(/\.lua$/i, "");
  const lastSegment = cleanUri.split(/[/\\]/).pop() ?? "";
  const fallbackSlug = toFileNameSlug(lastSegment);
  return fallbackSlug !== "" ? fallbackSlug : "script";
}

// Determines the file extension for a thumbnail based on its image MIME type.
export function getThumbnailExtension(mimeType: string): string {
  return mimeType === "image/webp" ? "webp" : "png";
}

// Generates the default file name for an exported thumbnail.
export function getThumbnailFileName(
  scriptSource: string | undefined,
  luaUri: string,
  mimeType: string,
): string {
  const baseName = exportBaseName(scriptSource, luaUri);
  const extension = getThumbnailExtension(mimeType);
  return `${baseName}.${extension}`;
}

// Generates the default file name for an exported video recording (WebM or MP4).
export function getVideoFileName(
  scriptSource: string | undefined,
  luaUri: string,
  startFrame: number,
  endFrame: number,
  mimeTypeOrFormat: string = "webm",
): string {
  const baseName = exportBaseName(scriptSource, luaUri);
  const isMp4 = mimeTypeOrFormat === "mp4" || mimeTypeOrFormat === "video/mp4";
  const extension = isMp4 ? "mp4" : "webm";
  return `${baseName}_${startFrame}-${endFrame}.${extension}`;
}
