// Embeds the source script into a recorded WebM as a Matroska Attachments
// element. Players skip the element (attachments are outside the strict WebM
// subset) while Matroska tools such as `mkvextract attachments` can recover
// the file.
//
// Where the element goes depends on how the Segment was written. A Segment of
// unknown size (what MediaRecorder produces) never ends, so bytes appended at
// the end of the file are already parsed as further Segment children. A
// Segment of known size (what the WebCodecs muxer produces) declares its own
// length, so the element must be spliced in before the Segment ends and the
// declared size grown to cover it -- otherwise the attachment falls outside
// the Segment and the file's structure no longer describes its own bytes.

const kSegmentId = [0x18, 0x53, 0x80, 0x67];
const kAttachmentsId = [0x19, 0x41, 0xa4, 0x69];
const kAttachedFileId = [0x61, 0xa7];
const kFileNameId = [0x46, 0x6e];
const kFileMimeTypeId = [0x46, 0x60];
const kFileUidId = [0x46, 0xae];
const kFileDataId = [0x46, 0x5c];
const kFileUid = [0x01];
const kMimeType = "text/x-lua";
// Segment sizes are rewritten in place, so the replacement size must occupy
// exactly as many bytes as the original. Muxers write this field at a fixed
// width to reserve room for the final value; anything narrower than the
// original is left-padded back up to it.
const kUnknownSizeMarker = 0xff;

export function appendScriptAttachment(
  webmBytes: Uint8Array,
  scriptFileName: string,
  scriptSource: string,
): Uint8Array {
  const attachments = buildAttachments(scriptFileName, scriptSource);
  const segment = findSegmentHeader(webmBytes);
  let result: Uint8Array;
  if (segment === undefined || segment.unknownSize) {
    result = concatBytes([webmBytes, attachments]);
  } else {
    result = spliceIntoSegment(webmBytes, segment, attachments);
  }
  return result;
}

function buildAttachments(scriptFileName: string, scriptSource: string): Uint8Array {
  const encoder = new TextEncoder();
  const attachedFile = ebmlElement(kAttachedFileId, [
    ebmlElement(kFileNameId, [encoder.encode(scriptFileName)]),
    ebmlElement(kFileMimeTypeId, [encoder.encode(kMimeType)]),
    ebmlElement(kFileUidId, [Uint8Array.from(kFileUid)]),
    ebmlElement(kFileDataId, [encoder.encode(scriptSource)]),
  ]);
  return ebmlElement(kAttachmentsId, [attachedFile]);
}

interface SegmentHeader {
  sizeOffset: number;
  sizeWidth: number;
  size: number;
  payloadEnd: number;
  unknownSize: boolean;
}

// Locates the Segment element that follows the EBML header. Only the first
// Segment is considered: recordings produced here always contain exactly one.
function findSegmentHeader(bytes: Uint8Array): SegmentHeader | undefined {
  let result: SegmentHeader | undefined;
  const segmentOffset = indexOfPattern(bytes, kSegmentId);
  if (segmentOffset >= 0) {
    const sizeOffset = segmentOffset + kSegmentId.length;
    const size = readVint(bytes, sizeOffset);
    if (size !== undefined) {
      const payloadStart = sizeOffset + size.width;
      const unknownSize = size.unknown;
      const payloadEnd = unknownSize ? bytes.length : payloadStart + size.value;
      if (payloadEnd <= bytes.length) {
        result = {
          sizeOffset,
          sizeWidth: size.width,
          size: size.value,
          payloadEnd,
          unknownSize,
        };
      }
    }
  }
  return result;
}

// Inserts the element at the end of the Segment payload and grows the declared
// Segment size to match, keeping the size field at its original byte width.
function spliceIntoSegment(
  bytes: Uint8Array,
  segment: SegmentHeader,
  element: Uint8Array,
): Uint8Array {
  const updatedSize = encodeEbmlSizeFixedWidth(
    segment.size + element.length,
    segment.sizeWidth,
  );
  let result: Uint8Array;
  if (updatedSize === undefined) {
    // The grown size no longer fits the reserved field; leaving the file
    // unmodified is safer than emitting a Segment that lies about its length.
    result = bytes;
  } else {
    result = concatBytes([
      bytes.slice(0, segment.sizeOffset),
      updatedSize,
      bytes.slice(segment.sizeOffset + segment.sizeWidth, segment.payloadEnd),
      element,
      bytes.slice(segment.payloadEnd),
    ]);
  }
  return result;
}

export interface ExtractedScriptAttachment {
  fileName: string;
  source: string;
}

// Recovers the script embedded by appendScriptAttachment. The Attachments
// element carries no offset index, so this scans for its ID pattern from the
// end of the file and validates the full element structure before trusting a
// match (raw video bytes can contain the same 4-byte sequence by chance).
export function extractScriptAttachment(
  webmBytes: Uint8Array,
): ExtractedScriptAttachment | undefined {
  let result: ExtractedScriptAttachment | undefined;
  let searchEnd = webmBytes.length;
  while (result === undefined && searchEnd > 0) {
    const candidate = lastIndexOfPattern(webmBytes, kAttachmentsId, searchEnd);
    if (candidate < 0) {
      break;
    }
    result = parseAttachments(webmBytes, candidate);
    searchEnd = candidate;
  }
  return result;
}

function parseAttachments(
  bytes: Uint8Array,
  attachmentsOffset: number,
): ExtractedScriptAttachment | undefined {
  const decoder = new TextDecoder();
  let result: ExtractedScriptAttachment | undefined;
  const attachments = readElement(bytes, attachmentsOffset, kAttachmentsId);
  const attachedFile =
    attachments === undefined
      ? undefined
      : readElement(bytes, attachments.payloadStart, kAttachedFileId);
  if (attachments !== undefined && attachedFile !== undefined) {
    let fileName: string | undefined;
    let mimeType: string | undefined;
    let fileData: Uint8Array | undefined;
    let offset = attachedFile.payloadStart;
    while (offset < attachedFile.payloadEnd) {
      const id = Array.from(bytes.slice(offset, offset + 2));
      const size = readVint(bytes, offset + 2);
      if (size === undefined) {
        break;
      }
      const payloadStart = offset + 2 + size.width;
      const payload = bytes.slice(payloadStart, payloadStart + size.value);
      if (matchesId(id, kFileNameId)) {
        fileName = decoder.decode(payload);
      } else if (matchesId(id, kFileMimeTypeId)) {
        mimeType = decoder.decode(payload);
      } else if (matchesId(id, kFileDataId)) {
        fileData = payload;
      }
      offset = payloadStart + size.value;
    }
    if (fileName !== undefined && mimeType === kMimeType && fileData !== undefined) {
      result = { fileName, source: decoder.decode(fileData) };
    }
  }
  return result;
}

interface ElementBounds {
  payloadStart: number;
  payloadEnd: number;
}

function readElement(
  bytes: Uint8Array,
  offset: number,
  expectedId: number[],
): ElementBounds | undefined {
  let result: ElementBounds | undefined;
  const id = Array.from(bytes.slice(offset, offset + expectedId.length));
  if (matchesId(id, expectedId)) {
    const size = readVint(bytes, offset + expectedId.length);
    if (size !== undefined) {
      const payloadStart = offset + expectedId.length + size.width;
      const payloadEnd = payloadStart + size.value;
      if (payloadEnd <= bytes.length) {
        result = { payloadStart, payloadEnd };
      }
    }
  }
  return result;
}

// An all-ones payload means "unknown size": the element runs to the end of its
// parent rather than declaring a length.
function readVint(
  bytes: Uint8Array,
  offset: number,
): { value: number; width: number; unknown: boolean } | undefined {
  let result: { value: number; width: number; unknown: boolean } | undefined;
  const first = bytes[offset];
  if (first !== undefined && first !== 0) {
    let width = 1;
    while ((first & (1 << (8 - width))) === 0) {
      width += 1;
    }
    if (offset + width <= bytes.length) {
      let value = first & ((1 << (8 - width)) - 1);
      let unknown = value === (1 << (8 - width)) - 1;
      for (let index = 1; index < width; index += 1) {
        const byte = bytes[offset + index];
        value = value * 256 + byte;
        unknown = unknown && byte === kUnknownSizeMarker;
      }
      result = { value, width, unknown };
    }
  }
  return result;
}

// Encodes a size into exactly `width` bytes, so it can overwrite an existing
// size field in place. Returns undefined when the value does not fit.
function encodeEbmlSizeFixedWidth(value: number, width: number): Uint8Array | undefined {
  let result: Uint8Array | undefined;
  const capacity = 2 ** (7 * width) - 2;
  if (value <= capacity) {
    const bytes = new Uint8Array(width);
    let remaining = value;
    for (let index = width - 1; index >= 0; index -= 1) {
      bytes[index] = remaining % 256;
      remaining = Math.floor(remaining / 256);
    }
    bytes[0] |= 1 << (8 - width);
    result = bytes;
  }
  return result;
}

function indexOfPattern(bytes: Uint8Array, pattern: number[]): number {
  let result = -1;
  const limit = bytes.length - pattern.length;
  for (let offset = 0; result < 0 && offset <= limit; offset += 1) {
    if (pattern.every((byte, index) => bytes[offset + index] === byte)) {
      result = offset;
    }
  }
  return result;
}

function matchesId(id: number[], expected: number[]): boolean {
  return id.length === expected.length && id.every((byte, index) => byte === expected[index]);
}

function lastIndexOfPattern(bytes: Uint8Array, pattern: number[], searchEnd: number): number {
  let result = -1;
  for (let offset = searchEnd - pattern.length; result < 0 && offset >= 0; offset -= 1) {
    if (pattern.every((byte, index) => bytes[offset + index] === byte)) {
      result = offset;
    }
  }
  return result;
}

function ebmlElement(id: number[], payloadParts: Uint8Array[]): Uint8Array {
  const payload = concatBytes(payloadParts);
  return concatBytes([Uint8Array.from(id), encodeEbmlSize(payload.length), payload]);
}

// EBML variable-width size: the leading byte carries a marker bit at position
// (8 - width); the remaining bits hold the value. All-ones payloads are
// reserved for "unknown size", hence the `- 1` in the capacity check.
function encodeEbmlSize(value: number): Uint8Array {
  let width = 1;
  while (width < 8 && value > 2 ** (7 * width) - 2) {
    width += 1;
  }
  const bytes = new Uint8Array(width);
  let remaining = value;
  for (let index = width - 1; index >= 0; index -= 1) {
    bytes[index] = remaining % 256;
    remaining = Math.floor(remaining / 256);
  }
  bytes[0] |= 1 << (8 - width);
  return bytes;
}

function concatBytes(parts: Uint8Array[]): Uint8Array {
  const total = parts.reduce((sum, part) => sum + part.length, 0);
  const result = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    result.set(part, offset);
    offset += part.length;
  }
  return result;
}
