// Toggles the hamburger dropdown (sample browser, load-script, docs, and
// licenses — everything that used to live in a permanent editor toolbar).
// Closes on an outside click, on Escape, or after choosing a menu action so
// it doesn't linger over the editor.
function wireAppMenu(menuButton: HTMLElement, menu: HTMLElement): void {
  const setOpen = (open: boolean) => {
    menu.classList.toggle("open", open);
    menuButton.setAttribute("aria-expanded", String(open));
  };
  menuButton.addEventListener("click", (event) => {
    event.stopPropagation();
    setOpen(!menu.classList.contains("open"));
  });
  document.addEventListener("click", (event) => {
    if (menu.classList.contains("open") && !menu.contains(event.target as Node)) {
      setOpen(false);
    }
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && menu.classList.contains("open")) {
      setOpen(false);
    }
  });
  // Every menu button click is a completed action (including opening the
  // sample browser overlay), so the dropdown itself always closes.
  for (const button of menu.querySelectorAll("button")) {
    button.addEventListener("click", () => setOpen(false));
  }
}

// Seeds a fresh scene with the bundled font for the script's font language
// (`@recommend lang`, or inferred from `@recommend text` -- see
// parseMugMetadata), so a Japanese sample opens in a font that can render it.
// The VSCode build does the same against the system font catalog, in
// simulatorPanel.ts's loadScene.
function applyBundledFontForLanguage(scene: Scene, metadata: MugMetadata): void {
  const languageFont = chooseBundledFontForLanguage(metadata.fontLang);
  if (languageFont !== undefined) {
    scene.global.fontName = languageFont.family;
    scene.settings.fontPath = languageFont.path;
  }
}

// Owns the state a plain SimulatorApp doesn't need to know about: which
// script (default or a picked sample) is currently loaded, and suppressing
// the editor's change-reload debounce while a sample switch programmatically
// replaces the buffer (so it isn't mistaken for user typing).
class WebSimulatorShell {
  private currentScriptId = kDefaultScriptId;
  private suppressChangeReload = false;
  private switchGeneration = 0;
  private readonly debouncedReload = createDebouncer(
    (source: string) => this.app.enqueueReload(source),
    kEditDebounceMs,
  );

  constructor(
    private readonly editor: Monaco.editor.IStandaloneCodeEditor,
    private readonly app: SimulatorApp,
    private fontPath: string | undefined,
    private fontBytes: ArrayBuffer | undefined,
  ) {
    this.editor.onDidChangeModelContent(() => {
      if (!this.suppressChangeReload) {
        this.debouncedReload.call(this.editor.getValue());
      }
    });
  }

  get scriptId(): string {
    return this.currentScriptId;
  }

  setCurrentScript(source: string): void {
    this.suppressChangeReload = true;
    this.editor.setValue(source);
    this.suppressChangeReload = false;
    this.app.enqueueReload(source);
  }

  // Gallery entries carry only a URL, so the script is fetched here rather
  // than read straight off the catalog entry (see loadSampleSource).
  async switchToSample(sample: SampleEntry): Promise<boolean> {
    const switchGeneration = this.beginScriptSwitch();
    const source = await loadSampleSource(sample);
    let switched = false;
    if (switchGeneration === this.switchGeneration) {
      switched = await this.switchToScript(sample.id, source, switchGeneration);
    }
    return switched;
  }

  // Switches the font the next switchTarget will hand the simulator, fetching
  // its bytes only when the path actually changes. A failed fetch keeps the
  // current font rather than dropping the simulator to box rendering.
  private async useFont(
    path: string | undefined,
    switchGeneration: number,
  ): Promise<void> {
    if (path !== undefined && path !== this.fontPath) {
      try {
        const fontBytes = await loadFontBytes(path);
        if (switchGeneration === this.switchGeneration) {
          this.fontBytes = fontBytes;
          this.fontPath = path;
        }
      } catch {
        // Keep the font already loaded.
      }
    }
  }

  // Shared by sample switching and WebM script recovery: both replace the
  // editor buffer wholesale and hand the simulator a fresh target under a
  // new script id (each with its own persisted scene).
  private async switchToScript(
    scriptId: string,
    source: string,
    switchGeneration: number,
  ): Promise<boolean> {
    if (switchGeneration !== this.switchGeneration) {
      return false;
    }
    this.suppressChangeReload = true;
    this.editor.setValue(source);
    this.suppressChangeReload = false;
    this.currentScriptId = scriptId;
    const metadata = parseMugMetadata(source);
    const sourceHash = computeSourceHash(source);
    // Metadata (@duration, @recommend bg, @required 3d, ...) only seeds a
    // scene the user has never touched before, same rule as the VSCode
    // extension's loadScene (see simulatorPanel.ts): once a scene has been
    // saved, whatever the inspector holds wins over the script header. The
    // exceptions are a stored text that predates `@recommend text`, which
    // loadStoredScene migrates (see restoreScene), or a sample/script whose
    // source hash has changed.
    const { scene, isNewScene } = loadStoredScene(scriptId, metadata, sourceHash);
    if (isNewScene) {
      applyMetadataToScene(scene, metadata);
      applyBundledFontForLanguage(scene, metadata);
    }
    // The scene decides the font: a migrated or freshly seeded one may ask for
    // the bundled Japanese font, which the shell's current selection would
    // otherwise overwrite. Only fall back to that selection when the scene has
    // no font of its own.
    const fontToUse = scene.settings.fontPath ?? this.fontPath;
    await this.useFont(fontToUse, switchGeneration);
    if (switchGeneration !== this.switchGeneration) {
      return false;
    }
    if (this.fontPath !== undefined) {
      scene.settings.fontPath = this.fontPath;
    }
    await this.app.switchTarget({
      scene,
      luaSource: source,
      luaUri: scriptId,
      luaPath: scriptId,
      fontPath: this.fontPath,
      // switchTarget falls back to no layout engine (box rendering) whenever
      // fontBytes is missing, so this must be forwarded on every switch, not
      // just the initial start() call.
      fontBytes: this.fontBytes,
      globalLoop: true,
    });
    return switchGeneration === this.switchGeneration;
  }

  // Used for both a directly loaded .lua file and one recovered from a
  // recorded WebM's embedded attachment (see wireFileLoader). Mirrors the
  // VSCode extension's chooseRestoreUri fallback naming so a loaded script
  // never collides with a same-named sample or the default script's
  // persisted scene.
  async loadFromFile(fileName: string, source: string): Promise<void> {
    const switchGeneration = this.beginScriptSwitch();
    const scriptId = `loaded:${fileName}`;
    if (await this.switchToScript(scriptId, source, switchGeneration)) {
      replaceBrowserSampleUrl(undefined);
    }
  }

  // Paste Script (see wireGeneralMenuActions): a clipboard-driven variant of
  // loadFromFile with no file name to key the persisted scene off of, so it
  // reuses the same "loaded:" id every time instead of one per paste.
  beginClipboardLoad(): number {
    return this.beginScriptSwitch();
  }

  async loadFromClipboardText(
    source: string,
    switchGeneration = this.beginScriptSwitch(),
  ): Promise<void> {
    if (await this.switchToScript("loaded:clipboard", source, switchGeneration)) {
      replaceBrowserSampleUrl(undefined);
    }
  }

  // New Script (see wireGeneralMenuActions): unlike loadFromFile/Sample, this
  // needs a scene loadStoredScene has never seen before every time, not a
  // stable id, so a fresh document always starts from SimulatorApp's actual
  // defaults rather than resuming whatever scene a previous "new" left behind.
  async createNewScript(): Promise<void> {
    const switchGeneration = this.beginScriptSwitch();
    const scriptId = `new:${Date.now()}`;
    if (await this.switchToScript(scriptId, kNewScriptTemplate, switchGeneration)) {
      replaceBrowserSampleUrl(undefined);
    }
  }

  async showDefaultScript(): Promise<void> {
    const switchGeneration = this.beginScriptSwitch();
    await this.switchToScript(kDefaultScriptId, kNewScriptTemplate, switchGeneration);
  }

  private beginScriptSwitch(): number {
    this.debouncedReload.cancel();
    this.switchGeneration += 1;
    return this.switchGeneration;
  }
}

function pushBrowserSampleUrl(sampleId: string): void {
  if (readSampleIdFromUrl(window.location.href) !== sampleId) {
    window.history.pushState(null, "", buildUrlForSample(window.location.href, sampleId));
  }
}

function replaceBrowserSampleUrl(sampleId: string | undefined): void {
  if (readSampleIdFromUrl(window.location.href) !== sampleId) {
    window.history.replaceState(null, "", buildUrlForSample(window.location.href, sampleId));
  }
}

async function fetchText(uri: string): Promise<string> {
  const response = await fetch(uri);
  if (!response.ok) {
    throw new Error(`failed to fetch text asset: ${uri} (${response.status})`);
  }
  return response.text();
}

async function encodeBlobForWebMcp(blob: Blob): Promise<WebMcpImage> {
  const bytes = new Uint8Array(await blob.arrayBuffer());
  let binary = "";
  for (let offset = 0; offset < bytes.length; offset += kBase64ChunkSize) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + kBase64ChunkSize));
  }
  return {
    data: btoa(binary),
    mimeType: blob.type || "image/png",
  };
}

async function main(): Promise<void> {
  const elements = getRequiredElements();
  applyStaticTranslations();

  const monacoPromise = import("monaco-editor");
  const preludeSourcesPromise = Promise.all([
    fetchText("prelude.lua"),
    fetchText("prelude_drawing_path.lua"),
  ]);
  let layoutEditor: Monaco.editor.IStandaloneCodeEditor | undefined;
  const gridLayout = new WebGridLayout(
    elements.shell,
    elements.editorPane,
    elements.editorContainer,
    elements.logPanel,
    elements.simulatorContainer,
    () => layoutEditor?.layout(),
  );
  const templateMetadata = parseMugMetadata(kNewScriptTemplate);
  const { scene, isNewScene } = loadStoredScene(kDefaultScriptId, templateMetadata);
  if (isNewScene) {
    applyMetadataToScene(scene, templateMetadata);
    applyBundledFontForLanguage(scene, templateMetadata);
  }
  const fontList = [...bundledFontEntries];
  const defaultFontPath = scene.settings.fontPath ?? fontList[0]?.path;
  const defaultFontBytesPromise =
    defaultFontPath !== undefined
      ? loadFontBytes(defaultFontPath)
      : Promise.resolve(undefined);
  const [monaco, preludeSources, defaultFontBytes] = await Promise.all([
    monacoPromise,
    preludeSourcesPromise,
    defaultFontBytesPromise,
  ]);
  const preludeSource = joinPreludeSources(...preludeSources);

  registerMonacoLuaLanguage(monaco);
  elements.editorContainer.replaceChildren();
  const editor = monaco.editor.create(elements.editorContainer, {
    value: kNewScriptTemplate,
    language: "lua",
    theme: kMonacoMtDarkThemeName,
    automaticLayout: true,
    minimap: { enabled: false },
    mouseWheelZoom: true,
  });
  layoutEditor = editor;

  const host = new WebHostAdapter({
    fontList,
    loadFontBytes,
    getCurrentScriptSource: () => editor.getValue(),
    onLogLine: wireLogPanel(
      elements.logPanelBody,
      elements.logPanelClearButton,
      (requestedLineNumber) => {
        const lineCount = editor.getModel()?.getLineCount() ?? 1;
        const lineNumber = Math.min(requestedLineNumber, lineCount);
        editor.setPosition({ lineNumber, column: 1 });
        editor.revealLineInCenter(lineNumber);
        editor.focus();
      },
    ),
  });

  const app = new SimulatorApp(host, gridLayout, {
    showPluginCompatibilityNotice: true,
  });
  host.onFontBytes((result) => app.applyFont(result));
  host.onScriptCopyResult((success) => app.showScriptCopyResult(success));

  await app.start({
    scene,
    luaSource: editor.getValue(),
    luaUri: kDefaultScriptId,
    luaPath: kDefaultScriptId,
    fontPath: defaultFontPath,
    fontBytes: defaultFontBytes,
    globalLoop: true,
    preludeSource,
    wasmUri: kWasmUri,
    hbModuleUri: kHbModuleUri,
    fontList,
  });

  const shell = new WebSimulatorShell(editor, app, defaultFontPath, defaultFontBytes);
  elements.appBarVersion.textContent = `v${__MT_SIM_VERSION__} (API level ${kScriptApiLevel})`;
  wireAppMenu(elements.appMenuButton, elements.appMenu);
  await wireSampleBrowser(elements, shell);
  wireScriptingCheck(
    elements,
    preludeSource,
    fontList.map((font) => font.family),
  );
  wireDocViewer(elements);
  wireAiReferenceActions(elements, app);
  wireLanguageSelect(elements);
  wireLicensesViewer(elements);
  let webMcpAvailability: WebMcpAvailability = "initializing";
  const refreshWebMcpGuide = wireWebMcpGuide(elements, () => webMcpAvailability);
  wireFileLoader(elements.loadFileButton, elements.loadFileInput, elements.editorContainer, shell);
  wireGeneralMenuActions(elements, editor, host, shell, app);

  let disposeWebMcp = () => {};
  void fetchText("lua_api_for_ai.md").then(async (apiDocsContent) => {
    const registration = await registerWebMcpTools(document, {
      getScriptText: () => editor.getValue(),
      setScriptText: (scriptText: string) => shell.setCurrentScript(scriptText),
      checkScriptText: async (scriptText: string) => {
        const report = await runScriptingCheck(scriptText, {
          preludeSource,
          fontNames: bundledFontEntries.map((font) => font.family),
        });
        const errors = report.checks
          .filter((check) => !check.ok)
          .map((check) => `${check.label}: ${check.message || "failed"}`);
        return {
          success: report.ok,
          errors: errors.length > 0 ? errors : report.details,
        };
      },
      captureCurrentFrame: async () => {
        const blob = await app.captureCurrentFrameImage();
        return blob === undefined ? undefined : encodeBlobForWebMcp(blob);
      },
      exportVideo: (format: "webm" | "mp4") => app.exportVideo(format),
      listSampleScripts: async () => {
        const catalog = await fetchSampleCatalog();
        return catalog.map(({ id, title, description }) => ({ id, title, description }));
      },
      loadSampleScript: async (sampleId: string) => {
        const catalog = await fetchSampleCatalog();
        const found = catalog.find((item) => item.id === sampleId);
        if (found !== undefined) {
          return shell.switchToSample(found);
        }
        return false;
      },
      apiDocsContent,
    });
    webMcpAvailability = registration.availability;
    disposeWebMcp = registration.dispose;
    refreshWebMcpGuide();
    if (registration.error !== undefined) {
      console.warn(`failed to register WebMCP tools: ${String(registration.error)}`);
    }
  }).catch((error: unknown) => {
    webMcpAvailability = "failed";
    refreshWebMcpGuide();
    console.warn(`failed to prepare WebMCP tools: ${String(error)}`);
  });

  // notifySceneChanged already persists through WebHostAdapter; this just
  // covers the unload edge case where the debounced save hasn't fired yet.
  window.addEventListener("beforeunload", () => {
    disposeWebMcp();
    saveStoredScene(shell.scriptId, scene, computeSourceHash(editor.getValue()));
  });
}

// "All" plus every distinct category present in the fetched catalog (in
// catalog order, so reference/showcase/gallery rather than alphabetical).
function collectSampleTabs(samples: SampleEntry[]): string[] {
  const categories: string[] = [];
  for (const sample of samples) {
    if (!categories.includes(sample.category)) {
      categories.push(sample.category);
    }
  }
  return ["all", ...categories];
}

// Builds the preview area of a gallery card: a thumbnail that only
// starts downloading once the card actually scrolls into view, plus a play
// button that swaps in the <video> on demand.
//
// Neither asset is referenced until it is needed. The thumbnail's `src` is
// assigned by the caller's IntersectionObserver rather than at construction,
// and the video element is created only on the first play, so opening the
// browser costs one request per visible card and none at all for the video.
function createSamplePreview(
  sample: SampleEntry,
  observer: IntersectionObserver,
): HTMLElement | undefined {
  let preview: HTMLElement | undefined;
  if (sample.thumbnailUrl !== undefined) {
    const container = document.createElement("span");
    container.className = "sample-card-preview";

    const thumbnail = document.createElement("img");
    thumbnail.className = "sample-card-thumbnail";
    thumbnail.alt = "";
    thumbnail.loading = "lazy";
    thumbnail.dataset.thumbnailUrl = sample.thumbnailUrl;
    container.appendChild(thumbnail);
    observer.observe(thumbnail);

    if (sample.videoUrl !== undefined) {
      const playButton = document.createElement("span");
      playButton.className = "sample-card-play";
      playButton.setAttribute("role", "button");
      playButton.setAttribute("aria-label", "Play preview");
      playButton.textContent = "▶";
      // The card itself loads the script into the editor; playing a preview
      // must not also do that, so the click stops here.
      playButton.addEventListener("click", (event) => {
        event.stopPropagation();
        event.preventDefault();
        playSamplePreview(container, sample.videoUrl as string);
      });
      container.appendChild(playButton);
    }
    preview = container;
  }
  return preview;
}

// Replaces the thumbnail with a playing <video>. The element is created here
// rather than up front so the video is only ever fetched for a sample the
// viewer explicitly asked to watch.
function playSamplePreview(container: HTMLElement, videoUrl: string): void {
  const video = document.createElement("video");
  video.className = "sample-card-video";
  video.src = videoUrl;
  video.controls = true;
  video.autoplay = true;
  video.loop = true;
  video.muted = true;
  video.playsInline = true;
  // Clicks inside the native controls would otherwise bubble to the card and
  // load the script out from under the viewer.
  video.addEventListener("click", (event) => {
    event.stopPropagation();
  });
  container.replaceChildren(video);
}

// Assigns each thumbnail's `src` the first time its card becomes visible
// inside the grid, then stops watching it. Without this every card in the
// catalog would fetch its image as soon as the browser opened, however far
// down the grid it sat.
function createThumbnailObserver(grid: HTMLElement): IntersectionObserver {
  return new IntersectionObserver(
    (observedEntries, self) => {
      for (const observed of observedEntries) {
        const thumbnail = observed.target as HTMLImageElement;
        const thumbnailUrl = thumbnail.dataset.thumbnailUrl;
        if (observed.isIntersecting && thumbnailUrl !== undefined) {
          thumbnail.src = thumbnailUrl;
          self.unobserve(thumbnail);
        }
      }
    },
    // The grid is its own scroll container, so viewport-relative observation
    // would treat every card as visible; the root must be the grid itself.
    { root: grid, rootMargin: "200px" },
  );
}

// Wires the sample browser overlay opened from the hamburger menu: a search
// box, category tabs (all / reference / showcase / gallery,
// driven by whatever categories the fetched catalog actually contains), and a
// card grid. Replaces the old flat <select> now that samples span every
// bundled category rather than just showcase (see writeSampleCatalog in
// esbuild.config.mjs).
//
// Gallery entries are fetched separately and appended, so a slow or failed
// gallery fetch never delays or breaks the bundled samples.
async function wireSampleBrowser(elements: RequiredElements, shell: WebSimulatorShell): Promise<void> {
  const galleryEntriesPromise = fetchGalleryCatalog();
  let samples: SampleEntry[];
  try {
    samples = await fetchSampleCatalog();
  } catch (error) {
    console.warn(`failed to load sample catalog: ${String(error)}`);
    elements.openSampleBrowserButton.setAttribute("disabled", "true");
    return;
  }

  let tabs = collectSampleTabs(samples);
  let activeTab = "all";
  let galleryMerged = false;

  // Replaced on every render so a stale observer never holds on to the
  // elements the previous render discarded.
  let thumbnailObserver = createThumbnailObserver(elements.sampleBrowserGrid);

  const renderGrid = () => {
    const query = elements.sampleBrowserSearch.value.trim().toLowerCase();
    const visibleSamples = samples.filter(
      (sample) => (activeTab === "all" || sample.category === activeTab) && sampleMatchesQuery(sample, query),
    );

    thumbnailObserver.disconnect();
    thumbnailObserver = createThumbnailObserver(elements.sampleBrowserGrid);

    elements.sampleBrowserGrid.replaceChildren();
    if (visibleSamples.length === 0) {
      const empty = document.createElement("div");
      empty.className = "sample-browser-empty";
      empty.textContent = t("samples.noMatch");
      elements.sampleBrowserGrid.appendChild(empty);
      return;
    }
    for (const sample of visibleSamples) {
      // A <div> rather than a <button>: the card holds its own interactive
      // children (the preview's play control, the submission link), and
      // nesting those inside a button is invalid HTML that browsers handle
      // inconsistently. The button role and key handler below keep it
      // reachable by keyboard.
      const card = document.createElement("div");
      card.className = "sample-card";
      card.tabIndex = 0;
      card.setAttribute("role", "button");

      const preview = createSamplePreview(sample, thumbnailObserver);
      if (preview !== undefined) {
        card.appendChild(preview);
      }

      const category = document.createElement("span");
      category.className = "sample-card-category";
      category.textContent = sample.category;
      card.appendChild(category);

      const name = document.createElement("span");
      name.className = "sample-card-name";
      name.textContent = formatSampleCardName(sample);
      card.appendChild(name);

      const metaBadges = [
        sample.author !== "" ? sample.author : undefined,
        sample.version !== "" ? `v${sample.version}` : undefined,
        sample.apiLevel !== undefined ? `API ${sample.apiLevel}` : undefined,
      ].filter((badgeText) => badgeText !== undefined);
      if (metaBadges.length > 0) {
        const meta = document.createElement("span");
        meta.className = "sample-card-meta";
        for (const badgeText of metaBadges) {
          const badge = document.createElement("span");
          badge.className = "sample-card-badge";
          badge.textContent = badgeText;
          meta.appendChild(badge);
        }
        card.appendChild(meta);
      }

      if (sample.description !== "") {
        const description = document.createElement("span");
        description.className = "sample-card-description";
        description.textContent = sample.description;
        card.appendChild(description);
      }

      // Gallery entries link back to the submission they came from. The
      // link opens in a new tab and, like the play button, must not also
      // load the script into the editor.
      if (sample.sourceUrl !== undefined) {
        const sourceLink = document.createElement("a");
        sourceLink.className = "sample-card-source";
        sourceLink.href = sample.sourceUrl;
        sourceLink.target = "_blank";
        sourceLink.rel = "noopener noreferrer";
        sourceLink.textContent = t("samples.viewSubmission");
        sourceLink.addEventListener("click", (event) => {
          event.stopPropagation();
        });
        card.appendChild(sourceLink);
      }

      // Gallery scripts are fetched on open, so this can fail on a network
      // error; the overlay stays up in that case rather than closing onto an
      // editor that never received the script.
      const openSample = () => {
        shell
          .switchToSample(sample)
          .then((switched) => {
            if (switched) {
              pushBrowserSampleUrl(sample.id);
              elements.sampleBrowserOverlay.classList.remove("visible");
            }
          })
          .catch((error: unknown) => {
            console.warn(`failed to open sample ${sample.name}: ${String(error)}`);
            card.classList.add("sample-card-failed");
          });
      };
      card.addEventListener("click", openSample);
      card.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          openSample();
        }
      });
      elements.sampleBrowserGrid.appendChild(card);
    }
  };

  const renderTabs = () => {
    elements.sampleBrowserTabs.replaceChildren();
    for (const tab of tabs) {
      const tabButton = document.createElement("button");
      tabButton.type = "button";
      tabButton.className = tab === activeTab ? "sample-browser-tab active" : "sample-browser-tab";
      tabButton.textContent = tab;
      tabButton.addEventListener("click", () => {
        activeTab = tab;
        for (const otherTabButton of elements.sampleBrowserTabs.children) {
          otherTabButton.classList.toggle("active", otherTabButton.textContent === tab);
        }
        renderGrid();
      });
      elements.sampleBrowserTabs.appendChild(tabButton);
    }
  };

  renderTabs();

  const mergeGalleryEntries = async (): Promise<void> => {
    const galleryEntries = await galleryEntriesPromise;
    if (!galleryMerged) {
      galleryMerged = true;
      if (galleryEntries.length > 0) {
        samples = [...samples, ...galleryEntries];
      }
      tabs = collectSampleTabs(samples);
      renderTabs();
      renderGrid();
    }
  };

  const findSample = async (sampleId: string): Promise<SampleEntry | undefined> => {
    let sample = samples.find((candidate) => candidate.id === sampleId);
    if (sample === undefined && !galleryMerged) {
      await mergeGalleryEntries();
      sample = samples.find((candidate) => candidate.id === sampleId);
    }
    return sample;
  };

  const openSampleFromCurrentUrl = async (): Promise<void> => {
    const sampleId = readSampleIdFromUrl(window.location.href);
    if (sampleId === undefined) {
      await shell.showDefaultScript();
    } else {
      const sample = await findSample(sampleId);
      if (sample === undefined) {
        console.warn(`sample URL does not match a catalog entry: ${sampleId}`);
        await shell.showDefaultScript();
      } else {
        try {
          await shell.switchToSample(sample);
        } catch (error) {
          console.warn(`failed to open sample URL ${sampleId}: ${String(error)}`);
          await shell.showDefaultScript();
        }
      }
    }
  };

  window.addEventListener("popstate", () => {
    void openSampleFromCurrentUrl();
  });
  await openSampleFromCurrentUrl();

  // Gallery entries come from a separate repository over the network. Start
  // rendering bundled samples immediately, then append the gallery whenever
  // its already-running request finishes.
  void mergeGalleryEntries();

  elements.sampleBrowserSearch.addEventListener("input", renderGrid);
  elements.openSampleBrowserButton.addEventListener("click", () => {
    elements.sampleBrowserOverlay.classList.add("visible");
    elements.sampleBrowserSearch.value = "";
    renderGrid();
    elements.sampleBrowserSearch.focus();
  });
  elements.closeSampleBrowserButton.addEventListener("click", () => {
    elements.sampleBrowserOverlay.classList.remove("visible");
  });
  elements.sampleBrowserOverlay.addEventListener("click", (event) => {
    if (event.target === elements.sampleBrowserOverlay) {
      elements.sampleBrowserOverlay.classList.remove("visible");
    }
  });

  renderGrid();
}

function renderScriptingCheckReport(elements: RequiredElements, report: ScriptingCheckReport): void {
  elements.scriptingCheckStatus.className = report.ok
    ? "scripting-check-status scripting-check-success"
    : "scripting-check-status scripting-check-failure";
  elements.scriptingCheckStatus.textContent = report.ok
    ? "Scripting is working correctly."
    : "Scripting check failed.";

  const checkList = document.createElement("div");
  checkList.className = "scripting-check-list";
  for (const check of report.checks) {
    const row = document.createElement("div");
    row.className = check.ok ? "scripting-check-row check-ok" : "scripting-check-row check-failed";

    const marker = document.createElement("span");
    marker.className = "scripting-check-marker";
    marker.textContent = check.ok ? "✓" : "✕";

    const content = document.createElement("span");
    const label = document.createElement("strong");
    label.textContent = check.label;
    content.appendChild(label);
    if (check.message !== undefined) {
      const message = document.createElement("span");
      message.className = "scripting-check-message";
      message.textContent = check.message;
      content.appendChild(message);
    }
    row.append(marker, content);
    checkList.appendChild(row);
  }

  elements.scriptingCheckBody.replaceChildren(checkList);
  if (report.details.length > 0) {
    const details = document.createElement("details");
    details.className = "scripting-check-details";
    const summary = document.createElement("summary");
    summary.textContent = t("check.environmentDetails");
    const output = document.createElement("pre");
    output.textContent = report.details.join("\n");
    details.append(summary, output);
    elements.scriptingCheckBody.appendChild(details);
  }
}

// Runs the bundled diagnostic in a disposable engine. Unlike opening a
// sample, this never replaces the editor buffer or switches the active scene.
function wireScriptingCheck(
  elements: RequiredElements,
  preludeSource: string,
  fontNames: readonly string[],
): void {
  let running = false;

  elements.openScriptingCheckButton.addEventListener("click", () => {
    elements.scriptingCheckOverlay.classList.add("visible");
    if (running) {
      return;
    }

    running = true;
    elements.scriptingCheckStatus.className = "scripting-check-status";
    elements.scriptingCheckStatus.textContent = t("check.running");
    elements.scriptingCheckBody.replaceChildren();

    fetch(kScriptingCheckUri)
      .then(async (response) => {
        if (!response.ok) {
          throw new Error(`failed to load diagnostic (${response.status})`);
        }
        return runScriptingCheck(await response.text(), {
          preludeSource,
          fontNames,
          wasmUri: kWasmUri,
        });
      })
      .then((report) => renderScriptingCheckReport(elements, report))
      .catch((error: unknown) => {
        renderScriptingCheckReport(elements, {
          ok: false,
          checks: [
            {
              label: "Scripting check",
              ok: false,
              message: error instanceof Error ? error.message : String(error),
            },
          ],
          details: [],
        });
      })
      .finally(() => {
        running = false;
      });
  });

  elements.closeScriptingCheckButton.addEventListener("click", () => {
    elements.scriptingCheckOverlay.classList.remove("visible");
  });
  elements.scriptingCheckOverlay.addEventListener("click", (event) => {
    if (event.target === elements.scriptingCheckOverlay) {
      elements.scriptingCheckOverlay.classList.remove("visible");
    }
  });
}

// Shared by the API reference and third-party notices modals: both are a
// button that reveals an overlay, lazily fetch their Markdown once, and
// close on the close button or an overlay-background click.
function wireMarkdownViewer(
  openButton: HTMLElement,
  closeButton: HTMLElement,
  overlay: HTMLElement,
  body: HTMLElement,
  fetchMarkdown: () => Promise<string>,
  failureMessage: (error: unknown) => string,
): void {
  let loaded = false;
  openButton.addEventListener("click", () => {
    overlay.classList.add("visible");
    if (!loaded) {
      loaded = true;
      fetchMarkdown()
        .then(async (markdown) => {
          body.innerHTML = await marked.parse(markdown);
        })
        .catch((error: unknown) => {
          body.textContent = failureMessage(error);
        });
    }
  });
  closeButton.addEventListener("click", () => {
    overlay.classList.remove("visible");
  });
  overlay.addEventListener("click", (event) => {
    if (event.target === overlay) {
      overlay.classList.remove("visible");
    }
  });
}

// Opens the published user manual's API reference page in a new tab, rather
// than re-rendering the same Markdown in an in-app modal.
function wireDocViewer(elements: RequiredElements): void {
  // The gallery is browsed in-app, but submitting to it happens on GitHub,
  // so this is the one path out to the repository itself.
  elements.openGalleryRepoButton.addEventListener("click", () => {
    window.open(kGalleryRepositoryUrl, "_blank", "noopener");
  });
  elements.openManualButton.addEventListener("click", () => {
    const url = navigator.language.startsWith("ja") ? kManualUrl.ja : kManualUrl.en;
    window.open(url, "_blank", "noopener");
  });
  elements.openDocsButton.addEventListener("click", () => {
    const url = publishedApiReferenceUrl(navigator.language.startsWith("ja") ? "ja" : "en");
    window.open(url, "_blank", "noopener");
  });
}

function wireAiReferenceActions(elements: RequiredElements, app: SimulatorApp): void {
  const loadAiReference = createAiReferenceLoader();
  elements.downloadAiReferenceButton.addEventListener("click", () => {
    void loadAiReference()
      .then((reference) => {
        downloadTextFile(kAiReferenceFileName, reference, "text/markdown;charset=utf-8");
      })
      .catch((error: unknown) => {
        console.warn(`failed to download AI API reference: ${String(error)}`);
      });
  });
  elements.copyAiReferenceButton.addEventListener("click", () => {
    void loadAiReference()
      .then(async (reference) => {
        if (typeof navigator.clipboard?.writeText !== "function") {
          throw new Error("clipboard access requires a secure context (https:// or localhost)");
        }
        await navigator.clipboard.writeText(reference);
        app.showScriptCopyResult(true);
      })
      .catch((error: unknown) => {
        app.showScriptCopyResult(false);
        console.warn(`failed to copy AI API reference: ${String(error)}`);
      });
  });
}

// The select reflects the locale i18n resolved at startup (a stored choice, or
// the browser's language on a first visit), and switching it relabels the UI in
// place. Static markup is handled by applyStaticTranslations; the panels that
// build their own DOM subscribe through onLocaleChange themselves.
function wireLanguageSelect(elements: RequiredElements): void {
  applyStaticTranslations();
  elements.languageSelect.value = getLocale();
  elements.languageSelect.addEventListener("change", () => {
    setLocale(elements.languageSelect.value as Locale);
  });
  onLocaleChange(() => {
    applyStaticTranslations();
  });
}

function wireLicensesViewer(elements: RequiredElements): void {
  wireMarkdownViewer(
    elements.openLicensesButton,
    elements.closeLicensesButton,
    elements.licensesViewerOverlay,
    elements.licensesViewerBody,
    fetchThirdPartyNotices,
    (error) => `Failed to load third-party notices: ${String(error)}`,
  );
}

function renderWebMcpGuideBody(container: HTMLElement, availability: WebMcpAvailability): void {
  container.innerHTML = renderWebMcpGuideContent(availability);
}

function wireWebMcpGuide(
  elements: RequiredElements,
  getAvailability: () => WebMcpAvailability,
): () => void {
  const refresh = () => {
    if (elements.webmcpGuideOverlay.classList.contains("visible")) {
      renderWebMcpGuideBody(elements.webmcpGuideBody, getAvailability());
    }
  };
  const setOpen = (open: boolean) => {
    if (open) {
      renderWebMcpGuideBody(elements.webmcpGuideBody, getAvailability());
    }
    elements.webmcpGuideOverlay.classList.toggle("visible", open);
  };
  elements.openWebmcpGuideButton.addEventListener("click", () => setOpen(true));
  elements.closeWebmcpGuideButton.addEventListener("click", () => setOpen(false));
  elements.webmcpGuideOverlay.addEventListener("click", (event) => {
    if (event.target === elements.webmcpGuideOverlay) {
      setOpen(false);
    }
  });

  onLocaleChange(refresh);
  return refresh;
}

// Wires the hamburger menu's general-purpose editing actions: Copy/Paste
// Script (clipboard) and Save Script/Export WebM (downloads). These mirror
// the equivalent actions already reachable elsewhere in the UI (the
// simulator toolbar's Copy Script button, the timeline's record button) so
// they're single entry points, not separate implementations.
function wireGeneralMenuActions(
  elements: RequiredElements,
  editor: Monaco.editor.IStandaloneCodeEditor,
  host: WebHostAdapter,
  shell: WebSimulatorShell,
  app: SimulatorApp,
): void {
  elements.copyScriptButton.addEventListener("click", () => {
    host.copyScript();
  });

  elements.pasteScriptButton.addEventListener("click", () => {
    const switchGeneration = shell.beginClipboardLoad();
    navigator.clipboard
      .readText()
      .then(async (text) => {
        await shell.loadFromClipboardText(text, switchGeneration);
      })
      .catch((error: unknown) => {
        console.warn(`failed to read clipboard: ${String(error)}`);
      });
  });

  elements.newScriptButton.addEventListener("click", () => {
    shell.createNewScript().catch((error: unknown) => {
      console.warn(`failed to create new script: ${String(error)}`);
    });
  });

  elements.saveFileButton.addEventListener("click", () => {
    const scriptName =
      shell.scriptId
        .replace(/^(?:loaded|restored):/, "")
        .split("/")
        .at(-1)
        ?.replace(/\.lua$/, "") || "script";
    downloadTextFile(`${scriptName}.lua`, editor.getValue(), "text/x-lua");
  });

  elements.exportWebmButton.addEventListener("click", () => {
    void app.exportVideo("webm");
  });

  elements.exportMp4Button.addEventListener("click", () => {
    app.exportMp4Video();
  });

  // Wipes every persisted scene and setting (see clearAllStoredData), then
  // starts a fresh script the same way New Script does: continuing to edit
  // the current buffer would otherwise save right back into the storage
  // that was just cleared, undoing the clear on the next keystroke.
  elements.clearLocalDataButton.addEventListener("click", () => {
    clearAllStoredData();
    const clearCachesAndWorkers = async (): Promise<void> => {
      if ("caches" in window) {
        try {
          const keys = await caches.keys();
          await Promise.all(keys.map((key) => caches.delete(key)));
        } catch (error: unknown) {
          console.warn(`failed to clear caches: ${String(error)}`);
        }
      }
      if ("serviceWorker" in navigator) {
        try {
          const registrations = await navigator.serviceWorker.getRegistrations();
          await Promise.all(registrations.map((reg) => reg.unregister()));
        } catch (error: unknown) {
          console.warn(`failed to unregister service workers: ${String(error)}`);
        }
      }
    };
    clearCachesAndWorkers().finally(() => {
      window.location.reload();
    });
  });
}

function downloadTextFile(fileName: string, contents: string, mimeType: string): void {
  downloadBlob(fileName, new Blob([contents], { type: mimeType }));
}

function downloadBlob(fileName: string, blob: Blob): void {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

// Loads a script from a dropped/picked file, branching purely on file
// extension: a .lua file is loaded as-is, while a .webm recovers the Lua
// source embedded in it by WebHostAdapter.saveVideo (see
// shared/webmAttachment.ts). Shared by both the button + hidden
// <input type="file"> path and the editor drag-and-drop path below.
async function loadScriptFile(file: File, shell: WebSimulatorShell): Promise<void> {
  const isWebm = file.name.toLowerCase().endsWith(".webm") || file.type === "video/webm";
  if (isWebm) {
    const buffer = await file.arrayBuffer();
    const attachment = extractScriptAttachment(new Uint8Array(buffer));
    if (attachment === undefined) {
      console.warn(`no embedded Mug Typography script found in ${file.name}`);
      return;
    }
    await shell.loadFromFile(attachment.fileName, attachment.source);
  } else {
    await shell.loadFromFile(file.name, await file.text());
  }
}

// There is no VSCode-style explorer context menu in the web build, so a
// script or a recorded WebM is loaded either by picking a file through a
// hidden <input type="file"> or by dragging it onto the editor.
function wireFileLoader(
  button: HTMLElement,
  input: HTMLInputElement,
  dropTarget: HTMLElement,
  shell: WebSimulatorShell,
): void {
  button.addEventListener("click", () => {
    input.value = "";
    input.click();
  });
  input.addEventListener("change", () => {
    const file = input.files?.[0];
    if (file !== undefined) {
      loadScriptFile(file, shell).catch((error: unknown) => {
        console.warn(`failed to load file: ${String(error)}`);
      });
    }
  });

  // dragenter/dragover must both be prevented for drop to fire; dragleave
  // fires when entering a child element too, so the counter below only
  // clears the drag-over styling once the pointer truly leaves dropTarget
  // (including its Monaco-internal children).
  let dragDepth = 0;
  dropTarget.addEventListener("dragenter", (event) => {
    event.preventDefault();
    dragDepth += 1;
    dropTarget.classList.add("drag-over");
  });
  dropTarget.addEventListener("dragover", (event) => {
    event.preventDefault();
  });
  dropTarget.addEventListener("dragleave", () => {
    dragDepth = Math.max(0, dragDepth - 1);
    if (dragDepth === 0) {
      dropTarget.classList.remove("drag-over");
    }
  });
  dropTarget.addEventListener("drop", (event) => {
    event.preventDefault();
    dragDepth = 0;
    dropTarget.classList.remove("drag-over");
    const file = event.dataTransfer?.files[0];
    if (file !== undefined) {
      loadScriptFile(file, shell).catch((error: unknown) => {
        console.warn(`failed to load dropped file: ${String(error)}`);
      });
    }
  });
}

main().catch((error: unknown) => {
  showFatalError(error);
  console.error(error);
});
