import type { EvaluatedFrame } from "../core/frameEvaluator";
import { onLocaleChange, t } from "../shared/i18n";
import { renderFrame } from "../core/renderer";
import { resizeCanvasBuffer } from "../core/canvasBuffer";
import type { DisplayMode } from "../shared/sceneSchema";

const kMinimumZoom = 0.25;
const kMaximumZoom = 16;
const kWheelZoomSensitivity = 0.0015;
const kWheelLinePixels = 16;

export interface PreviewNavigationState {
  zoom: number;
  panX: number;
  panY: number;
}

export class PreviewNavigation {
  private state_: PreviewNavigationState = { zoom: 1, panX: 0, panY: 0 };

  state(): Readonly<PreviewNavigationState> {
    return this.state_;
  }

  zoomAt(factor: number, anchorX: number, anchorY: number): void {
    const previousZoom = this.state_.zoom;
    const nextZoom = Math.min(Math.max(previousZoom * factor, kMinimumZoom), kMaximumZoom);
    const appliedFactor = nextZoom / previousZoom;
    this.state_ = {
      zoom: nextZoom,
      panX: anchorX - (anchorX - this.state_.panX) * appliedFactor,
      panY: anchorY - (anchorY - this.state_.panY) * appliedFactor,
    };
  }

  panBy(deltaX: number, deltaY: number): void {
    this.state_ = {
      ...this.state_,
      panX: this.state_.panX + deltaX,
      panY: this.state_.panY + deltaY,
    };
  }

  reset(): void {
    this.state_ = { zoom: 1, panX: 0, panY: 0 };
  }
}

// Hosts the preview <canvas>, fitting the scene's pixel size into the
// available panel area (device-pixel-ratio aware).
export class PreviewCanvas {
  private readonly canvas: HTMLCanvasElement;
  private readonly context: CanvasRenderingContext2D;
  private readonly container: HTMLElement;
  private readonly resetButton: HTMLButtonElement;
  private readonly navigation = new PreviewNavigation();
  private readonly resizeObserver: ResizeObserver;
  private readonly removeLocaleListener: () => void;
  private dragPointerId: number | undefined;
  private dragClientX = 0;
  private dragClientY = 0;
  private lastFrame: EvaluatedFrame | undefined;
  private lastDisplayMode: DisplayMode = "box";
  private lastShowIndexLabels = false;

  constructor(container: HTMLElement, appendHeaderControl: (control: HTMLElement) => void) {
    this.container = container;
    this.container.classList.add("preview-viewport");
    this.canvas = document.createElement("canvas");
    this.canvas.className = "preview-canvas";
    container.appendChild(this.canvas);
    const context = this.canvas.getContext("2d");
    if (context === null) {
      throw new Error("2D canvas context unavailable");
    }
    this.context = context;
    this.resetButton = document.createElement("button");
    this.resetButton.className = "preview-navigation-reset";
    this.resetButton.type = "button";
    this.resetButton.title = t("preview.resetView");
    this.resetButton.setAttribute("aria-label", this.resetButton.title);
    this.resetButton.addEventListener("click", () => this.resetNavigation());
    appendHeaderControl(this.resetButton);
    this.installNavigationEvents();
    this.applyNavigation();
    this.removeLocaleListener = onLocaleChange(() => {
      this.resetButton.title = t("preview.resetView");
      this.resetButton.setAttribute("aria-label", this.resetButton.title);
    });
    this.resizeObserver = new ResizeObserver(() => this.renderLastFrame());
    this.resizeObserver.observe(this.container);
  }

  render(frame: EvaluatedFrame, displayMode: DisplayMode = "box", showIndexLabels = false): void {
    this.lastFrame = frame;
    this.lastDisplayMode = displayMode;
    this.lastShowIndexLabels = showIndexLabels;
    this.renderLastFrame();
  }

  dispose(): void {
    this.resizeObserver.disconnect();
    this.removeLocaleListener();
  }

  private renderLastFrame(): void {
    const frame = this.lastFrame;
    if (frame === undefined) {
      return;
    }
    const parent = this.canvas.parentElement;
    if (parent === null) {
      return;
    }
    const availableWidth = Math.max(parent.clientWidth - 16, 100);
    const availableHeight = Math.max(parent.clientHeight - 16, 100);
    const fitScale = Math.min(
      availableWidth / frame.canvasWidth,
      availableHeight / frame.canvasHeight,
    );
    const devicePixelRatio = window.devicePixelRatio || 1;
    const cssWidth = frame.canvasWidth * fitScale;
    const cssHeight = frame.canvasHeight * fitScale;
    const cssWidthText = `${cssWidth}px`;
    const cssHeightText = `${cssHeight}px`;
    if (this.canvas.style.width !== cssWidthText) {
      this.canvas.style.width = cssWidthText;
    }
    if (this.canvas.style.height !== cssHeightText) {
      this.canvas.style.height = cssHeightText;
    }
    resizeCanvasBuffer(
      this.canvas,
      cssWidth * devicePixelRatio,
      cssHeight * devicePixelRatio,
    );
    renderFrame(this.context, frame, fitScale * devicePixelRatio, {
      displayMode: this.lastDisplayMode,
      showIndexLabels: this.lastShowIndexLabels,
    });
  }

  private installNavigationEvents(): void {
    this.container.addEventListener("wheel", (event) => {
      event.preventDefault();
      const bounds = this.container.getBoundingClientRect();
      const anchorX = event.clientX - bounds.left - bounds.width / 2;
      const anchorY = event.clientY - bounds.top - bounds.height / 2;
      const deltaPixels = normalizeWheelDelta(event, bounds.height);
      this.navigation.zoomAt(Math.exp(-deltaPixels * kWheelZoomSensitivity), anchorX, anchorY);
      this.applyNavigation();
    }, { passive: false });
    this.container.addEventListener("pointerdown", (event) => {
      const supportedButton = event.button === 0 || event.button === 1;
      if (supportedButton) {
        this.dragPointerId = event.pointerId;
        this.dragClientX = event.clientX;
        this.dragClientY = event.clientY;
        this.container.setPointerCapture(event.pointerId);
        this.container.classList.add("is-panning");
        event.preventDefault();
      }
    });
    this.container.addEventListener("pointermove", (event) => {
      if (event.pointerId === this.dragPointerId) {
        this.navigation.panBy(event.clientX - this.dragClientX, event.clientY - this.dragClientY);
        this.dragClientX = event.clientX;
        this.dragClientY = event.clientY;
        this.applyNavigation();
      }
    });
    const finishPan = (event: PointerEvent): void => {
      if (event.pointerId === this.dragPointerId) {
        this.dragPointerId = undefined;
        this.container.classList.remove("is-panning");
        if (this.container.hasPointerCapture(event.pointerId)) {
          this.container.releasePointerCapture(event.pointerId);
        }
      }
    };
    this.container.addEventListener("pointerup", finishPan);
    this.container.addEventListener("pointercancel", finishPan);
    this.container.addEventListener("lostpointercapture", finishPan);
    this.container.addEventListener("dblclick", () => this.resetNavigation());
  }

  private resetNavigation(): void {
    this.navigation.reset();
    this.applyNavigation();
  }

  private applyNavigation(): void {
    const state = this.navigation.state();
    this.canvas.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.zoom})`;
    this.resetButton.textContent = `${Math.round(state.zoom * 100)}%`;
  }
}

function normalizeWheelDelta(event: WheelEvent, viewportHeight: number): number {
  let result = event.deltaY;
  if (event.deltaMode === WheelEvent.DOM_DELTA_LINE) {
    result *= kWheelLinePixels;
  } else if (event.deltaMode === WheelEvent.DOM_DELTA_PAGE) {
    result *= viewportHeight;
  }
  return result;
}
