// Fetches every browsable bundled sample script (reference / showcase,
// see shared/sampleDirectories.ts) the build step (esbuild.config.mjs:
// writeSampleCatalog) bakes into the web build's static assets. The VSCode
// extension has no equivalent: it reads samples/<category>/*.lua directly
// from the workspace instead.
//
// The API reference itself is not fetched here: it links out to the
// published user manual instead of re-rendering the same Markdown in-app
// (see publishedApiReferenceUrl in shared/apiReferenceSections.ts).

export interface SampleEntry {
  // Stable catalog identity used by shareable simulator URLs and per-sample
  // scene storage. It includes the category/path, so equal file names in
  // different categories never collide.
  id: string;
  category: string;
  name: string;
  // Bundled samples carry their script inline (the build bakes it in).
  // Gallery entries leave this undefined and set scriptUrl instead, so the
  // catalog stays an index rather than shipping every submission's source to
  // everyone who opens the browser; loadSampleSource resolves either form.
  source?: string;
  scriptUrl?: string;
  description: string;
  title: string;
  author: string;
  version: string;
  apiLevel?: number;
  // Absolute URLs to the preview media, present only on gallery entries
  // (see galleryCatalog.ts). Bundled samples ship no preview, so the card
  // renders as text only.
  thumbnailUrl?: string;
  videoUrl?: string;
  // Link back to the submission this sample landed through, shown on the
  // card so viewers can trace a gallery entry to its author's post.
  sourceUrl?: string;
}

export async function fetchSampleCatalog(): Promise<SampleEntry[]> {
  const response = await fetch("sample-catalog.json");
  if (!response.ok) {
    throw new Error(`failed to fetch sample catalog (${response.status})`);
  }
  return (await response.json()) as SampleEntry[];
}

// Resolves a sample's script whichever way the entry carries it: inline for
// bundled samples, over the network for gallery entries. Rejects when a
// gallery script cannot be fetched, so the caller can report it rather than
// silently opening an empty editor.
export async function loadSampleSource(sample: SampleEntry): Promise<string> {
  let source = sample.source;
  if (source === undefined) {
    if (sample.scriptUrl === undefined) {
      throw new Error(`sample ${sample.name} carries neither a source nor a script URL`);
    }
    const response = await fetch(sample.scriptUrl);
    if (!response.ok) {
      throw new Error(`failed to fetch ${sample.name} (${response.status})`);
    }
    source = await response.text();
  }
  return source;
}

// Label for a sample card. Bundled samples are stored as NN_slug.lua and are
// browsed in that numeric order, so the number is shown alongside the title to
// make a card findable from a file name (and vice versa). Gallery entries are
// user submissions whose file names carry no such number, so they are titled
// as-is.
//
// The number is read from the file name rather than the title because the file
// name is what orders the browser and what the repository is navigated by; a
// title is free text and may not mention it at all.
export function formatSampleCardName(sample: SampleEntry): string {
  const label = sample.title !== "" ? sample.title : sample.name;
  const numberMatch = /^(\d+)_/.exec(sample.name);
  return numberMatch === null ? label : `${numberMatch[1]}. ${label}`;
}

// Decides whether a sample matches the browser's search box. Everything the
// card puts on screen is searchable, so anything a viewer can read there is
// also something they can type. That includes the badges: a gallery fills up
// with entries from people rather than topics, and "who made this" or "which
// API level does this need" are as natural to search as a title.
//
// Version and API level are matched both bare and as their badges spell them
// ("v1.0", "API 3"), since either is a reasonable thing to type after reading
// one off a card. `query` is expected already lowercased and trimmed.
export function sampleMatchesQuery(sample: SampleEntry, query: string): boolean {
  const version = sample.version === "" ? "" : `${sample.version} v${sample.version}`;
  const apiLevel = sample.apiLevel === undefined ? "" : `${sample.apiLevel} API ${sample.apiLevel}`;
  return [sample.name, sample.title, sample.author, version, apiLevel, sample.description]
    .join(" ")
    .toLowerCase()
    .includes(query);
}
