import { parseHexColor } from "./luaCompletionContext";
import type { Rgba } from "./sceneSchema";

export interface RecommendedColorCode {
  startOffset: number;
  endOffset: number;
  color: Rgba;
  includesAlpha: boolean;
}

const kRecommendLinePattern = /^\s*--\s*@recommend(?:\.|\s+)(.*)$/i;
const kRecommendedColorPattern =
  /\b(bg|background|fill|fill_color|gradient|gradient_color)\s+(?:(checkerboard|checker|solid)\s+)?(#[0-9a-fA-F]{6}(?:[0-9a-fA-F]{2})?)\b/gi;

export function findRecommendedColorCodes(source: string): RecommendedColorCode[] {
  const result: RecommendedColorCode[] = [];
  const linePattern = /[^\r\n]*(?:\r\n|\n|\r|$)/g;
  let lineMatch: RegExpExecArray | null;
  while ((lineMatch = linePattern.exec(source)) !== null && lineMatch[0].length > 0) {
    const lineWithEnding = lineMatch[0];
    const line = lineWithEnding.replace(/[\r\n]+$/, "");
    const trimmed = line.trimStart();
    if (trimmed !== "") {
      if (/^--\[\[/.test(trimmed) || !/^--/.test(trimmed)) {
        break;
      }
      const recommendMatch = kRecommendLinePattern.exec(line);
      if (recommendMatch !== null) {
        const body = recommendMatch[1];
        const bodyStart = recommendMatch[0].length - body.length;
        kRecommendedColorPattern.lastIndex = 0;
        let colorMatch: RegExpExecArray | null;
        while ((colorMatch = kRecommendedColorPattern.exec(body)) !== null) {
          const hex = colorMatch[3];
          const color = parseHexColor(hex);
          if (color !== undefined) {
            const hexStartInMatch = colorMatch[0].lastIndexOf(hex);
            const startOffset = lineMatch.index + bodyStart + colorMatch.index + hexStartInMatch;
            result.push({
              startOffset,
              endOffset: startOffset + hex.length,
              color,
              includesAlpha: hex.length === 9,
            });
          }
        }
      }
    }
  }
  return result;
}

export function formatHexColor(color: Rgba, includeAlpha: boolean): string {
  const toHex = (value: number): string =>
    Math.round(Math.min(Math.max(value, 0), 1) * 255)
      .toString(16)
      .padStart(2, "0");
  const alpha = includeAlpha ? toHex(color.a) : "";
  return `#${toHex(color.r)}${toHex(color.g)}${toHex(color.b)}${alpha}`;
}
