import type { DisplayMode, PartMode } from "../shared/sceneSchema";
import { onLocaleChange, t } from "../shared/i18n";
import {
  createBoxIcon,
  createCheckIcon,
  createContourIcon,
  createCopyIcon,
  createFixedPartsIcon,
  createGlyphIcon,
  createMoreIcon,
  createResetLayoutIcon,
  createWarningIcon,
} from "./icons";

export interface ToolbarState {
  displayMode: DisplayMode;
  partMode: PartMode;
  partsPerCharacter: number;
}

export interface ToolbarCallbacks {
  onSettingsChanged: (state: ToolbarState) => void;
  onCopyScript?: () => void;
  onResetLayout?: () => void;
}

// Compact command bar for preview-level controls. Frequently used controls
// stay visible as fixed-size icons; infrequent layout actions live in the
// overflow menu so localization never changes the bar's geometry.
export class Toolbar {
  private static readonly copyFeedbackDurationMilliseconds = 1500;

  private readonly bar: HTMLDivElement;
  private readonly viewportControls: HTMLDivElement;
  private readonly displayButtons = new Map<DisplayMode, HTMLButtonElement>();
  private readonly partButtons = new Map<PartMode, HTMLButtonElement>();
  private readonly partCountInput: HTMLInputElement;
  private readonly topologyStatus: HTMLSpanElement;
  private readonly copyScriptButton: HTMLButtonElement | undefined;
  private readonly moreActionsButton: HTMLButtonElement | undefined;
  private readonly overflowMenu: HTMLDivElement | undefined;
  private readonly resetLayoutButton: HTMLButtonElement | undefined;
  private readonly resetLayoutLabel: HTMLSpanElement | undefined;
  private readonly removeLocaleListener: () => void;
  private copyFeedbackTimer: ReturnType<typeof setTimeout> | undefined;

  constructor(
    container: HTMLElement,
    private readonly state: ToolbarState,
    private readonly callbacks: ToolbarCallbacks,
  ) {
    this.bar = document.createElement("div");
    this.bar.className = "toolbar";

    this.viewportControls = document.createElement("div");
    this.viewportControls.className = "toolbar-control-group toolbar-viewport-controls";

    const displaySegment = this.createSegment("toolbar-display-segment");
    this.displayButtons.set(
      "glyph",
      this.createModeButton(createGlyphIcon(), () => this.setDisplayMode("glyph")),
    );
    this.displayButtons.set(
      "box",
      this.createModeButton(createBoxIcon(), () => this.setDisplayMode("box")),
    );
    displaySegment.append(...this.displayButtons.values());

    const partSegment = this.createSegment("toolbar-part-segment");
    this.partButtons.set(
      "contour",
      this.createModeButton(createContourIcon(), () => this.setPartMode("contour")),
    );
    this.partButtons.set(
      "fixed",
      this.createModeButton(createFixedPartsIcon(), () => this.setPartMode("fixed")),
    );
    partSegment.append(...this.partButtons.values());

    this.partCountInput = document.createElement("input");
    this.partCountInput.className = "toolbar-part-count";
    this.partCountInput.type = "number";
    this.partCountInput.min = "1";
    this.partCountInput.max = "16";
    this.partCountInput.value = String(state.partsPerCharacter);
    this.partCountInput.addEventListener("change", () => {
      const count = Math.max(1, Math.min(16, Number(this.partCountInput.value) || 1));
      this.partCountInput.value = String(count);
      this.state.partsPerCharacter = count;
      this.notify();
    });
    this.viewportControls.append(displaySegment, partSegment, this.partCountInput);

    this.topologyStatus = document.createElement("span");
    this.topologyStatus.className = "topology-status";
    this.topologyStatus.setAttribute("aria-live", "polite");

    const actions = document.createElement("div");
    actions.className = "toolbar-control-group toolbar-actions";
    if (this.callbacks.onCopyScript !== undefined) {
      this.copyScriptButton = this.createIconButton("toolbar-copy-script-button");
      this.copyScriptButton.appendChild(createCopyIcon());
      this.copyScriptButton.addEventListener("click", () => {
        this.callbacks.onCopyScript?.();
      });
      actions.appendChild(this.copyScriptButton);
    }

    if (this.callbacks.onResetLayout !== undefined) {
      const overflow = document.createElement("div");
      overflow.className = "toolbar-overflow";
      this.moreActionsButton = this.createIconButton("toolbar-more-actions-button");
      this.moreActionsButton.appendChild(createMoreIcon());
      this.moreActionsButton.setAttribute("aria-haspopup", "menu");
      this.moreActionsButton.setAttribute("aria-expanded", "false");
      this.moreActionsButton.addEventListener("click", (event) => {
        event.stopPropagation();
        this.setOverflowMenuOpen(this.overflowMenu?.hidden ?? true);
      });

      this.overflowMenu = document.createElement("div");
      this.overflowMenu.className = "toolbar-overflow-menu";
      this.overflowMenu.setAttribute("role", "menu");
      this.overflowMenu.hidden = true;
      this.overflowMenu.addEventListener("click", (event) => event.stopPropagation());

      this.resetLayoutButton = document.createElement("button");
      this.resetLayoutButton.type = "button";
      this.resetLayoutButton.className = "toolbar-menu-item toolbar-reset-ui-button";
      this.resetLayoutButton.setAttribute("role", "menuitem");
      this.resetLayoutButton.appendChild(createResetLayoutIcon());
      this.resetLayoutLabel = document.createElement("span");
      this.resetLayoutButton.appendChild(this.resetLayoutLabel);
      this.resetLayoutButton.addEventListener("click", () => {
        this.setOverflowMenuOpen(false);
        this.callbacks.onResetLayout?.();
      });
      this.overflowMenu.appendChild(this.resetLayoutButton);
      overflow.append(this.moreActionsButton, this.overflowMenu);
      actions.appendChild(overflow);
      document.addEventListener("click", this.closeOverflowMenu);
      document.addEventListener("keydown", this.closeOverflowMenuOnEscape);
    }

    this.bar.append(this.viewportControls, this.topologyStatus, actions);
    container.appendChild(this.bar);
    this.updatePartCountVisibility();
    this.updateToggleStates();
    this.applyTranslations();
    this.removeLocaleListener = onLocaleChange(() => this.applyTranslations());
  }

  dispose(): void {
    if (this.copyFeedbackTimer !== undefined) {
      clearTimeout(this.copyFeedbackTimer);
      this.copyFeedbackTimer = undefined;
    }
    this.removeLocaleListener();
    document.removeEventListener("click", this.closeOverflowMenu);
    document.removeEventListener("keydown", this.closeOverflowMenuOnEscape);
  }

  showCopyResult(success: boolean): void {
    if (this.copyScriptButton !== undefined) {
      if (this.copyFeedbackTimer !== undefined) {
        clearTimeout(this.copyFeedbackTimer);
      }
      this.copyScriptButton.classList.toggle("copy-succeeded", success);
      this.copyScriptButton.classList.toggle("copy-failed", !success);
      this.copyScriptButton.replaceChildren(success ? createCheckIcon() : createWarningIcon());
      const feedback = success ? t("toolbar.copied") : t("toolbar.copyFailed");
      this.setAccessibleLabel(this.copyScriptButton, feedback);
      this.copyFeedbackTimer = setTimeout(() => {
        this.restoreCopyButton();
        this.copyFeedbackTimer = undefined;
      }, Toolbar.copyFeedbackDurationMilliseconds);
    }
  }

  addLeadingControl(control: HTMLElement): void {
    control.classList.add("toolbar-leading-control");
    this.viewportControls.prepend(control);
  }

  setTopology(characterCount: number, partCount: number): void {
    this.topologyStatus.textContent = `${characterCount} chars · ${partCount} parts`;
  }

  applyState(state: ToolbarState): void {
    this.state.displayMode = state.displayMode;
    this.state.partMode = state.partMode;
    this.state.partsPerCharacter = state.partsPerCharacter;
    this.partCountInput.value = String(state.partsPerCharacter);
    this.updatePartCountVisibility();
    this.updateToggleStates();
  }

  private createSegment(className: string): HTMLDivElement {
    const segment = document.createElement("div");
    segment.className = `toolbar-segment ${className}`;
    segment.setAttribute("role", "group");
    return segment;
  }

  private createModeButton(icon: SVGSVGElement, onClick: () => void): HTMLButtonElement {
    const button = this.createIconButton("toolbar-mode-button");
    button.appendChild(icon);
    button.addEventListener("click", onClick);
    return button;
  }

  private createIconButton(className: string): HTMLButtonElement {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `toolbar-icon-button ${className}`;
    return button;
  }

  private setDisplayMode(displayMode: DisplayMode): void {
    this.state.displayMode = displayMode;
    this.updateToggleStates();
    this.notify();
  }

  private setPartMode(partMode: PartMode): void {
    this.state.partMode = partMode;
    this.updatePartCountVisibility();
    this.updateToggleStates();
    this.notify();
  }

  private updatePartCountVisibility(): void {
    this.partCountInput.hidden = this.state.partMode !== "fixed";
  }

  private updateToggleStates(): void {
    for (const [displayMode, button] of this.displayButtons) {
      const selected = displayMode === this.state.displayMode;
      button.classList.toggle("active", selected);
      button.setAttribute("aria-pressed", String(selected));
    }
    for (const [partMode, button] of this.partButtons) {
      const selected = partMode === this.state.partMode;
      button.classList.toggle("active", selected);
      button.setAttribute("aria-pressed", String(selected));
    }
  }

  private applyTranslations(): void {
    const glyphButton = this.displayButtons.get("glyph");
    const boxButton = this.displayButtons.get("box");
    const contourButton = this.partButtons.get("contour");
    const fixedButton = this.partButtons.get("fixed");
    if (glyphButton !== undefined) {
      this.setAccessibleLabel(glyphButton, t("toolbar.displayGlyph"));
    }
    if (boxButton !== undefined) {
      this.setAccessibleLabel(boxButton, t("toolbar.displayBox"));
    }
    if (contourButton !== undefined) {
      this.setAccessibleLabel(contourButton, t("toolbar.partsContours"));
    }
    if (fixedButton !== undefined) {
      this.setAccessibleLabel(fixedButton, t("toolbar.partsFixed"));
    }
    this.setAccessibleLabel(this.partCountInput, t("toolbar.partsPerCharacter"));
    if (this.copyScriptButton !== undefined && this.copyFeedbackTimer === undefined) {
      this.setAccessibleLabel(this.copyScriptButton, t("toolbar.copyScriptTooltip"));
    }
    if (this.moreActionsButton !== undefined) {
      this.setAccessibleLabel(this.moreActionsButton, t("toolbar.moreActions"));
    }
    if (this.resetLayoutButton !== undefined && this.resetLayoutLabel !== undefined) {
      this.setAccessibleLabel(this.resetLayoutButton, t("toolbar.resetLayoutTooltip"));
      this.resetLayoutLabel.textContent = t("toolbar.resetLayout");
    }
  }

  private restoreCopyButton(): void {
    if (this.copyScriptButton !== undefined) {
      this.copyScriptButton.classList.remove("copy-succeeded", "copy-failed");
      this.copyScriptButton.replaceChildren(createCopyIcon());
      this.setAccessibleLabel(this.copyScriptButton, t("toolbar.copyScriptTooltip"));
    }
  }

  private setAccessibleLabel(element: HTMLElement, label: string): void {
    element.title = label;
    element.setAttribute("aria-label", label);
  }

  private setOverflowMenuOpen(open: boolean): void {
    if (this.overflowMenu !== undefined && this.moreActionsButton !== undefined) {
      this.overflowMenu.hidden = !open;
      this.moreActionsButton.setAttribute("aria-expanded", String(open));
    }
  }

  private readonly closeOverflowMenu = (): void => {
    this.setOverflowMenuOpen(false);
  };

  private readonly closeOverflowMenuOnEscape = (event: KeyboardEvent): void => {
    if (event.key === "Escape") {
      this.setOverflowMenuOpen(false);
      this.moreActionsButton?.focus();
    }
  };

  private notify(): void {
    this.callbacks.onSettingsChanged(this.state);
  }
}
