const kSampleQueryParameter = "sample";

export function readSampleIdFromUrl(href: string): string | undefined {
  let result: string | undefined;
  try {
    const value = new URL(href).searchParams.get(kSampleQueryParameter);
    if (value !== null && value !== "") {
      result = value;
    }
  } catch {
    // An invalid URL does not select a sample.
  }
  return result;
}

export function buildUrlForSample(href: string, sampleId: string | undefined): string {
  const url = new URL(href);
  if (sampleId === undefined) {
    url.searchParams.delete(kSampleQueryParameter);
  } else {
    url.searchParams.set(kSampleQueryParameter, sampleId);
  }
  return `${url.pathname}${url.search}${url.hash}`;
}
