// Fetches the user-submitted sample catalog from the gallery repository at
// runtime, as a separate step from the bundled catalog (sampleCatalog.ts).
//
// Gallery entries are not baked into this build on purpose. They land in
// their own public repository through an Issue -> approve -> auto-PR flow, so
// new submissions appear in the simulator as soon as they are merged there,
// with no rebuild or redeploy of this application. Keeping them out of the
// build also keeps user-submitted scripts out of this repository's test
// suite, where a broken submission would otherwise turn CI red.
//
// raw.githubusercontent.com serves `Access-Control-Allow-Origin: *`, so the
// cross-origin fetch from the published simulator needs no proxy. The catalog
// is a build artifact of that repository's approve workflow: it is rewritten
// on every merge, so this only ever reads it.

import type { SampleEntry } from "./sampleCatalog";

// The repository keeps its original name; only the vocabulary moved to
// "gallery", and renaming it would break existing issue and pull
// request links for no functional gain.
const kGalleryRepository = "mug-lab-3/mug-typography-community";
const kGalleryBranch = "main";
const kGalleryBaseUrl = `https://raw.githubusercontent.com/${kGalleryRepository}/${kGalleryBranch}`;

export const kGalleryCategory = "gallery";

// Where submissions are opened, linked from the app menu. Derived from the
// same constant the catalog is fetched from, so the two can never drift.
export const kGalleryRepositoryUrl = `https://github.com/${kGalleryRepository}`;

// Mirrors the entry shape the gallery repository's catalog generator
// writes. Paths are repository-relative there and resolved to absolute URLs
// here, so the catalog stays valid regardless of where it is served from.
//
// The catalog is an index: it names each script's path rather than carrying
// its body, so opening the sample browser costs one small request instead of
// every submission's source.
interface GalleryCatalogEntry {
  name: string;
  scriptPath: string;
  description: string;
  title: string;
  author: string;
  version: string;
  apiLevel?: number;
  thumbnailPath?: string;
  videoPath?: string;
  sourceUrl?: string;
}

// A submission is skipped rather than failing the whole catalog: one
// malformed entry must not empty the gallery tab.
function toSampleEntry(entry: GalleryCatalogEntry): SampleEntry | undefined {
  let result: SampleEntry | undefined;
  if (typeof entry.name === "string" && typeof entry.scriptPath === "string") {
    result = {
      id: entry.scriptPath,
      category: kGalleryCategory,
      name: entry.name,
      // Left unset on purpose: the script is fetched only when the viewer
      // opens this sample (see loadSampleSource).
      scriptUrl: resolveAssetUrl(entry.scriptPath),
      description: entry.description ?? "",
      title: entry.title ?? "",
      author: entry.author ?? "",
      version: entry.version ?? "",
      apiLevel: entry.apiLevel,
      thumbnailUrl: resolveAssetUrl(entry.thumbnailPath),
      videoUrl: resolveAssetUrl(entry.videoPath),
      sourceUrl: entry.sourceUrl,
    };
  }
  return result;
}

function resolveAssetUrl(assetPath: string | undefined): string | undefined {
  return assetPath === undefined || assetPath === "" ? undefined : `${kGalleryBaseUrl}/${assetPath}`;
}

// Resolves to an empty list rather than rejecting when the gallery
// repository is unreachable, so an offline or rate-limited fetch degrades to
// "no gallery entries" instead of breaking the sample browser entirely.
export async function fetchGalleryCatalog(): Promise<SampleEntry[]> {
  let entries: SampleEntry[] = [];
  try {
    const response = await fetch(`${kGalleryBaseUrl}/catalog.json`);
    if (response.ok) {
      const rawEntries = (await response.json()) as GalleryCatalogEntry[];
      if (Array.isArray(rawEntries)) {
        entries = rawEntries
          .map(toSampleEntry)
          .filter((entry): entry is SampleEntry => entry !== undefined);
      }
    } else {
      console.warn(`failed to fetch gallery catalog (${response.status})`);
    }
  } catch (error) {
    console.warn(`failed to fetch gallery catalog: ${String(error)}`);
  }
  return entries;
}
