export interface WebMcpImage {
  data: string;
  mimeType: string;
}

export interface WebMcpSample {
  id: string;
  title: string;
  description: string;
}

export interface WebMcpProviderOptions {
  getScriptText: () => string;
  setScriptText: (scriptText: string) => void;
  checkScriptText: (scriptText: string) => Promise<{ success: boolean; errors: string[] }>;
  captureCurrentFrame: () => Promise<WebMcpImage | undefined>;
  exportVideo: (format: "webm" | "mp4") => Promise<boolean>;
  listSampleScripts: () => Promise<WebMcpSample[]>;
  loadSampleScript: (sampleId: string) => Promise<boolean>;
  apiDocsContent: string;
}

export type WebMcpAvailability = "initializing" | "available" | "unsupported" | "failed";

interface WebMcpToolResult {
  content: Array<
    | { type: "text"; text: string }
    | { type: "image"; data: string; mimeType: string }
  >;
  isError?: boolean;
}

interface WebMcpTool {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
  annotations?: {
    readOnlyHint?: boolean;
    destructiveHint?: boolean;
  };
  execute: (argumentsValue: Record<string, unknown>) => Promise<WebMcpToolResult> | WebMcpToolResult;
}

interface WebMcpModelContext {
  registerTool(
    tool: WebMcpTool,
    options?: { signal?: AbortSignal },
  ): Promise<void> | void;
}

type WebMcpDocument = Document & {
  modelContext?: WebMcpModelContext;
};

export interface WebMcpRegistration {
  availability: Exclude<WebMcpAvailability, "initializing">;
  dispose: () => void;
  error?: unknown;
}

function textResult(text: string, isError = false): WebMcpToolResult {
  return {
    content: [{ type: "text", text }],
    isError,
  };
}

function requiredString(argumentsValue: Record<string, unknown>, name: string): string {
  const value = argumentsValue[name];
  if (typeof value !== "string" || value.length === 0) {
    throw new TypeError(`${name} must be a non-empty string`);
  }
  return value;
}

function makeTools(options: WebMcpProviderOptions): WebMcpTool[] {
  return [
    {
      name: "get_api_reference",
      description: "Returns the complete Lua API reference that must be followed when editing MT Simulator scripts.",
      inputSchema: { type: "object", properties: {}, additionalProperties: false },
      annotations: { readOnlyHint: true },
      execute: () => textResult(options.apiDocsContent),
    },
    {
      name: "get_current_script",
      description: "Returns the Lua script currently open in the MT Simulator editor.",
      inputSchema: { type: "object", properties: {}, additionalProperties: false },
      annotations: { readOnlyHint: true },
      execute: () => textResult(options.getScriptText()),
    },
    {
      name: "set_script",
      description: "Replaces the current Lua script and refreshes the simulator preview. Read get_api_reference before calling this tool.",
      inputSchema: {
        type: "object",
        properties: {
          script: { type: "string", minLength: 1, description: "Complete Lua script text." },
        },
        required: ["script"],
        additionalProperties: false,
      },
      annotations: { readOnlyHint: false, destructiveHint: true },
      execute: (argumentsValue) => {
        options.setScriptText(requiredString(argumentsValue, "script"));
        return textResult("The script was updated and the preview reload was requested.");
      },
    },
    {
      name: "check_script",
      description: "Validates the supplied Lua script, or the current editor script when script is omitted.",
      inputSchema: {
        type: "object",
        properties: {
          script: { type: "string", description: "Optional Lua script text." },
        },
        additionalProperties: false,
      },
      annotations: { readOnlyHint: true },
      execute: async (argumentsValue) => {
        const script = typeof argumentsValue.script === "string"
          ? argumentsValue.script
          : options.getScriptText();
        const result = await options.checkScriptText(script);
        const message = result.success
          ? "Validation passed with zero errors."
          : `Validation failed with ${result.errors.length} error(s):\n${result.errors.join("\n")}`;
        return textResult(message, !result.success);
      },
    },
    {
      name: "capture_current_frame",
      description: "Captures the currently selected simulator frame at the scene's native resolution.",
      inputSchema: { type: "object", properties: {}, additionalProperties: false },
      annotations: { readOnlyHint: true },
      execute: async () => {
        const image = await options.captureCurrentFrame();
        let result: WebMcpToolResult;
        if (image === undefined) {
          result = textResult("The current frame could not be captured.", true);
        } else {
          result = {
            content: [{ type: "image", data: image.data, mimeType: image.mimeType }],
          };
        }
        return result;
      },
    },
    {
      name: "list_sample_scripts",
      description: "Lists sample scripts that can be loaded into the simulator.",
      inputSchema: { type: "object", properties: {}, additionalProperties: false },
      annotations: { readOnlyHint: true },
      execute: async () => textResult(JSON.stringify(await options.listSampleScripts(), null, 2)),
    },
    {
      name: "load_sample_script",
      description: "Loads a sample script by an ID returned from list_sample_scripts.",
      inputSchema: {
        type: "object",
        properties: {
          sampleId: { type: "string", minLength: 1, description: "Exact sample ID." },
        },
        required: ["sampleId"],
        additionalProperties: false,
      },
      annotations: { readOnlyHint: false, destructiveHint: true },
      execute: async (argumentsValue) => {
        const sampleId = requiredString(argumentsValue, "sampleId");
        const success = await options.loadSampleScript(sampleId);
        return textResult(
          success ? `Loaded sample '${sampleId}'.` : `Sample '${sampleId}' could not be loaded.`,
          !success,
        );
      },
    },
    {
      name: "export_video",
      description: "Encodes the selected timeline range and requests a browser download in WebM or MP4 format.",
      inputSchema: {
        type: "object",
        properties: {
          format: { type: "string", enum: ["webm", "mp4"], description: "Video format." },
        },
        required: ["format"],
        additionalProperties: false,
      },
      annotations: { readOnlyHint: false },
      execute: async (argumentsValue) => {
        const format = requiredString(argumentsValue, "format").toLowerCase();
        if (format !== "webm" && format !== "mp4") {
          throw new TypeError("format must be 'webm' or 'mp4'");
        }
        const success = await options.exportVideo(format);
        return textResult(
          success
            ? `${format.toUpperCase()} encoding finished and a browser download was requested.`
            : `${format.toUpperCase()} export could not be completed.`,
          !success,
        );
      },
    },
  ];
}

export async function registerWebMcpTools(
  targetDocument: Document,
  options: WebMcpProviderOptions,
): Promise<WebMcpRegistration> {
  const modelContext = (targetDocument as WebMcpDocument).modelContext;
  if (modelContext === undefined || typeof modelContext.registerTool !== "function") {
    return { availability: "unsupported", dispose: () => {} };
  }

  const controller = new AbortController();
  try {
    for (const tool of makeTools(options)) {
      await modelContext.registerTool(tool, { signal: controller.signal });
    }
    return {
      availability: "available",
      dispose: () => controller.abort(),
    };
  } catch (error: unknown) {
    controller.abort();
    return {
      availability: "failed",
      dispose: () => {},
      error,
    };
  }
}
