// Explicit anchors are shared by both locales, so links do not depend on a
// Markdown renderer's locale-specific heading-slug algorithm.
export interface ApiReferenceLocation {
  file: string;
  fragment: string;
}

export const apiReferenceLocations: Readonly<Record<string, ApiReferenceLocation>> = {
  callback: { file: "01_concepts.md", fragment: "section-callback" },
  context: { file: "02_ctx_reference.md", fragment: "section-context" },
  timeline: { file: "02_ctx_reference.md", fragment: "section-timeline" },
  font: { file: "02_ctx_reference.md", fragment: "section-font" },
  meta: { file: "02_ctx_reference.md", fragment: "section-meta" },
  script_inputs: { file: "02_ctx_reference.md", fragment: "section-inputs" },
  global: { file: "02_ctx_reference.md", fragment: "section-global" },
  camera: { file: "02_ctx_reference.md", fragment: "section-camera" },
  character: { file: "02_ctx_reference.md", fragment: "section-character" },
  part: { file: "02_ctx_reference.md", fragment: "section-part" },
  bounding_box: { file: "02_ctx_reference.md", fragment: "section-bounding-box" },
  output: { file: "02_ctx_reference.md", fragment: "section-output" },
  mt: { file: "03_mt_reference.md", fragment: "section-mt" },
  canvas: { file: "02_ctx_reference.md", fragment: "section-canvas" },
  // ctx.paths and the part/drawing path objects it hands out are all described
  // in the same ctx.paths section; there is no separate heading per object.
  path_context: { file: "02_ctx_reference.md", fragment: "section-path-context" },
  color: { file: "01_concepts.md", fragment: "section-color" },
};

export function apiReferenceLocation(section: string): ApiReferenceLocation | undefined {
  return apiReferenceLocations[section];
}

// The id VSCode's Markdown preview gives a heading. It ignores any id the
// author writes and derives one from the heading text: lowercased, stripped of
// punctuation and symbols, with whitespace turned into hyphens. Reproducing that
// is what lets a deep link land inside the rendered preview, so the extension
// never has to fall back to showing raw Markdown.
//
// The stripped set is Unicode "not a letter, digit, mark, or connector", which
// keeps Japanese headings intact while dropping backticks, dots and brackets.
export function headingSlug(headingText: string): string {
  return headingText
    .trim()
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\p{M}\p{Pc}\s-]/gu, "")
    .replace(/\s/g, "-");
}

// The preview id to scroll to for the given anchor, or undefined when the
// document does not carry that anchor.
//
// A standalone anchor introduces a heading, which is the exact landing point. An
// anchor inside a table row (the easing and path:* tables) has no heading of its
// own, so the heading the table sits under is used instead -- the row is then a
// short scroll away rather than a page away.
export function anchorPreviewFragment(document: string, anchor: string): string | undefined {
  const marker = `<a id="${anchor}"></a>`;
  const lines = document.split("\n");
  // Sub-headings such as "Arguments" and "Return value" repeat under every
  // entry, so their slugs collide and the preview would scroll to whichever
  // came first. Only a slug unique in the document can be scrolled to, which
  // means walking out to the nearest ancestor heading that qualifies.
  const slugCounts = new Map<string, number>();
  for (const line of lines) {
    const headingMatch = /^#{1,6}\s+(.*)$/.exec(line.trim());
    if (headingMatch !== null) {
      const slug = headingSlug(headingMatch[1]);
      slugCounts.set(slug, (slugCounts.get(slug) ?? 0) + 1);
    }
  }
  // The preview percent-encodes the fragment before matching it against the id
  // it rendered, and the id itself is left raw. A slug carrying non-ASCII (every
  // Japanese heading) therefore can never match and would leave the reader at
  // the top of the page, so such headings are not offered as landing points.
  const isReachable = (slug: string): boolean =>
    slugCounts.get(slug) === 1 && encodeURIComponent(slug) === slug;

  const headingStack: Array<{ level: number; slug: string }> = [];
  const nearestUniqueHeading = (): string | undefined => {
    let result: string | undefined;
    for (let depth = headingStack.length - 1; depth >= 0 && result === undefined; depth -= 1) {
      if (isReachable(headingStack[depth].slug)) {
        result = headingStack[depth].slug;
      }
    }
    return result;
  };

  let fragment: string | undefined;
  let enclosingHeading: string | undefined;
  for (let index = 0; index < lines.length && fragment === undefined; index += 1) {
    const headingMatch = /^(#{1,6})\s+(.*)$/.exec(lines[index].trim());
    if (headingMatch !== null) {
      const level = headingMatch[1].length;
      while (headingStack.length > 0 && headingStack[headingStack.length - 1].level >= level) {
        headingStack.pop();
      }
      headingStack.push({ level, slug: headingSlug(headingMatch[2]) });
      enclosingHeading = nearestUniqueHeading();
    }
    if (!lines[index].includes(marker)) {
      continue;
    }
    if (lines[index].trim() !== marker) {
      fragment = enclosingHeading;
      break;
    }
    for (let ahead = index + 1; ahead < lines.length; ahead += 1) {
      const text = lines[ahead].trim();
      // Sibling anchors share one heading, so they are stepped over.
      if (text.length === 0 || /^<a id="[^"]+"><\/a>$/.test(text)) {
        continue;
      }
      const introduced = /^#{1,6}\s+(.*)$/.exec(text);
      if (introduced === null) {
        fragment = enclosingHeading;
      } else {
        const slug = headingSlug(introduced[1]);
        fragment = isReachable(slug) ? slug : enclosingHeading;
      }
      break;
    }
  }
  return fragment;
}

// The published user manual renders all four reference documents into a single
// page via VitePress's @include, so every anchor below resolves on one URL and
// the source file name is not part of it. VSCode opens the Markdown files
// themselves and needs the file name, which is why callers there use
// ApiReferenceLocation.file instead.
const kPublishedApiReferenceUrl = {
  ja: "https://mug-lab-3.github.io/mug-typography-docs/scripting/api-reference",
  en: "https://mug-lab-3.github.io/mug-typography-docs/en/scripting/api-reference",
} as const;

export type ApiReferenceLocale = keyof typeof kPublishedApiReferenceUrl;

// `anchor` is a function's explicit anchor (LuaApiMember.reference.anchor) or a
// section fragment; omitting it opens the top of the reference.
export function publishedApiReferenceUrl(locale: ApiReferenceLocale, anchor?: string): string {
  const baseUrl = kPublishedApiReferenceUrl[locale];
  return anchor === undefined || anchor.length === 0 ? baseUrl : `${baseUrl}#${anchor}`;
}
