import type { MugMetadata } from "../../shared/luaCompletionContext";
import { createDefaultScene, restoreScene, type Scene } from "../../shared/sceneSchema";
import { chooseBundledFontForLanguage, isLocalFontAccessPath } from "./fontSources";

const kSceneStorageKeyPrefix = "mt-web-scene::";
// Shared by every localStorage key the web build owns (per-script scenes
// under kSceneStorageKeyPrefix, plus standalone settings like
// WebHostAdapter's "mt-web-loop-playback"), so clearAllStoredData below can
// wipe all of them without each new key needing its own removal line.
const kStoredDataKeyPrefix = "mt-web-";

export interface StoredSceneResult {
  scene: Scene;
  // True when nothing was found under this script id (or the stored entry
  // was corrupt), mirroring the VSCode extension's loadScene isNewScene
  // flag (see simulatorPanel.ts): callers use this to decide whether script
  // metadata (@duration, @recommend, ...) should be applied, since it must
  // never overwrite inspector values the user already adjusted and saved.
  isNewScene: boolean;
}

export function computeSourceHash(source: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < source.length; i += 1) {
    hash ^= source.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16);
}

// Minimal localStorage-backed scene persistence for the web build's initial
// milestone. A later step replaces this with IndexedDB (per-script quota is
// tighter under localStorage's ~5MB total budget); the call shape here is
// deliberately identical so that swap is a drop-in file replacement.
// `metadata` is only consulted to migrate scenes stored before the script's
// `@recommend text` and the bundled Japanese font existed (see restoreScene);
// a current scene ignores it. If `sourceHash` is provided and differs from the
// stored hash (e.g. sample or script updated), the cache is ignored.
export function loadStoredScene(
  scriptId: string,
  metadata?: MugMetadata,
  sourceHash?: string,
): StoredSceneResult {
  let scene = createDefaultScene();
  let isNewScene = true;
  try {
    const raw = localStorage.getItem(kSceneStorageKeyPrefix + scriptId);
    if (raw !== null) {
      const stored = JSON.parse(raw) as unknown;
      const storedSourceHash =
        isRecord(stored) && typeof stored.sourceHash === "string"
          ? stored.sourceHash
          : undefined;
      const isHashMatch =
        sourceHash === undefined || (storedSourceHash !== undefined && storedSourceHash === sourceHash);
      if (isHashMatch) {
        scene = restoreScene(stored, {
          metadata,
          fontForLanguage: fontToMigrateTo(stored, metadata),
        });
        isNewScene = false;
      }
    }
  } catch {
    // Corrupt or missing entry: fall back to defaults.
  }
  return { scene, isNewScene };
}

// Resolves the font a stored scene should be migrated to, for scenes saved
// while the web build shipped no CJK font: a Japanese script could only ever
// have been saved with a Latin font, which renders its text as missing glyphs.
//
// A font the user picked themselves through Local Font Access is left alone --
// it is an explicit choice and may well have CJK coverage -- as is a scene that
// already holds the bundled Japanese font.
function fontToMigrateTo(
  stored: unknown,
  metadata?: MugMetadata,
): { family: string; path: string } | undefined {
  const languageFont = chooseBundledFontForLanguage(metadata?.fontLang);
  const storedSettings = isRecord(stored) ? stored.settings : undefined;
  const storedPath = isRecord(storedSettings) ? storedSettings.fontPath : undefined;
  const keepsStoredFont =
    typeof storedPath === "string" &&
    (isLocalFontAccessPath(storedPath) || storedPath === languageFont?.path);
  let result: { family: string; path: string } | undefined;
  if (languageFont !== undefined && !keepsStoredFont) {
    result = { family: languageFont.family, path: languageFont.path };
  }
  return result;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function saveStoredScene(scriptId: string, scene: Scene, sourceHash?: string): void {
  const payload = sourceHash !== undefined ? { ...scene, sourceHash } : scene;
  localStorage.setItem(kSceneStorageKeyPrefix + scriptId, JSON.stringify(payload));
}

// Wipes every persisted scene and setting the web build has ever written
// (see kStoredDataKeyPrefix), for the "Clear Local Data" menu action.
// Collects keys before removing any of them since localStorage.key(index)
// shifts as entries are deleted mid-iteration.
export function clearAllStoredData(): void {
  const keysToRemove: string[] = [];
  for (let index = 0; index < localStorage.length; index += 1) {
    const key = localStorage.key(index);
    if (key !== null && key.startsWith(kStoredDataKeyPrefix)) {
      keysToRemove.push(key);
    }
  }
  for (const key of keysToRemove) {
    localStorage.removeItem(key);
  }
}
