import { getLocale, onLocaleChange, t } from "../shared/i18n";
import { kScriptApiLevel } from "../shared/scriptingApi";

const kPluginStoreUrl = "https://muglab3.booth.pm/items/8339678";
export const kRequiredPluginVersion = "5.2b";
const kInstallationUrl = {
  en: "https://mug-lab-3.github.io/mug-typography-docs/en/guide/installation",
  ja: "https://mug-lab-3.github.io/mug-typography-docs/guide/installation",
} as const;

// Keyed by the required plugin version as well as the API level, so raising the
// requirement within one API level still reaches users who dismissed the notice
// for the previous build. Slots gained in 5.2b are an example: same API level 8,
// but a script using them silently misbehaves on 5.2a.
export const kPluginCompatibilityConfirmationKey =
  `mt-web-plugin-compatibility-api-${kScriptApiLevel}-version-${kRequiredPluginVersion}-confirmed`;

function formatMessage(template: string): string {
  return template
    .replace("{apiLevel}", String(kScriptApiLevel))
    .replace("{pluginVersion}", kRequiredPluginVersion);
}

// Only this exact key counts. A confirmation stored for an earlier required
// version deliberately does not carry over, which is what re-shows the notice
// after the requirement moves.
function hasConfirmedPluginCompatibility(): boolean {
  return localStorage.getItem(kPluginCompatibilityConfirmationKey) === "true";
}

export function mountPluginCompatibilityNotice(parent: HTMLElement): () => void {
  if (hasConfirmedPluginCompatibility()) {
    return () => undefined;
  }

  const notice = document.createElement("aside");
  notice.className = "plugin-compatibility-notice";
  notice.setAttribute("role", "status");
  notice.setAttribute("aria-live", "polite");

  const header = document.createElement("div");
  header.className = "plugin-compatibility-notice-header";
  const icon = document.createElement("span");
  icon.className = "plugin-compatibility-notice-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.textContent = "↑";
  const title = document.createElement("strong");
  const badge = document.createElement("span");
  badge.className = "plugin-compatibility-notice-badge";
  badge.textContent = `API ${kScriptApiLevel}`;
  header.append(icon, title, badge);

  const message = document.createElement("p");
  message.className = "plugin-compatibility-notice-message";

  const links = document.createElement("div");
  links.className = "plugin-compatibility-notice-links";
  const storeLink = document.createElement("a");
  storeLink.href = kPluginStoreUrl;
  storeLink.target = "_blank";
  storeLink.rel = "noopener noreferrer";
  const installationLink = document.createElement("a");
  installationLink.target = "_blank";
  installationLink.rel = "noopener noreferrer";
  links.append(storeLink, installationLink);

  const confirmButton = document.createElement("button");
  confirmButton.className = "plugin-compatibility-notice-confirm";
  confirmButton.type = "button";

  const actions = document.createElement("div");
  actions.className = "plugin-compatibility-notice-actions";
  actions.append(links, confirmButton);

  notice.append(header, message, actions);
  parent.appendChild(notice);

  const updateLabels = () => {
    title.textContent = t("compatibility.title");
    message.textContent = formatMessage(t("compatibility.message"));
    storeLink.textContent = t("compatibility.getPlugin");
    installationLink.textContent = t("compatibility.installation");
    installationLink.href = kInstallationUrl[getLocale()];
    confirmButton.textContent = formatMessage(t("compatibility.confirm"));
  };
  updateLabels();
  const unsubscribe = onLocaleChange(updateLabels);
  const dispose = () => {
    unsubscribe();
    notice.remove();
  };

  confirmButton.addEventListener("click", () => {
    localStorage.setItem(kPluginCompatibilityConfirmationKey, "true");
    dispose();
  });

  return dispose;
}
