import type { WebLogLine } from "./webHostAdapter";

export type RevealEditorLine = (lineNumber: number) => void;

export function wireLogPanel(
  body: HTMLElement,
  clearButton: HTMLElement,
  revealEditorLine: RevealEditorLine,
): (line: WebLogLine) => void {
  clearButton.addEventListener("click", () => {
    body.replaceChildren();
  });

  return (line) => {
    const hasSourceLocation =
      line.level === "error" &&
      line.lineNumber !== undefined &&
      Number.isInteger(line.lineNumber) &&
      line.lineNumber > 0;
    const lineElement = document.createElement(hasSourceLocation ? "button" : "div");
    lineElement.className =
      line.level === "log" ? "log-panel-line" : `log-panel-line log-${line.level}`;
    lineElement.textContent = line.text;

    if (hasSourceLocation) {
      const lineNumber = line.lineNumber as number;
      lineElement.classList.add("log-panel-source-link");
      lineElement.setAttribute("type", "button");
      lineElement.setAttribute("title", `Go to line ${lineNumber}`);
      lineElement.addEventListener("click", () => {
        revealEditorLine(lineNumber);
      });
    }

    body.appendChild(lineElement);
    body.scrollTop = body.scrollHeight;
  };
}
