export interface CanvasBufferDimensions {
  width: number;
  height: number;
}

export function resizeCanvasBuffer(
  canvas: CanvasBufferDimensions,
  width: number,
  height: number,
): boolean {
  const nextWidth = Math.max(Math.round(width), 1);
  const nextHeight = Math.max(Math.round(height), 1);
  let resized = false;
  if (canvas.width !== nextWidth) {
    canvas.width = nextWidth;
    resized = true;
  }
  if (canvas.height !== nextHeight) {
    canvas.height = nextHeight;
    resized = true;
  }
  return resized;
}
