import { getLocale } from "../shared/i18n";
import type { WebMcpAvailability } from "./webMcpProvider";

interface StatusCopy {
  label: string;
  detail: string;
  color: string;
}

function getStatusCopy(availability: WebMcpAvailability, isJapanese: boolean): StatusCopy {
  const copies: Record<WebMcpAvailability, { ja: StatusCopy; en: StatusCopy }> = {
    initializing: {
      ja: { label: "確認中", detail: "WebMCP の利用可否を確認しています。", color: "#fbbf24" },
      en: { label: "Checking", detail: "Checking whether WebMCP is available.", color: "#fbbf24" },
    },
    available: {
      ja: { label: "公開準備完了", detail: "このブラウザでは WebMCP ツールを公開できます。", color: "#4ade80" },
      en: { label: "Ready to expose tools", detail: "This browser can expose WebMCP tools.", color: "#4ade80" },
    },
    unsupported: {
      ja: { label: "未対応", detail: "このブラウザでは WebMCP API が無効、または提供されていません。", color: "#fca5a5" },
      en: { label: "Unsupported", detail: "The WebMCP API is disabled or unavailable in this browser.", color: "#fca5a5" },
    },
    failed: {
      ja: { label: "利用不可", detail: "WebMCP ツールを登録できませんでした。やり方 A を利用してください。", color: "#fca5a5" },
      en: { label: "Unavailable", detail: "WebMCP tools could not be registered. Use Method A instead.", color: "#fca5a5" },
    },
  };
  return isJapanese ? copies[availability].ja : copies[availability].en;
}

function renderChromeEnablementHelp(
  availability: WebMcpAvailability,
  isJapanese: boolean,
): string {
  if (availability === "available" || availability === "initializing") {
    return "";
  }
  if (isJapanese) {
    return `
      <div style="margin-top: 10px; padding-top: 9px; border-top: 1px solid #fca5a533; color: #dddddd;">
        <strong>Chrome で実験機能を有効にしてください：</strong>
        <ol style="margin: 5px 0 0; padding-left: 20px;">
          <li>アドレスバーに <code>chrome://flags/#enable-webmcp-testing</code> を入力します。</li>
          <li><strong>WebMCP for testing</strong> を <strong>Enabled</strong> に変更します。</li>
          <li>画面下部の <strong>Relaunch</strong> を押して Chrome を再起動します。</li>
          <li>シミュレーターを開き直し、状態が「公開準備完了」になることを確認します。</li>
        </ol>
      </div>`;
  }
  return `
    <div style="margin-top: 10px; padding-top: 9px; border-top: 1px solid #fca5a533; color: #dddddd;">
      <strong>Enable the experimental feature in Chrome:</strong>
      <ol style="margin: 5px 0 0; padding-left: 20px;">
        <li>Enter <code>chrome://flags/#enable-webmcp-testing</code> in the address bar.</li>
        <li>Set <strong>WebMCP for testing</strong> to <strong>Enabled</strong>.</li>
        <li>Click <strong>Relaunch</strong> to restart Chrome.</li>
        <li>Reopen the simulator and confirm that its status changes to Available.</li>
      </ol>
    </div>`;
}

export function renderWebMcpGuideContent(availability: WebMcpAvailability): string {
  const isJapanese = getLocale() === "ja";
  const status = getStatusCopy(availability, isJapanese);
  const chromeEnablementHelp = renderChromeEnablementHelp(availability, isJapanese);
  const statusPanel = `
    <div style="border: 1px solid ${status.color}55; background: ${status.color}12; border-radius: 6px; padding: 9px 11px; margin-bottom: 14px;">
      <strong style="color: ${status.color};">● ${status.label}</strong>
      <span style="color: #bbbbbb; margin-left: 6px;">${status.detail}</span>
      ${chromeEnablementHelp}
    </div>`;

  if (isJapanese) {
    return `
      <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; color: #cccccc; line-height: 1.6; font-size: 13px;">
        <h3 style="margin: 0 0 8px; font-size: 16px; color: var(--mt-accent, #a855f7);">🤖 AI連携ガイド</h3>
        <section style="background: #252526; border: 1px solid #3c3c3c; border-radius: 8px; padding: 14px 16px; margin-bottom: 14px;">
          <h4 style="margin: 0 0 8px; color: #38bdf8;">やり方 A：通常の AI チャットを使う</h4>
          <ol style="margin: 0; padding-left: 20px; color: #bbbbbb;">
            <li>メニューの「AI向けAPI仕様書をダウンロード」または「コピー」を選びます。</li>
            <li>仕様書を ChatGPT や Claude に渡し、作りたいアニメーションを指示します。</li>
            <li>生成された Lua スクリプトをエディタへ貼り付けます。</li>
          </ol>
        </section>

        <details style="background: #1e1e1e; border: 1px solid #333333; border-radius: 6px; padding: 8px 12px; color: #aaaaaa;">
          <summary style="cursor: pointer; font-weight: 600;">やり方 B：ブラウザ AI から直接操作（対応予定）</summary>
          <div style="margin-top: 8px; color: #bbbbbb;">
            <div style="border: 1px solid #f59e0b66; background: #f59e0b12; border-radius: 6px; padding: 9px 11px; margin-bottom: 12px; color: #fcd34d;">
              <strong>現在は一般利用できません。</strong> 対応するブラウザ AI が提供された後に利用できる予定です。WebMCP 自体も実験的な Web API であり、仕様や設定方法が変わる可能性があります。
            </div>
            ${statusPanel}
            <h4 style="margin: 10px 0 8px; color: #c084fc;">Chrome で準備機能を有効にする</h4>
            <ol style="margin: 0; padding-left: 20px;">
              <li>アドレスバーへ <code>chrome://flags/#enable-webmcp-testing</code> と入力します。</li>
              <li><strong>WebMCP for testing</strong> を <strong>Enabled</strong> にします。</li>
              <li><strong>Relaunch</strong> を押して Chrome を再起動します。</li>
              <li>シミュレーターを開き直し、状態が「公開準備完了」になればページ側の準備は完了です。</li>
            </ol>
            <p style="color: #999999; font-size: 12px;">フラグを有効にしても AI は追加されず、現時点ではシミュレーターを直接操作できません。Chrome の内部ページは、上記アドレスをアドレスバーへ直接入力してください。</p>
            <p>API仕様取得、現在のコード取得・更新・検査、現在フレームの画像取得、サンプル一覧・読込、WebM/MP4出力を提供します。</p>
            <p>動画出力はエンコード完了後にブラウザへダウンロードを要求します。保存先やダウンロード結果はブラウザが管理します。</p>
            <p>コード更新、サンプル読込、動画出力は画面の状態を変更します。AI ツールに表示される内容を確認してから許可してください。</p>
            <p style="margin-bottom: 0;"><code>document.modelContext.registerTool()</code> を使用し、クロスオリジンの独自メッセージ受信は行いません。</p>
          </div>
        </details>
      </div>
    `;
  }

  return `
    <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; color: #cccccc; line-height: 1.6; font-size: 13px;">
      <h3 style="margin: 0 0 8px; font-size: 16px; color: var(--mt-accent, #a855f7);">🤖 AI Integration Guide</h3>
      <section style="background: #252526; border: 1px solid #3c3c3c; border-radius: 8px; padding: 14px 16px; margin-bottom: 14px;">
        <h4 style="margin: 0 0 8px; color: #38bdf8;">Method A: Use a regular AI chat</h4>
        <ol style="margin: 0; padding-left: 20px; color: #bbbbbb;">
          <li>Download or copy the AI API Reference from the menu.</li>
          <li>Give the reference and your animation request to ChatGPT or Claude.</li>
          <li>Paste the generated Lua script into the editor.</li>
        </ol>
      </section>

      <details style="background: #1e1e1e; border: 1px solid #333333; border-radius: 6px; padding: 8px 12px; color: #aaaaaa;">
        <summary style="cursor: pointer; font-weight: 600;">Method B: Direct control from browser AI (planned)</summary>
        <div style="margin-top: 8px; color: #bbbbbb;">
          <div style="border: 1px solid #f59e0b66; background: #f59e0b12; border-radius: 6px; padding: 9px 11px; margin-bottom: 12px; color: #fcd34d;">
            <strong>Not currently available for general use.</strong> This method is planned for when compatible browser AI becomes available. WebMCP itself is experimental, and its specification and setup may change.
          </div>
          ${statusPanel}
          <h4 style="margin: 10px 0 8px; color: #c084fc;">Enable the preparatory feature in Chrome</h4>
          <ol style="margin: 0; padding-left: 20px;">
            <li>Enter <code>chrome://flags/#enable-webmcp-testing</code> in the address bar.</li>
            <li>Set <strong>WebMCP for testing</strong> to <strong>Enabled</strong>.</li>
            <li>Click <strong>Relaunch</strong> to restart Chrome.</li>
            <li>Reopen the simulator. The page is ready when the status changes to Ready to expose tools.</li>
          </ol>
          <p style="color: #999999; font-size: 12px;">Enabling the flag does not add an AI, so it cannot directly operate the simulator yet. Enter the Chrome internal address directly in the address bar.</p>
          <p>Tools provide the API reference, current script access and validation, current-frame capture, sample listing and loading, and WebM/MP4 export.</p>
          <p>Video export waits for encoding, then requests a browser download. The browser controls the destination and final download result.</p>
          <p>Script updates, sample loading, and video export change page state. Review each operation before approving it.</p>
          <p style="margin-bottom: 0;">Tools use <code>document.modelContext.registerTool()</code>; no custom cross-origin message listener is installed.</p>
        </div>
      </details>
    </div>
  `;
}
