import { FrameEvaluator } from "../../core/frameEvaluator";
import { ScriptEngine } from "../../core/luaEngine";
import { createDefaultScene } from "../../shared/sceneSchema";

export interface ScriptingCheckItem {
  label: string;
  ok: boolean;
  message?: string;
}

export interface ScriptingCheckReport {
  ok: boolean;
  checks: ScriptingCheckItem[];
  details: string[];
}

export interface ScriptingCheckOptions {
  preludeSource: string;
  fontNames: readonly string[];
  wasmUri?: string;
}

const kDiagnosticFrames = [0, 30];

// Runs the bundled environment diagnostic in a disposable Lua VM and scene.
// This deliberately does not use SimulatorApp: a check must never replace the
// editor buffer, alter the current preview, or persist a diagnostic scene.
export async function runScriptingCheck(
  source: string,
  options: ScriptingCheckOptions,
): Promise<ScriptingCheckReport> {
  const checks: ScriptingCheckItem[] = [];
  const details: string[] = [];
  let engine: ScriptEngine | undefined;

  try {
    engine = await ScriptEngine.create({
      preludeSource: options.preludeSource,
      wasmUri: options.wasmUri,
      log: (text) => details.push(text),
    });
    checks.push({ label: "Lua engine", ok: true });

    const loadResult = await engine.loadScript(source);
    checks.push({
      label: "Diagnostic script",
      ok: loadResult.ok,
      message: loadResult.message,
    });

    if (loadResult.ok) {
      for (const hookName of ["OnInitialize", "OnPreLayout", "OnLayout"]) {
        checks.push({
          label: hookName,
          ok: engine.hasHook(hookName),
          message: engine.hasHook(hookName) ? undefined : `${hookName} is not defined`,
        });
      }

      const evaluator = new FrameEvaluator(engine);
      evaluator.setFontNames(options.fontNames);
      const scene = createDefaultScene();

      const initializeResult = evaluator.initialize(scene);
      checks.push({
        label: "Initialization",
        ok: initializeResult.errors.length === 0,
        message: initializeResult.errors.join("\n") || undefined,
      });

      if (initializeResult.errors.length === 0) {
        const frameErrors = kDiagnosticFrames.flatMap((frame) => evaluator.evaluate(scene, frame).errors);
        checks.push({
          label: "Frame evaluation",
          ok: frameErrors.length === 0,
          message: frameErrors.join("\n") || undefined,
        });
      }
    }
  } catch (error) {
    checks.push({
      label: "Scripting runtime",
      ok: false,
      message: error instanceof Error ? error.message : String(error),
    });
  } finally {
    engine?.dispose();
  }

  return {
    ok: checks.length > 0 && checks.every((check) => check.ok),
    checks,
    details,
  };
}
