export function createInspectorCatalog(
  scene: Scene,
  characterCount: number,
  partCount: number,
  scriptInputs?: ScriptInputMetadata,
): InspectorSection[] {
  const baseSections = inspectorCatalog.flatMap((section) => {
    let result = [section];
    if (section.title === "Script Inputs") {
      const scriptInputSection = makeScriptInputSection(scriptInputs);
      result = scriptInputSection === undefined ? [] : [scriptInputSection];
    }
    return result;
  });
  const characterSections = scene.characters.slice(0, characterCount).map((_character, index) => ({
    page: "characters" as const,
    title: `Character ${index + 1}`,
    fields: makeCharacterFields(index),
  }));
  const partSections = scene.parts.slice(0, partCount).map((_part, index) => ({
    page: "parts" as const,
    title: `Part ${index + 1}`,
    fields: makePartFields(index),
  }));
  return [...baseSections, ...characterSections, ...partSections];
}

function makeScriptInputSection(metadata?: ScriptInputMetadata): InspectorSection | undefined {
  const fields: InspectorField[] = [];
  for (const [index, declaration] of metadata?.numbers.entries() ?? []) {
    if (declaration !== undefined) {
      fields.push(
        numberArrayItemField(
          declaration.label,
          "scriptInputs.numbers",
          (scene) => scene.scriptInputs.numbers,
          index,
          clampScriptInputNumber,
        ),
      );
    }
  }
  for (const [index, declaration] of metadata?.colors.entries() ?? []) {
    if (declaration !== undefined) {
      fields.push(
        colorArrayItemField(
          declaration.label,
          "scriptInputs.colors",
          (scene) => scene.scriptInputs.colors,
          index,
        ),
      );
    }
  }
  for (const [index, declaration] of metadata?.texts.entries() ?? []) {
    if (declaration !== undefined) {
      fields.push(
        textArrayItemField(
          declaration.label,
          "scriptInputs.texts",
          (scene) => scene.scriptInputs.texts,
          index,
        ),
      );
    }
  }
  return fields.length === 0
    ? undefined
    : {
        page: "simulator",
        title: "Script Inputs",
        initiallyOpen: true,
        fields,
      };
}

function makeCharacterFields(index: number): InspectorField[] {
  const root = `characters.${index}`;
  const character = (scene: Scene): CharacterScene => scene.characters[index];
  return [
    numberArrayItemField("Margin After", "global.margins", (scene) => scene.global.margins, index),
    numberField("Offset X", root, character, "offsetX"),
    numberField("Offset Y", root, character, "offsetY"),
    numberField("Pivot X", root, character, "pivotX"),
    numberField("Pivot Y", root, character, "pivotY"),
    numberField("Scale", root, character, "scale"),
    numberField("Stretch X", root, character, "stretchX"),
    numberField("Stretch Y", root, character, "stretchY"),
    numberField("Rotation", root, character, "rotation"),
    numberField("Z", root, character, "z"),
    numberField("Yaw", root, character, "yaw"),
    numberField("Pitch", root, character, "pitch"),
    numberField("Opacity", root, character, "opacity"),
    booleanField("Use individual color", root, character, "useColor"),
    enabledWhen(
      colorField("Color", root, character, "color"),
      (scene) => character(scene).useColor,
    ),
    booleanField("Use individual stroke", root, character, "useStroke"),
    enabledWhen(
      numberField("Stroke width", root, character, "strokeWidth"),
      (scene) => character(scene).useStroke,
    ),
    enabledWhen(
      numberField("Stroke gap", root, character, "strokeGap"),
      (scene) => character(scene).useStroke,
    ),
    enabledWhen(
      colorField("Stroke color", root, character, "strokeColor"),
      (scene) => character(scene).useStroke,
    ),
    enabledWhen(
      numberField("Outer stroke width", root, character, "outerStrokeWidth"),
      (scene) => character(scene).useStroke,
    ),
    enabledWhen(
      colorField("Outer stroke color", root, character, "outerStrokeColor"),
      (scene) => character(scene).useStroke,
    ),
    booleanField("Use individual shadow color", root, character, "useShadowColor"),
    enabledWhen(
      colorField("Shadow color", root, character, "shadowColor"),
      (scene) => character(scene).useShadowColor,
    ),
  ];
}

function makePartFields(index: number): InspectorField[] {
  const root = `parts.${index}`;
  const part = (scene: Scene): PartScene => scene.parts[index];
  return [
    numberField("Offset X", root, part, "offsetX"),
    numberField("Offset Y", root, part, "offsetY"),
    numberField("Pivot X", root, part, "pivotX"),
    numberField("Pivot Y", root, part, "pivotY"),
    numberField("Scale", root, part, "scale"),
    numberField("Stretch X", root, part, "stretchX"),
    numberField("Stretch Y", root, part, "stretchY"),
    numberField("Rotation", root, part, "rotation"),
    numberField("Z", root, part, "z"),
    numberField("Opacity", root, part, "opacity"),
    booleanField("Use individual color", root, part, "useColor"),
    enabledWhen(
      colorField("Color", root, part, "color"),
      (scene) => part(scene).useColor,
    ),
  ];
}

// Part yaw/pitch/stroke/shadow are script-only (no host parameter group backs them,
// unlike the character equivalents — see ScriptApiSchema's part.yaw/pitch/stroke/shadow
// descriptions): the real Fusion inspector never shows them, so this simulator's
// inspector must not either. They still work end to end through OnLayout scripts; they
// are just not editable by hand here, matching the host.
// These scene properties intentionally live outside the right-side inspector.
// Keeping the list explicit makes newly added properties fail the coverage
// test instead of silently disappearing from the simulator UI.
export const inspectorCatalogExclusions = new Set([
  "schemaVersion",
  "scriptInputs",
  "settings.partsPerCharacter",
  "settings.displayMode",
  "settings.partMode",
  "settings.fontPath",
  "parts.0.yaw",
  "parts.0.pitch",
  "parts.0.useStroke",
  "parts.0.strokeWidth",
  "parts.0.strokeGap",
  "parts.0.strokeColor",
  "parts.0.outerStrokeWidth",
  "parts.0.outerStrokeColor",
  "parts.0.useShadowColor",
  "parts.0.shadowColor",
]);

function positiveInteger(value: number): number {
  return Math.max(Math.round(value), 1);
}

function positiveNumber(value: number): number {
  return Math.max(value, 0.001);
}

function nonNegativeNumber(value: number): number {
  return Math.max(value, 0);
}

function clampScriptInputNumber(value: number): number {
  return Math.min(Math.max(value, kScriptInputNumberMinimum), kScriptInputNumberMaximum);
}
