// Mapping between the simulator's scene model (camelCase TS) and the Lua ctx
// data tables (snake_case, the script-facing API). The snake_case field names
// here are the script API contract shared with the host plugin's C++
// bindings — renaming one side without the other breaks user scripts.

import type {
  CameraScene,
  BoundingBoxScene,
  CharacterScene,
  GradientColorSpace,
  GlobalScene,
  PartScene,
  OutputScene,
  Rgba,
} from "../shared/sceneSchema";

export interface CtxGlobalFillData {
  color: Rgba;
  transparent: boolean;
}

export interface CtxGradientData {
  color_space: GradientColorSpace;
  end_color: Rgba;
  midpoint: number;
  angle: number;
  start_position: number;
  end_position: number;
}

export interface CtxGlobalStrokeData {
  width: number;
  gap: number;
  color: Rgba;
  outer_width: number;
  outer_color: Rgba;
  order: GlobalScene["strokeOrder"];
  join: GlobalScene["strokeJoin"];
  miter_limit: number;
}

export interface CtxGlobalShadowData {
  enabled: boolean;
  distance: number;
  angle: number;
  color: Rgba;
}

export interface CtxGlobalData {
  text: string;
  font_name: string;
  tracking: number;
  line_spacing: number;
  vertical: boolean;
  h_align: string;
  v_align: string;
  margins: number[];
  position_x: number;
  position_y: number;
  rotation: number;
  yaw: number;
  pitch: number;
  scale: number;
  stretch_x: number;
  stretch_y: number;
  pivot_x: number;
  pivot_y: number;
  opacity: number;
  fill: CtxGlobalFillData;
  gradient: CtxGradientData;
  stroke: CtxGlobalStrokeData;
  shadow: CtxGlobalShadowData;
}

export interface CtxCameraData {
  target_x: number;
  target_y: number;
  yaw: number;
  pitch: number;
  perspective: number;
  zoom: number;
  lens_shift_x: number;
  lens_shift_y: number;
}

export interface CtxCharacterData {
  readonly index?: number;
  readonly text?: string;
  readonly part_start?: number;
  readonly part_count?: number;
  readonly line_index?: number;
  readonly geometry?: CtxCharacterGeometryData;
  offset_x: number;
  offset_y: number;
  pivot_x: number;
  pivot_y: number;
  scale: number;
  stretch_x: number;
  stretch_y: number;
  rotation: number;
  z: number;
  yaw: number;
  pitch: number;
  opacity: number;
  fill: CtxIndividualFillData;
  stroke: CtxIndividualStrokeData;
  shadow: CtxIndividualShadowData;
}

export interface CtxIndividualFillData {
  use: boolean;
  color: Rgba;
}

export interface CtxIndividualStrokeData {
  use: boolean;
  width: number;
  gap: number;
  color: Rgba;
  outer_width: number;
  outer_color: Rgba;
}

export interface CtxIndividualShadowData {
  use: boolean;
  color: Rgba;
}

export interface CtxPartData {
  readonly index?: number;
  readonly character_index?: number;
  readonly index_in_character?: number;
  readonly geometry?: CtxPartGeometryData;
  offset_x: number;
  offset_y: number;
  pivot_x: number;
  pivot_y: number;
  scale: number;
  rotation: number;
  stretch_x: number;
  stretch_y: number;
  z: number;
  yaw: number;
  pitch: number;
  opacity: number;
  fill: CtxIndividualFillData;
  stroke: CtxIndividualStrokeData;
  shadow: CtxIndividualShadowData;
}

export interface CtxBoundingBoxData {
  enabled: boolean;
  draw_top: boolean;
  draw_bottom: boolean;
  draw_left: boolean;
  draw_right: boolean;
  color: Rgba;
  width: number;
  fill_enabled: boolean;
  fill_color: Rgba;
  fill_opacity: number;
  start_cap: BoundingBoxScene["startCap"];
  end_cap: BoundingBoxScene["endCap"];
  margin_x: number;
  margin_y: number;
  corner_radius: number;
  fill_offset_x: number;
  fill_offset_y: number;
  stroke_offset_x: number;
  stroke_offset_y: number;
}

export interface CtxOutputData {
  separation_enabled: boolean;
  render_mode: OutputScene["renderMode"];
  targets_1: string;
  targets_2: string;
  write_on_mode: OutputScene["writeOnMode"];
  write_on_start: number;
  write_on_end: number;
  reorder_parts: boolean;
  manual_order_enabled: boolean;
  manual_order_text: string;
  force_disable_3d_projection: boolean;
}

export interface CtxCanvasData {
  width: number;
  height: number;
  aspect_ratio: number;
  pixel_aspect_ratio: number;
}

export interface CtxTimelineData {
  available: boolean;
  start_frame: number;
  end_frame: number;
  duration_frames: number;
  duration_seconds: number;
  progress: number;
}

export interface CtxFontMetricsData {
  ascent: number;
  descent: number;
  line_height: number;
  units_per_em: number;
}

export interface CtxCharacterGeometryData {
  canvas_origin_x: number;
  canvas_origin_y: number;
  vertical_origin_x: number;
  vertical_origin_y: number;
  bounds_center_x: number;
  bounds_center_y: number;
  bounds_width: number;
  bounds_height: number;
  advance_x: number;
  advance_y: number;
}

export interface CtxPartGeometryData {
  local_center_x: number;
  local_center_y: number;
  canvas_center_x: number;
  canvas_center_y: number;
  bounds_center_x: number;
  bounds_center_y: number;
  bounds_width: number;
  bounds_height: number;
}

export interface CtxCapabilitiesData {
  has_3d: boolean;
}

export interface CtxMetaData {
  api_level: number;
  plugin_version: string;
  capabilities: CtxCapabilitiesData;
  limits: {
    max_characters: number;
    max_parts: number;
  };
  instance_seed: number;
}

export interface CtxScriptInputsData {
  numbers: number[];
  colors: Rgba[];
  texts: string[];
}

export interface BaseHookData {
  time: number;
  frame: number;
  fps: number;
  text: string;
  canvas: CtxCanvasData;
  fonts?: string[];
  timeline: CtxTimelineData;
  meta: CtxMetaData;
  inputs: CtxScriptInputsData;
  global: CtxGlobalData;
  camera: CtxCameraData;
}

export interface LayoutHookData {
  time: number;
  frame: number;
  fps: number;
  text: string;
  char_count: number;
  part_count: number;
  canvas: CtxCanvasData;
  fonts?: string[];
  timeline: CtxTimelineData;
  font: CtxFontMetricsData;
  meta: CtxMetaData;
  inputs: CtxScriptInputsData;
  global: CtxGlobalData;
  camera: CtxCameraData;
  chars: CtxCharacterData[];
  parts: CtxPartData[];
  bounding_box: CtxBoundingBoxData;
  output: CtxOutputData;
}

export interface InitializeHookData {
  canvas: CtxCanvasData;
  fonts: string[];
  meta: CtxMetaData;
  inputs: CtxScriptInputsData;
}

function cloneColor(color: Rgba): Rgba {
  return { r: color.r, g: color.g, b: color.b, a: color.a };
}

export function ctxToGlobal(data: CtxGlobalData): GlobalScene {
  return {
    text: data.text,
    fontName: data.font_name,
    tracking: data.tracking,
    lineSpacing: data.line_spacing,
    vertical: data.vertical,
    hAlign: data.h_align as GlobalScene["hAlign"],
    vAlign: data.v_align as GlobalScene["vAlign"],
    margins: Object.values(data.margins ?? []),
    positionX: data.position_x,
    positionY: data.position_y,
    rotation: data.rotation,
    yaw: data.yaw,
    pitch: data.pitch,
    scale: data.scale,
    stretchX: data.stretch_x,
    stretchY: data.stretch_y,
    pivotX: data.pivot_x,
    pivotY: data.pivot_y,
    opacity: data.opacity,
    color: cloneColor(data.fill.color),
    fillTransparent: data.fill.transparent,
    gradientColorSpace: data.gradient.color_space,
    gradientEndColor: cloneColor(data.gradient.end_color),
    gradientMidpoint: data.gradient.midpoint,
    gradientAngle: data.gradient.angle,
    gradientStart: data.gradient.start_position,
    gradientEnd: data.gradient.end_position,
    strokeWidth: data.stroke.width,
    strokeGap: data.stroke.gap,
    strokeColor: cloneColor(data.stroke.color),
    outerStrokeWidth: data.stroke.outer_width,
    outerStrokeColor: cloneColor(data.stroke.outer_color),
    strokeOrder: data.stroke.order,
    strokeJoin: data.stroke.join,
    strokeMiterLimit: data.stroke.miter_limit,
    shadowEnabled: data.shadow.enabled,
    shadowDistance: data.shadow.distance,
    shadowAngle: data.shadow.angle,
    shadowColor: cloneColor(data.shadow.color),
  };
}

export function globalToCtx(global: GlobalScene): CtxGlobalData {
  return {
    text: global.text,
    font_name: global.fontName,
    tracking: global.tracking,
    line_spacing: global.lineSpacing,
    vertical: global.vertical,
    h_align: global.hAlign,
    v_align: global.vAlign,
    margins: [...global.margins],
    position_x: global.positionX,
    position_y: global.positionY,
    rotation: global.rotation,
    yaw: global.yaw,
    pitch: global.pitch,
    scale: global.scale,
    stretch_x: global.stretchX,
    stretch_y: global.stretchY,
    pivot_x: global.pivotX,
    pivot_y: global.pivotY,
    opacity: global.opacity,
    fill: {
      color: cloneColor(global.color),
      transparent: global.fillTransparent,
    },
    gradient: {
      color_space: global.gradientColorSpace,
      end_color: cloneColor(global.gradientEndColor),
      midpoint: global.gradientMidpoint,
      angle: global.gradientAngle,
      start_position: global.gradientStart,
      end_position: global.gradientEnd,
    },
    stroke: {
      width: global.strokeWidth,
      gap: global.strokeGap,
      color: cloneColor(global.strokeColor),
      outer_width: global.outerStrokeWidth ?? 0,
      outer_color: cloneColor(global.outerStrokeColor ?? global.strokeColor),
      order: global.strokeOrder,
      join: global.strokeJoin,
      miter_limit: global.strokeMiterLimit,
    },
    shadow: {
      enabled: global.shadowEnabled,
      distance: global.shadowDistance,
      angle: global.shadowAngle,
      color: cloneColor(global.shadowColor),
    },
  };
}

export function cameraToCtx(camera: CameraScene): CtxCameraData {
  return {
    target_x: camera.targetX,
    target_y: camera.targetY,
    yaw: camera.yaw,
    pitch: camera.pitch,
    perspective: camera.perspective,
    zoom: camera.zoom,
    lens_shift_x: camera.lensShiftX,
    lens_shift_y: camera.lensShiftY,
  };
}

export function characterSceneToCtx(character: CharacterScene): CtxCharacterData {
  return {
    offset_x: character.offsetX,
    offset_y: character.offsetY,
    pivot_x: character.pivotX,
    pivot_y: character.pivotY,
    scale: character.scale,
    stretch_x: character.stretchX,
    stretch_y: character.stretchY,
    rotation: character.rotation,
    z: character.z,
    yaw: character.yaw,
    pitch: character.pitch,
    opacity: character.opacity,
    fill: {
      use: character.useColor,
      color: cloneColor(character.color),
    },
    stroke: {
      use: character.useStroke,
      width: character.strokeWidth,
      gap: character.strokeGap,
      color: cloneColor(character.strokeColor),
      outer_width: character.outerStrokeWidth ?? 0,
      outer_color: cloneColor(character.outerStrokeColor ?? character.strokeColor),
    },
    shadow: {
      use: character.useShadowColor,
      color: cloneColor(character.shadowColor),
    },
  };
}

export function partSceneToCtx(part: PartScene): CtxPartData {
  return {
    offset_x: part.offsetX,
    offset_y: part.offsetY,
    pivot_x: part.pivotX,
    pivot_y: part.pivotY,
    scale: part.scale,
    rotation: part.rotation,
    stretch_x: part.stretchX,
    stretch_y: part.stretchY,
    z: part.z,
    yaw: part.yaw,
    pitch: part.pitch,
    opacity: part.opacity,
    fill: {
      use: part.useColor,
      color: cloneColor(part.color),
    },
    stroke: {
      use: part.useStroke,
      width: part.strokeWidth,
      gap: part.strokeGap,
      color: cloneColor(part.strokeColor),
      outer_width: part.outerStrokeWidth ?? 0,
      outer_color: cloneColor(part.outerStrokeColor ?? part.strokeColor),
    },
    shadow: {
      use: part.useShadowColor,
      color: cloneColor(part.shadowColor),
    },
  };
}

export function boundingBoxToCtx(value: BoundingBoxScene): CtxBoundingBoxData {
  return {
    enabled: value.enabled,
    draw_top: value.drawTop,
    draw_bottom: value.drawBottom,
    draw_left: value.drawLeft,
    draw_right: value.drawRight,
    color: cloneColor(value.color),
    width: value.width,
    fill_enabled: value.fillEnabled,
    fill_color: cloneColor(value.fillColor),
    fill_opacity: value.fillOpacity,
    start_cap: value.startCap,
    end_cap: value.endCap,
    margin_x: value.marginX,
    margin_y: value.marginY,
    corner_radius: value.cornerRadius,
    fill_offset_x: value.fillOffsetX,
    fill_offset_y: value.fillOffsetY,
    stroke_offset_x: value.strokeOffsetX,
    stroke_offset_y: value.strokeOffsetY,
  };
}

export function outputToCtx(value: OutputScene): CtxOutputData {
  return {
    separation_enabled: value.separationEnabled,
    render_mode: value.renderMode,
    targets_1: value.targets1,
    targets_2: value.targets2,
    write_on_mode: value.writeOnMode,
    write_on_start: value.writeOnStart,
    write_on_end: value.writeOnEnd,
    reorder_parts: value.reorderParts,
    manual_order_enabled: value.manualOrderEnabled,
    manual_order_text: value.manualOrderText,
    force_disable_3d_projection: false,
  };
}
