import type { MugMetadata } from "./luaCompletionContext";
import {
  createEmptyScriptInputMetadata,
  kScriptInputColorCount,
  kScriptInputNumberCount,
  kScriptInputNumberMaximum,
  kScriptInputNumberMinimum,
  kScriptInputTextCount,
  type ScriptInputDeclaration,
  type ScriptInputMetadata,
} from "./scriptInputMetadata";

export interface Rgba {
  r: number;
  g: number;
  b: number;
  a: number;
}

export type HorizontalAlign = "left" | "center" | "right";
export type VerticalAlign = "top" | "center" | "bottom" | "baseline";
export type DisplayMode = "box" | "glyph";
export type GradientColorSpace = "none" | "okhsv" | "okhsl" | "oklab" | "linear_rgb" | "crayon";
export type StrokeOrder = "fill_over_stroke" | "stroke_over_fill";
export type StrokeJoin = "miter_clip" | "round" | "bevel" | "miter_round" | "miter_bevel";
export type StrokeCap = "butt" | "square" | "round" | "round_rev" | "triangle" | "triangle_rev";
export type OutputRenderMode = "default" | "separation_1" | "separation_2";
export type WriteOnMode = "character" | "part";
export const kDaVinciNormalizedCenter = 0.5;
// How pseudo parts are derived from a glyph: "contour" splits outlines into
// solid+holes groups; "fixed" slices every character into an equal number of
// pieces.
export type PartMode = "contour" | "fixed";

