export interface ScriptInputsScene {
  numbers: number[];
  colors: Rgba[];
  texts: string[];
}

export interface Scene {
  schemaVersion: 6;
  global: GlobalScene;
  camera: CameraScene;
  boundingBox: BoundingBoxScene;
  output: OutputScene;
  characters: CharacterScene[];
  parts: PartScene[];
  scriptInputs: ScriptInputsScene;
  settings: SimulatorSettings;
}

const kOpaqueWhite: Rgba = { r: 1, g: 1, b: 1, a: 1 };
const kDefaultGradientEndColor: Rgba = { r: 1, g: 0.5, b: 0, a: 1 };
const kDefaultStrokeColor: Rgba = { r: 0.1098039, g: 0.1098039, b: 0.1176471, a: 1 };
const kDefaultShadowColor: Rgba = { r: 0.3333333, g: 0.3333333, b: 1, a: 1 };
const kDefaultBoundingBoxColor: Rgba = { r: 1, g: 0, b: 0, a: 1 };
const kDefaultBoundingBoxFillColor: Rgba = { r: 1, g: 0.6666667, b: 1, a: 1 };
const kDefaultBoundingBoxWidth = 20;
const kDefaultBoundingBoxMargin = 40;
const kDefaultPreviewBackgroundColor: Rgba = {
  r: 0.1176471,
  g: 0.1176471,
  b: 0.1176471,
  a: 1,
};

export function createDefaultScene(): Scene {
  return {
    schemaVersion: 6,
    global: {
      text: "Sample Text!",
      fontName: "",
      tracking: 0,
      lineSpacing: 1,
      vertical: false,
      hAlign: "center",
      vAlign: "center",
      margins: [0, 0, 0, 0],
      positionX: kDaVinciNormalizedCenter,
      positionY: kDaVinciNormalizedCenter,
      rotation: 0,
      yaw: 0,
      pitch: 0,
      scale: 1,
      stretchX: 1,
      stretchY: 1,
      pivotX: kDaVinciNormalizedCenter,
      pivotY: kDaVinciNormalizedCenter,
      opacity: 1,
      color: { ...kOpaqueWhite },
      fillTransparent: false,
      gradientColorSpace: "none",
      gradientEndColor: { ...kDefaultGradientEndColor },
      gradientMidpoint: 0.5,
      gradientAngle: 270,
      gradientStart: 0.2,
      gradientEnd: 0.8,
      strokeWidth: 0,
      strokeGap: 0,
      strokeColor: { ...kDefaultStrokeColor },
      outerStrokeWidth: 0,
      outerStrokeColor: { ...kDefaultStrokeColor },
      strokeOrder: "fill_over_stroke",
      strokeJoin: "miter_clip",
      strokeMiterLimit: 4,
      shadowEnabled: false,
      shadowDistance: 1,
      shadowAngle: 45,
      shadowColor: { ...kDefaultShadowColor },
    },
    camera: {
      targetX: kDaVinciNormalizedCenter,
      targetY: kDaVinciNormalizedCenter,
      yaw: 0,
      pitch: 0,
      perspective: 0.5,
      zoom: 1,
      lensShiftX: 0,
      lensShiftY: 0,
    },
    boundingBox: {
      enabled: false,
      drawTop: true,
      drawBottom: true,
      drawLeft: true,
      drawRight: true,
      color: { ...kDefaultBoundingBoxColor },
      width: kDefaultBoundingBoxWidth,
      fillEnabled: false,
      fillColor: { ...kDefaultBoundingBoxFillColor },
      fillOpacity: 1,
      startCap: "butt",
      endCap: "butt",
      marginX: kDefaultBoundingBoxMargin,
      marginY: kDefaultBoundingBoxMargin,
      cornerRadius: 0,
      fillOffsetX: 0,
      fillOffsetY: 0,
      strokeOffsetX: 0,
      strokeOffsetY: 0,
    },
    output: {
      separationEnabled: false,
      renderMode: "default",
      targets1: "",
      targets2: "",
      writeOnMode: "character",
      writeOnStart: 0,
      writeOnEnd: 1,
      reorderParts: false,
      manualOrderEnabled: false,
      manualOrderText: "",
    },
    characters: [],
    parts: [],
    // Sized from the slot counts rather than listed out, so widening the slots
    // cannot leave a stored scene shorter than the arrays Lua reads.
    scriptInputs: {
      numbers: Array.from({ length: kScriptInputNumberCount }, () => 0),
      colors: Array.from({ length: kScriptInputColorCount }, () => ({ ...kOpaqueWhite })),
      texts: Array.from({ length: kScriptInputTextCount }, () => ""),
    },
    settings: {
      // 720p rather than 1080p: recordings are shared as gallery previews,
      // which cap at 1280x720, and this keeps an unmodified scene
      // within that budget without the author having to think about it.
      // Scenes already saved at another size keep it (mergeKnown preserves
      // stored values), so this only affects new ones.
      canvasWidth: 1280,
      canvasHeight: 720,
      fps: 30,
      durationFrames: 120,
      partsPerCharacter: 3,
      displayMode: "glyph",
      partMode: "contour",
      projection3D: false,
      backgroundColor: { ...kDefaultPreviewBackgroundColor },
      checkerboardBackground: false,
      showIndexLabels: false,
      showSpaces: false,
      spaceColor: { r: 0.5, g: 0.5, b: 0.5, a: 1 },
    },
  };
}

