export interface ApplyMetadataToSceneOptions {
  applyScriptInputDefaults?: boolean;
}

export function applyMetadataToScene(
  scene: Scene,
  metadata?: MugMetadata,
  options: ApplyMetadataToSceneOptions = {},
): void {
  if (metadata === undefined) {
    return;
  }
  if (metadata.projection3D !== undefined) {
    scene.settings.projection3D = metadata.projection3D;
  }
  if (metadata.durationSeconds !== undefined) {
    scene.settings.durationFrames = Math.max(
      Math.round(metadata.durationSeconds * scene.settings.fps),
      1,
    );
  }
  if (metadata.backgroundColor !== undefined) {
    scene.settings.backgroundColor = { ...metadata.backgroundColor };
  }
  if (metadata.fillColor !== undefined) {
    scene.global.color = { ...metadata.fillColor };
  }
  if (metadata.gradientEndColor !== undefined) {
    scene.global.gradientEndColor = { ...metadata.gradientEndColor };
  }
  if (metadata.checkerboardBackground !== undefined) {
    scene.settings.checkerboardBackground = metadata.checkerboardBackground;
  }
  if (metadata.positionX !== undefined) {
    scene.global.positionX = metadata.positionX;
  }
  if (metadata.positionY !== undefined) {
    scene.global.positionY = metadata.positionY;
  }
  // An empty `text ""` is treated as "no recommendation" rather than applied:
  // it would leave the inspector with nothing to shape, which no script means
  // to ask for.
  if (metadata.text !== undefined && metadata.text.length > 0) {
    scene.global.text = metadata.text;
  }
  if (
    options.applyScriptInputDefaults !== false &&
    metadata.scriptInputError === undefined &&
    metadata.scriptInputs !== undefined
  ) {
    applyAllScriptInputDefaults(scene, metadata.scriptInputs);
  }
}

export function synchronizeScriptInputMetadata(
  scene: Scene,
  metadata: MugMetadata,
  previous: ScriptInputMetadata | undefined,
  applyChangedDefaults: boolean,
): ScriptInputMetadata {
  let result = previous ?? createEmptyScriptInputMetadata();
  if (metadata.scriptInputError === undefined) {
    const current = metadata.scriptInputs ?? createEmptyScriptInputMetadata();
    if (applyChangedDefaults) {
      applyChangedScriptInputDefaults(scene, current, previous);
    }
    result = current;
  }
  return result;
}

function applyAllScriptInputDefaults(scene: Scene, metadata: ScriptInputMetadata): void {
  for (const [index, declaration] of metadata.numbers.entries()) {
    if (declaration !== undefined) {
      scene.scriptInputs.numbers[index] = declaration.defaultValue;
    }
  }
  for (const [index, declaration] of metadata.colors.entries()) {
    if (declaration !== undefined) {
      scene.scriptInputs.colors[index] = { ...declaration.defaultValue };
    }
  }
  for (const [index, declaration] of metadata.texts.entries()) {
    if (declaration !== undefined) {
      scene.scriptInputs.texts[index] = declaration.defaultValue;
    }
  }
}

function applyChangedScriptInputDefaults(
  scene: Scene,
  metadata: ScriptInputMetadata,
  previous: ScriptInputMetadata | undefined,
): void {
  for (const [index, declaration] of metadata.numbers.entries()) {
    if (declaration !== undefined && defaultChanged(declaration, previous?.numbers[index])) {
      scene.scriptInputs.numbers[index] = declaration.defaultValue;
    }
  }
  for (const [index, declaration] of metadata.colors.entries()) {
    if (
      declaration !== undefined &&
      defaultChanged(declaration, previous?.colors[index], colorsEqual)
    ) {
      scene.scriptInputs.colors[index] = { ...declaration.defaultValue };
    }
  }
  for (const [index, declaration] of metadata.texts.entries()) {
    if (declaration !== undefined && defaultChanged(declaration, previous?.texts[index])) {
      scene.scriptInputs.texts[index] = declaration.defaultValue;
    }
  }
}

function defaultChanged<Value>(
  declaration: ScriptInputDeclaration<Value>,
  previous: ScriptInputDeclaration<Value> | undefined,
  equal: (left: Value, right: Value) => boolean = Object.is,
): boolean {
  return previous === undefined || !equal(previous.defaultValue, declaration.defaultValue);
}

function colorsEqual(left: Rgba, right: Rgba): boolean {
  return left.r === right.r && left.g === right.g && left.b === right.b && left.a === right.a;
}

export function resetInspectorValues(scene: Scene, metadata?: MugMetadata): void {
  const defaults = createDefaultScene();
  const preservedSettings = {
    displayMode: scene.settings.displayMode,
    partMode: scene.settings.partMode,
    partsPerCharacter: scene.settings.partsPerCharacter,
    projection3D: scene.settings.projection3D,
    fontPath: scene.settings.fontPath,
  };
  scene.global = defaults.global;
  scene.camera = defaults.camera;
  scene.boundingBox = defaults.boundingBox;
  scene.output = defaults.output;
  scene.characters = [];
  scene.parts = [];
  scene.scriptInputs = defaults.scriptInputs;
  scene.settings = { ...defaults.settings, ...preservedSettings };
  if (metadata !== undefined) {
    applyMetadataToScene(scene, metadata);
  }
}

// What a pre-schemaVersion-5 scene needs to be brought up to date. Both fields
// come from the script's metadata; the caller resolves the font because which
// fonts exist is platform-specific (bundled assets on the web, the system font
// catalog under VSCode).
export interface SceneMigrationInputs {
  metadata?: MugMetadata;
  // The font a pre-5 scene should adopt for the script's `@recommend lang`,
  // when the stored font predates it being available. Undefined leaves the
  // stored font alone.
  fontForLanguage?: { family: string; path: string };
}

// Restores only fields known by the current schema and fills missing fields
// from defaults. This keeps hand-edited or older scene files safe to load.
//
// Two things are migrated for pre-schemaVersion-5 scenes, both stale by
// construction rather than by user intent:
//
//   - Text: samples used to set ctx.global.text from OnPreLayout on every
//     frame, so the persisted text was whatever the inspector happened to hold
//     and editing it had no visible effect. Those samples now publish the same
//     string as `@recommend text`, which replaces it.
//   - Font: the web build shipped no CJK font, so a Japanese script's scene was
//     saved with a Latin font that cannot render it. `fontForLanguage` replaces
//     it when the script asks for a language the stored font predates.
//
// From 5 on, both stored values are authoritative and neither is overridden.
export function restoreScene(value: unknown, migration?: SceneMigrationInputs): Scene {
  const defaults = createDefaultScene();
  const metadata = migration?.metadata;
  let result = defaults;
  let predatesRecommendedText = false;
  if (
    isRecord(value) &&
    (value.schemaVersion === defaults.schemaVersion || value.schemaVersion === 5 || value.schemaVersion === 4)
  ) {
    predatesRecommendedText = value.schemaVersion === 4;
    result = mergeKnown(defaults, value);
    result.characters = restoreItems(value.characters, createDefaultCharacterScene);
    result.parts = restoreItems(value.parts, createDefaultPartScene);
    const fontPath = isRecord(value.settings) ? value.settings.fontPath : undefined;
    if (typeof fontPath === "string" && fontPath.length > 0) {
      result.settings.fontPath = fontPath;
    }
  } else if (isRecord(value) && value.schemaVersion === 3) {
    predatesRecommendedText = true;
    result = restoreSchemaVersion3Scene(value, defaults);
  } else if (isRecord(value) && (value.schemaVersion === 1 || value.schemaVersion === 2)) {
    predatesRecommendedText = true;
    result = restoreLegacyScene(value, defaults);
  }
  if (predatesRecommendedText && metadata?.text !== undefined && metadata.text.length > 0) {
    result.global.text = metadata.text;
  }
  if (predatesRecommendedText && migration?.fontForLanguage !== undefined) {
    result.global.fontName = migration.fontForLanguage.family;
    result.settings.fontPath = migration.fontForLanguage.path;
  }
  // mergeKnown copies the stored schemaVersion verbatim, so a migrated scene
  // would otherwise be written back under its old version and migrate again on
  // every load.
  result.schemaVersion = defaults.schemaVersion;
  result.scriptInputs = normalizeScriptInputs(result.scriptInputs, defaults.scriptInputs);
  result.settings.canvasWidth = Math.max(Math.round(result.settings.canvasWidth), 1);
  result.settings.canvasHeight = Math.max(Math.round(result.settings.canvasHeight), 1);
  result.settings.fps = Math.max(result.settings.fps, 0.001);
  result.settings.durationFrames = Math.max(Math.round(result.settings.durationFrames), 1);
  result.settings.partsPerCharacter = Math.max(Math.round(result.settings.partsPerCharacter), 1);
  result.settings.backgroundColor.a = 1;
  result.camera.perspective = Math.max(result.camera.perspective, 0);
  result.camera.zoom = Math.max(result.camera.zoom, 0.001);
  result.global.hAlign = includes(["left", "center", "right"] as const, result.global.hAlign)
    ? result.global.hAlign
    : defaults.global.hAlign;
  result.global.vAlign = includes(["top", "center", "bottom", "baseline"] as const, result.global.vAlign)
    ? result.global.vAlign
    : defaults.global.vAlign;
  result.settings.displayMode = includes(["box", "glyph"] as const, result.settings.displayMode)
    ? result.settings.displayMode
    : defaults.settings.displayMode;
  result.settings.partMode = includes(["contour", "fixed"] as const, result.settings.partMode)
    ? result.settings.partMode
    : defaults.settings.partMode;
  result.global.gradientColorSpace = includes(
    ["none", "okhsv", "okhsl", "oklab", "linear_rgb", "crayon"] as const,
    result.global.gradientColorSpace,
  )
    ? result.global.gradientColorSpace
    : defaults.global.gradientColorSpace;
  result.global.margins = result.global.margins.filter(
    (margin): margin is number => typeof margin === "number" && Number.isFinite(margin),
  );
  return result;
}

function normalizeScriptInputs(value: ScriptInputsScene, defaults: ScriptInputsScene): ScriptInputsScene {
  const numbers = defaults.numbers.map((fallback, index) => {
    const candidate = value.numbers[index];
    return typeof candidate === "number" && Number.isFinite(candidate)
      ? Math.min(Math.max(candidate, kScriptInputNumberMinimum), kScriptInputNumberMaximum)
      : fallback;
  });
  const colors = defaults.colors.map((fallback, index) => {
    const candidate = value.colors[index];
    return isRecord(candidate) ? mergeKnown(fallback, candidate) : { ...fallback };
  });
  const texts = defaults.texts.map((fallback, index) => {
    const candidate = value.texts[index];
    return typeof candidate === "string" ? candidate : fallback;
  });
  return { numbers, colors, texts };
}

// schemaVersion 3 kept text-shaping inputs (text, font_name, tracking, ...) in a separate `layout`
// slice from the transform/fill/stroke/shadow `global` slice. schemaVersion 4 merged them into a
// single `global` slice, mirroring the ctx.global consolidation on the Lua API side.
function restoreSchemaVersion3Scene(value: Record<string, unknown>, defaults: Scene): Scene {
  const legacyLayout = isRecord(value.layout) ? value.layout : {};
  const legacyGlobal = isRecord(value.global) ? value.global : {};
  const migratedValue: Record<string, unknown> = {
    ...value,
    schemaVersion: defaults.schemaVersion,
    global: { ...legacyLayout, ...legacyGlobal },
  };
  delete migratedValue.layout;
  const result = mergeKnown(defaults, migratedValue);
  result.characters = restoreItems(value.characters, createDefaultCharacterScene);
  result.parts = restoreItems(value.parts, createDefaultPartScene);
  const fontPath = isRecord(value.settings) ? value.settings.fontPath : undefined;
  if (typeof fontPath === "string" && fontPath.length > 0) {
    result.settings.fontPath = fontPath;
  }
  return result;
}

function restoreLegacyScene(value: Record<string, unknown>, defaults: Scene): Scene {
  const migratedValue: Record<string, unknown> = { ...value, schemaVersion: defaults.schemaVersion };
  const legacyLayout = isRecord(value.layout) ? value.layout : {};
  const legacyGlobal = isRecord(value.global) ? value.global : {};
  migratedValue.global = {
    positionX: 0,
    positionY: 0,
    pivotX: 0,
    pivotY: 0,
    ...legacyLayout,
    ...legacyGlobal,
  };
  delete migratedValue.layout;
  if (value.schemaVersion === 1) {
    const legacyCharacter = isRecord(value.characterDefaults) ? value.characterDefaults : undefined;
    const legacyPart = isRecord(value.partDefaults) ? value.partDefaults : undefined;
    migratedValue.characters = legacyCharacter === undefined ? [] : [legacyCharacter];
    migratedValue.parts = legacyPart === undefined ? [] : [legacyPart];
  }
  migratedValue.characters = addLegacyItemCoordinateDefaults(migratedValue.characters);
  migratedValue.parts = addLegacyItemCoordinateDefaults(migratedValue.parts);
  const result = mergeKnown(defaults, migratedValue);
  result.characters = restoreItems(migratedValue.characters, createDefaultCharacterScene);
  result.parts = restoreItems(migratedValue.parts, createDefaultPartScene);
  const fontPath = isRecord(value.settings) ? value.settings.fontPath : undefined;
  if (typeof fontPath === "string" && fontPath.length > 0) {
    result.settings.fontPath = fontPath;
  }
  migrateZeroCenteredCoordinates(result);
  return result;
}

function migrateZeroCenteredCoordinates(scene: Scene): void {
  const canvasWidth = Math.max(Math.round(scene.settings.canvasWidth), 1);
  const canvasHeight = Math.max(Math.round(scene.settings.canvasHeight), 1);
  const horizontalScale = canvasHeight / canvasWidth;
  const migrateX = (value: number): number => kDaVinciNormalizedCenter + value * horizontalScale;
  const migrateY = (value: number): number => kDaVinciNormalizedCenter - value;
  scene.global.positionX = migrateX(scene.global.positionX);
  scene.global.positionY = migrateY(scene.global.positionY);
  scene.global.pivotX = migrateX(scene.global.pivotX);
  scene.global.pivotY = migrateY(scene.global.pivotY);
  for (const character of scene.characters) {
    character.offsetX = migrateX(character.offsetX);
    character.offsetY = migrateY(character.offsetY);
    character.pivotX = migrateX(character.pivotX);
    character.pivotY = migrateY(character.pivotY);
  }
  for (const part of scene.parts) {
    part.offsetX = migrateX(part.offsetX);
    part.offsetY = migrateY(part.offsetY);
    part.pivotX = migrateX(part.pivotX);
    part.pivotY = migrateY(part.pivotY);
  }
}

function addLegacyItemCoordinateDefaults(value: unknown): unknown[] {
  if (!Array.isArray(value)) {
    return [];
  }
  return value.filter(isRecord).map((item) => ({
    offsetX: 0,
    offsetY: 0,
    pivotX: 0,
    pivotY: 0,
    ...item,
  }));
}

function restoreItems<T>(value: unknown, makeDefault: () => T): T[] {
  if (!Array.isArray(value)) {
    return [];
  }
  return value.filter(isRecord).map((item) => mergeKnown(makeDefault(), item));
}

function mergeKnown<T>(defaults: T, value: unknown): T {
  let result = defaults;
  if (Array.isArray(defaults)) {
    result = (Array.isArray(value) ? [...value] : [...defaults]) as T;
  } else if (isRecord(defaults) && isRecord(value)) {
    const merged: Record<string, unknown> = {};
    for (const [key, defaultValue] of Object.entries(defaults)) {
      merged[key] = mergeKnown(defaultValue, value[key]);
    }
    result = merged as T;
  } else if (
    typeof value === typeof defaults &&
    (typeof value !== "number" || Number.isFinite(value))
  ) {
    result = value as T;
  }
  return result;
}

function includes<T extends string>(values: readonly T[], value: string): value is T {
  return values.some((candidate) => candidate === value);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
