import type { LuaApiMember, LuaCompletionTarget } from "./scriptingApi";

export function getApiMemberDescription(apiMember: LuaApiMember, isJapanese: boolean): string {
  const description = isJapanese ? apiMember.descriptionJa : apiMember.description;
  return `\`API ${apiMember.since}+\` ${description}`;
}

export function targetToSection(target: LuaCompletionTarget): string {
  switch (target) {
    case "global":
    case "global_fill":
    case "gradient":
    case "global_stroke":
    case "global_shadow":
      return "global";
    case "camera":
      return "camera";
    case "character":
    case "character_geometry":
    case "individual_fill":
    case "individual_stroke":
    case "individual_shadow":
      return "character";
    case "part":
    case "part_geometry":
      return "part";
    case "path_collection":
    case "path_part":
    case "drawing_path":
      return "path_context";
    // The info table has no heading of its own: it is documented inside the
    // mt.each_char / mt.each_part entries.
    case "each_info":
      return "mt";
    case "color":
      return "color";
    case "oklab_components":
    case "oklch_components":
    case "okhsv_components":
    case "okhsl_components":
      return "mt";
    case "bounding_box":
      return "bounding_box";
    case "output":
      return "output";
    case "timeline":
      return "timeline";
    case "font":
      return "font";
    case "canvas":
      return "canvas";
    case "meta":
    case "capabilities":
    case "limits":
      return "meta";
    case "script_inputs":
      return "script_inputs";
    case "mt":
    case "ease":
    case "color_utilities":
    case "layout_utilities":
    case "path_utilities":
    case "arc_length_path":
    case "timeline_utilities":
    case "text_utilities":
      return "mt";
    default:
      return "context";
  }
}
