import type { CtxCharacterData, CtxGlobalData, CtxPartData } from "./ctxBindings";
import type { Rgba } from "../shared/sceneSchema";

export function resolveEffectiveCharacter(
  scriptOutput: CtxCharacterData,
  global: CtxGlobalData,
): CtxCharacterData {
  return {
    ...scriptOutput,
    opacity: global.opacity * scriptOutput.opacity,
    fill: {
      use: scriptOutput.fill.use,
      color: cloneColor(scriptOutput.fill.use ? scriptOutput.fill.color : global.fill.color),
    },
    stroke: {
      use: scriptOutput.stroke.use,
      width: scriptOutput.stroke.use ? scriptOutput.stroke.width : global.stroke.width,
      gap: scriptOutput.stroke.use ? scriptOutput.stroke.gap : global.stroke.gap,
      color: cloneColor(scriptOutput.stroke.use ? scriptOutput.stroke.color : global.stroke.color),
      outer_width: scriptOutput.stroke.use ? scriptOutput.stroke.outer_width : global.stroke.outer_width,
      outer_color: cloneColor(
        scriptOutput.stroke.use ? scriptOutput.stroke.outer_color : global.stroke.outer_color,
      ),
    },
    shadow: {
      use: scriptOutput.shadow.use,
      color: cloneColor(scriptOutput.shadow.use ? scriptOutput.shadow.color : global.shadow.color),
    },
  };
}

export function resolveEffectivePart(
  scriptOutput: CtxPartData,
  character: CtxCharacterData,
): CtxPartData {
  return {
    ...scriptOutput,
    // character.opacity is already the resolved global*character product (see
    // resolveEffectiveCharacter), so multiplying it in here gives the full global*character*part
    // opacity without resolveEffectivePart needing the global value itself.
    opacity: character.opacity * scriptOutput.opacity,
    fill: {
      use: scriptOutput.fill.use,
      color: cloneColor(scriptOutput.fill.use ? scriptOutput.fill.color : character.fill.color),
    },
    // No host parameter group backs a part's individual stroke/shadow (cut from the inspector to
    // keep the parameter count down, mirroring the Native side); script-only, so it only ever
    // overrides the owning character's resolved stroke/shadow when a script sets .use.
    stroke: {
      use: scriptOutput.stroke.use,
      width: scriptOutput.stroke.use ? scriptOutput.stroke.width : character.stroke.width,
      gap: scriptOutput.stroke.use ? scriptOutput.stroke.gap : character.stroke.gap,
      color: cloneColor(scriptOutput.stroke.use ? scriptOutput.stroke.color : character.stroke.color),
      outer_width: scriptOutput.stroke.use ? scriptOutput.stroke.outer_width : character.stroke.outer_width,
      outer_color: cloneColor(
        scriptOutput.stroke.use ? scriptOutput.stroke.outer_color : character.stroke.outer_color,
      ),
    },
    // use mirrors Native's resolved useIndividualShadowColor_: true when either this part or its
    // owning character opted into an individual shadow color, so a part without its own override
    // still reports "individual shadow in effect" when it inherited one from the character (needed
    // so the shadow pass can draw this part even while the global shadow is off).
    shadow: {
      use: scriptOutput.shadow.use || character.shadow.use,
      color: cloneColor(scriptOutput.shadow.use ? scriptOutput.shadow.color : character.shadow.color),
    },
  };
}

function cloneColor(color: Rgba): Rgba {
  return { r: color.r, g: color.g, b: color.b, a: color.a };
}
