export type ScriptReloadOperation = (
  source: string,
  scriptGeneration: number,
) => Promise<void>;

// Serializes candidate Lua runtime creation and tags every request with the
// target it belongs to. Advancing the generation invalidates work that has
// not started yet; a running operation can use isCurrent() before committing
// its result to UI state.
export class ScriptReloadQueue {
  private tail: Promise<void> = Promise.resolve();
  private scriptGeneration = 0;

  constructor(
    private readonly reload: ScriptReloadOperation,
    private readonly onError: (error: unknown) => void,
  ) {}

  get currentGeneration(): number {
    return this.scriptGeneration;
  }

  advanceTarget(): number {
    this.scriptGeneration += 1;
    return this.scriptGeneration;
  }

  isCurrent(scriptGeneration: number): boolean {
    return scriptGeneration === this.scriptGeneration;
  }

  enqueue(
    source: string,
    scriptGeneration = this.scriptGeneration,
  ): Promise<void> {
    const operation = this.tail.then(async () => {
      if (this.isCurrent(scriptGeneration)) {
        await this.reload(source, scriptGeneration);
      }
    });
    this.tail = operation.catch((error: unknown) => {
      this.onError(error);
    });
    return operation;
  }
}
