// Inline SVG icons for toolbar buttons.
//
// Emoji were tried first and rejected: their glyphs are supplied by the
// platform's font, so they look different on every OS and ignore the button's
// own colour, which the loop toggle needs in order to show its state. These
// paths use fill="currentColor" so CSS drives the colour exactly like the
// text-glyph buttons around them.

const kIconSize = 16;
const kViewBox = "0 0 24 24";

function createIconSvg(pathData: string): SVGSVGElement {
  const svgNamespace = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(svgNamespace, "svg");
  svg.setAttribute("viewBox", kViewBox);
  svg.setAttribute("width", String(kIconSize));
  svg.setAttribute("height", String(kIconSize));
  svg.setAttribute("fill", "currentColor");
  // The button carries its own aria-label, so the icon itself is decorative.
  svg.setAttribute("aria-hidden", "true");
  const path = document.createElementNS(svgNamespace, "path");
  path.setAttribute("d", pathData);
  svg.appendChild(path);
  return svg;
}

