export const kAiReferenceUri = "lua_api_for_ai.md";
export const kAiReferenceFileName = "lua_api_for_ai.md";

export interface TextResponse {
  ok: boolean;
  status: number;
  text(): Promise<string>;
}

// Both menu actions share one request. A failed request is discarded so a
// later click can retry after a transient server or network failure.
export function createAiReferenceLoader(
  fetchReference: () => Promise<TextResponse> = () => fetch(kAiReferenceUri),
): () => Promise<string> {
  let pendingReference: Promise<string> | undefined;
  return async () => {
    pendingReference ??= fetchReference().then(async (response) => {
      if (!response.ok) {
        throw new Error(`failed to load AI API reference (${response.status})`);
      }
      return response.text();
    });
    try {
      return await pendingReference;
    } catch (error) {
      pendingReference = undefined;
      throw error;
    }
  };
}
