// Fetches the aggregated third-party license notices the build step
// (esbuild.config.mjs: writeThirdPartyNotices) bakes into the web build's
// static assets. The VSCode extension instead ships THIRD_PARTY_NOTICES.md
// as a file inside the .vsix (see .vscodeignore) with no in-app viewer.

export async function fetchThirdPartyNotices(): Promise<string> {
  const response = await fetch("third-party-notices.md");
  if (!response.ok) {
    throw new Error(`failed to fetch third-party notices (${response.status})`);
  }
  return response.text();
}
