export interface SteppedNumericText {
  text: string;
  value: number;
  caret: number;
}

export function stepNumericText(
  text: string,
  caret: number,
  direction: 1 | -1,
  minimumStep: number,
): SteppedNumericText | undefined {
  const parsed = Number(text);
  let result: SteppedNumericText | undefined;
  if (Number.isFinite(parsed)) {
    const mantissaEnd = findMantissaEnd(text);
    const boundedCaret = Math.min(Math.max(caret, 0), mantissaEnd);
    const digitIndex = findActiveDigit(text, boundedCaret, mantissaEnd);
    if (digitIndex !== undefined) {
      const exponent = digitExponent(text, digitIndex, mantissaEnd);
      const step = Math.max(10 ** exponent, minimumStep);
      const fractionDigits = countFractionDigits(text, mantissaEnd);
      const precision = Math.max(fractionDigits, decimalPlaces(step));
      const scale = 10 ** precision;
      const value = Math.round((parsed + direction * step) * scale) / scale;
      if (Number.isFinite(value)) {
        const steppedText = precision > 0 ? value.toFixed(precision) : String(value);
        const wasAtEnd = boundedCaret === mantissaEnd;
        const wasAfterDigit = digitIndex < boundedCaret;
        const steppedDigitIndex = findDigitForExponent(steppedText, exponent);
        let steppedCaret = wasAtEnd ? steppedText.length : steppedDigitIndex;
        if (!wasAtEnd && wasAfterDigit) {
          steppedCaret += 1;
        }
        result = {
          text: steppedText,
          value,
          caret: Math.min(Math.max(steppedCaret, 0), steppedText.length),
        };
      }
    }
  }
  return result;
}

function findMantissaEnd(text: string): number {
  const exponentIndex = text.search(/[eE]/);
  return exponentIndex < 0 ? text.length : exponentIndex;
}

function findActiveDigit(text: string, caret: number, mantissaEnd: number): number | undefined {
  let result: number | undefined;
  const precedingIndex = Math.min(caret, mantissaEnd) - 1;
  if (precedingIndex >= 0 && isDigit(text[precedingIndex])) {
    result = precedingIndex;
  }
  return result;
}

function digitExponent(text: string, digitIndex: number, mantissaEnd: number): number {
  const decimalIndex = text.slice(0, mantissaEnd).indexOf(".");
  const effectiveDecimalIndex = decimalIndex < 0 ? mantissaEnd : decimalIndex;
  return digitIndex < effectiveDecimalIndex
    ? effectiveDecimalIndex - digitIndex - 1
    : effectiveDecimalIndex - digitIndex;
}

function findDigitForExponent(text: string, exponent: number): number {
  const mantissaEnd = findMantissaEnd(text);
  const decimalIndex = text.slice(0, mantissaEnd).indexOf(".");
  const effectiveDecimalIndex = decimalIndex < 0 ? mantissaEnd : decimalIndex;
  const candidate = exponent >= 0
    ? effectiveDecimalIndex - exponent - 1
    : effectiveDecimalIndex - exponent;
  return Math.min(Math.max(candidate, 0), mantissaEnd - 1);
}

function countFractionDigits(text: string, mantissaEnd: number): number {
  const decimalIndex = text.slice(0, mantissaEnd).indexOf(".");
  return decimalIndex < 0 ? 0 : mantissaEnd - decimalIndex - 1;
}

function decimalPlaces(value: number): number {
  const text = String(value);
  const decimalIndex = text.indexOf(".");
  return decimalIndex < 0 ? 0 : text.length - decimalIndex - 1;
}

function isDigit(value: string | undefined): boolean {
  return value !== undefined && value >= "0" && value <= "9";
}
