import type { Rgba } from "../shared/sceneSchema";

const kMaximumColorChannel = 255;

export function rgbaToHex(color: Rgba): string {
  const channels = [color.r, color.g, color.b].map((channel) =>
    Math.round(clampUnit(channel) * kMaximumColorChannel)
      .toString(16)
      .padStart(2, "0"),
  );
  return `#${channels.join("")}`;
}

export function rgbaToCompactLabel(color: Rgba): string {
  const rgb = rgbaToHex(color).toUpperCase();
  const alpha = clampUnit(color.a);
  return alpha === 1 ? rgb : `${rgb} @${Math.round(alpha * 100)}%`;
}

export function rgbaToCss(color: Rgba): string {
  const channels = [color.r, color.g, color.b].map((channel) =>
    Math.round(clampUnit(channel) * kMaximumColorChannel),
  );
  return `rgba(${channels.join(", ")}, ${clampUnit(color.a)})`;
}

export function applyHexToRgb(hex: string, color: Rgba): void {
  const match = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(hex);
  if (match !== null) {
    color.r = Number.parseInt(match[1], 16) / kMaximumColorChannel;
    color.g = Number.parseInt(match[2], 16) / kMaximumColorChannel;
    color.b = Number.parseInt(match[3], 16) / kMaximumColorChannel;
  }
}

export function clampUnit(value: number): number {
  return Math.min(Math.max(value, 0), 1);
}
