/**
 * Splits a dotted Lua expression for hover lookup. Trailing index access on the
 * final segment is stripped so `ctx.chars[index]` / `ctx.parts[i]` resolve as
 * members `chars` / `parts` (schema names never include brackets). A method call
 * written with a colon (`path:at_distance`) splits on the colon.
 */
export function parseHoverExpression(
  expression: string,
): { receiver: string; memberName: string; receiverEnd: number; separator: string } | undefined {
  const separatorIndex = Math.max(expression.lastIndexOf("."), expression.lastIndexOf(":"));
  let result:
    | { receiver: string; memberName: string; receiverEnd: number; separator: string }
    | undefined;
  if (separatorIndex >= 0) {
    const receiver = expression.slice(0, separatorIndex);
    const rawMember = expression.slice(separatorIndex + 1);
    const memberName = bareIdentifier(rawMember);
    if (memberName.length > 0) {
      result = {
        receiver,
        memberName,
        receiverEnd: separatorIndex,
        separator: expression[separatorIndex],
      };
    }
  }
  return result;
}

/** Leading identifier of a segment such as `chars[index]` → `chars`. */
export function bareIdentifier(segment: string): string {
  const match = /^([A-Za-z_]\w*)/.exec(segment);
  return match?.[1] ?? "";
}
