export type MessageKey = keyof typeof kStrings;

const kStorageKey = "mt-sim.locale";

function isLocale(value: string | null): value is Locale {
  return value === "en" || value === "ja";
}

// A stored choice always wins: the reader picked it on this machine. Only the
// first visit consults the browser, and anything that is not Japanese lands on
// English rather than an untranslated locale.
function detectInitialLocale(): Locale {
  let locale: Locale = "en";
  const stored = typeof localStorage === "undefined" ? null : localStorage.getItem(kStorageKey);
  if (isLocale(stored)) {
    locale = stored;
  } else if (typeof navigator !== "undefined" && navigator.language.startsWith("ja")) {
    locale = "ja";
  }
  return locale;
}

let currentLocale = detectInitialLocale();
const localeListeners = new Set<() => void>();

export function getLocale(): Locale {
  return currentLocale;
}

export function isJapaneseLocale(): boolean {
  return currentLocale === "ja";
}

export function t(key: MessageKey): string {
  return kStrings[key][currentLocale];
}

// Notifies every subscriber so already-rendered UI can relabel itself in place;
// nothing here reloads the page or rebuilds the DOM.
export function setLocale(locale: Locale): void {
  if (locale !== currentLocale) {
    currentLocale = locale;
    if (typeof localStorage !== "undefined") {
      localStorage.setItem(kStorageKey, locale);
    }
    for (const listener of localeListeners) {
      listener();
    }
  }
}

export function onLocaleChange(listener: () => void): () => void {
  localeListeners.add(listener);
  return () => localeListeners.delete(listener);
}

// Relabels every element carrying a data-i18n attribute. Static markup opts in
// declaratively instead of being wired up one element at a time:
//   data-i18n="menu.copyScript"        -> textContent
//   data-i18n-title="toolbar.resetLayout"  -> title attribute
//   data-i18n-aria-label="menu.label"      -> aria-label attribute
export function applyStaticTranslations(root: ParentNode = document): void {
  const attributeTargets = [
    ["data-i18n-title", "title"],
    ["data-i18n-aria-label", "aria-label"],
    ["data-i18n-placeholder", "placeholder"],
  ] as const;

  for (const element of root.querySelectorAll<HTMLElement>("[data-i18n]")) {
    const key = element.dataset.i18n as MessageKey | undefined;
    if (key !== undefined && key in kStrings) {
      // Menu items hold an inline SVG icon before their label, so only the text
      // node is replaced; setting textContent would drop the icon.
      const label = element.querySelector<HTMLElement>("[data-i18n-text]");
      if (label === null) {
        element.textContent = t(key);
      } else {
        label.textContent = t(key);
      }
    }
  }

  for (const [datasetAttribute, domAttribute] of attributeTargets) {
    for (const element of root.querySelectorAll<HTMLElement>(`[${datasetAttribute}]`)) {
      const key = element.getAttribute(datasetAttribute) as MessageKey | null;
      if (key !== null && key in kStrings) {
        element.setAttribute(domAttribute, t(key));
      }
    }
  }
}
