// Transport bar: play/pause, frame slider, frame counter. Playback advances
// fractional frames from wall-clock time so evaluation cost never changes the
// animation speed. The slider also hosts the recording range: a shaded band
// with draggable in/out handles.
import { createCameraIcon, createLoopIcon } from "./icons";
import { onLocaleChange, t } from "../shared/i18n";

export interface RecordRange {
  startFrame: number;
  endFrame: number;
}

export function clampRecordRange(
  startFrame: number,
  endFrame: number,
  durationFrames: number,
): RecordRange {
  const clampedStart = Math.min(Math.max(Math.floor(startFrame), 0), durationFrames - 1);
  const clampedEnd = Math.min(
    Math.max(Math.floor(endFrame), clampedStart + 1),
    durationFrames,
  );
  return { startFrame: clampedStart, endFrame: clampedEnd };
}

export class Timeline {
  private frameValue = 0;
  private playing = false;
  private lastTickMs = 0;
  private animationHandle = 0;
  private playbackGeneration = 0;
  private disposed = false;
  private recordRange: RecordRange;

  get recordRangeValue(): RecordRange {
    return { ...this.recordRange };
  }

  private readonly playButton: HTMLButtonElement;
  private readonly sliderWrap: HTMLDivElement;
  private readonly slider: HTMLInputElement;
  private readonly frameLabel: HTMLSpanElement;
  private readonly secondsLabel: HTMLSpanElement;
  private readonly loopButton: HTMLButtonElement;
  private readonly recordBand: HTMLDivElement;
  private readonly recordStartHandle: HTMLDivElement;
  private readonly recordEndHandle: HTMLDivElement;
  private readonly recordStartLabel: HTMLDivElement;
  private readonly recordEndLabel: HTMLDivElement;
  private readonly recordButton: HTMLButtonElement;
  private readonly captureButton: HTMLButtonElement | undefined;

  constructor(
    container: HTMLElement,
    private durationFrames: number,
    private fps: number,
    private loop: boolean,
    private readonly onFrame: (frame: number) => void,
    private readonly onLoopChanged: (loop: boolean) => void,
    private readonly onRecordRequested: (startFrame: number, endFrame: number) => void,
    // Optional: hosts with nowhere to put a still omit it, and no capture
    // button is rendered.
    onCaptureRequested?: () => void,
  ) {
    this.recordRange = { startFrame: 0, endFrame: durationFrames };
    const bar = document.createElement("div");
    bar.className = "timeline";
    this.playButton = document.createElement("button");
    this.playButton.textContent = "▶";
    this.playButton.addEventListener("click", () => this.togglePlay());
    this.slider = document.createElement("input");
    this.slider.type = "range";
    this.slider.min = "0";
    this.slider.max = String(durationFrames);
    this.slider.step = "1";
    this.slider.value = "0";
    this.slider.addEventListener("input", () => {
      this.pause();
      this.setFrame(Number(this.slider.value));
    });
    this.sliderWrap = document.createElement("div");
    this.sliderWrap.className = "slider-wrap";
    this.recordBand = document.createElement("div");
    this.recordBand.className = "record-band";
    this.recordStartHandle = this.createRecordHandle("record-handle-start", true);
    this.recordStartHandle.title = t("timeline.recordStart");
    this.recordEndHandle = this.createRecordHandle("record-handle-end", false);
    this.recordEndHandle.title = t("timeline.recordEnd");
    this.recordStartLabel = document.createElement("div");
    this.recordStartLabel.className = "record-frame-label";
    this.recordEndLabel = document.createElement("div");
    this.recordEndLabel.className = "record-frame-label";
    this.sliderWrap.append(
      this.recordBand,
      this.slider,
      this.recordStartHandle,
      this.recordEndHandle,
      this.recordStartLabel,
      this.recordEndLabel,
    );
    this.frameLabel = document.createElement("span");
    this.frameLabel.className = "frame-label";
    this.secondsLabel = document.createElement("span");
    this.secondsLabel.className = "seconds-label";

    // An icon toggle rather than a labelled checkbox: the row has to fit the
    // capture and record buttons too, and "Loop" spelled out costs more width
    // than the state is worth. Active state reads as colour (see
    // .loop-button.active), with aria-pressed carrying it for assistive tech.
    this.loopButton = document.createElement("button");
    this.loopButton.type = "button";
    this.loopButton.className = "loop-button";
    this.loopButton.appendChild(createLoopIcon());
    this.loopButton.addEventListener("click", () => {
      this.loop = !this.loop;
      this.applyLoopState();
      this.onLoopChanged(this.loop);
    });
    this.applyLoopState();

    this.recordButton = document.createElement("button");
    this.recordButton.className = "record-button";
    this.recordButton.textContent = "⏺";
    this.recordButton.title = t("timeline.record");
    this.recordButton.addEventListener("click", () => {
      this.onRecordRequested(this.recordRange.startFrame, this.recordRange.endFrame);
    });

    const recordContainer = document.createElement("span");
    recordContainer.className = "record-controls";
    // The capture button sits with the record button because both produce a
    // file from the scene; omitted when the host cannot save one.
    if (onCaptureRequested !== undefined) {
      const captureButton = document.createElement("button");
      this.captureButton = captureButton;
      captureButton.type = "button";
      captureButton.className = "capture-button";
      captureButton.appendChild(createCameraIcon());
      captureButton.title = t("timeline.capture");
      captureButton.setAttribute("aria-label", captureButton.title);
      captureButton.addEventListener("click", onCaptureRequested);
      recordContainer.append(captureButton);
    }
    recordContainer.append(this.recordButton);

    bar.append(
      this.playButton,
      this.sliderWrap,
      this.frameLabel,
      this.secondsLabel,
      this.loopButton,
      recordContainer,
    );
    container.appendChild(bar);
    this.updateLabel();
    this.updateRecordRangeVisuals();
    onLocaleChange(() => {
      this.applyTranslations();
    });
  }

  // Relabels the tooltips set once during construction. The transport buttons
  // carry glyphs rather than words, so only their titles are localized; the
  // loop button's title is owned by applyLoopState.
  private applyTranslations(): void {
    this.recordStartHandle.title = t("timeline.recordStart");
    this.recordEndHandle.title = t("timeline.recordEnd");
    this.recordButton.title = t("timeline.record");
    if (this.captureButton !== undefined) {
      this.captureButton.title = t("timeline.capture");
      this.captureButton.setAttribute("aria-label", this.captureButton.title);
    }
  }

  // The toggle carries its state in colour alone, so aria-pressed and the
  // title are what make it readable without seeing that colour.
  private applyLoopState(): void {
    this.loopButton.classList.toggle("active", this.loop);
    this.loopButton.setAttribute("aria-pressed", String(this.loop));
    const title = this.loop ? "Loop playback: on" : "Loop playback: off";
    this.loopButton.title = title;
    this.loopButton.setAttribute("aria-label", title);
  }

  get frame(): number {
    return Math.floor(this.frameValue);
  }

  refresh(): void {
    this.onFrame(this.frame);
  }

  updateConfiguration(durationFrames: number, fps: number, loop: boolean): void {
    const previousDuration = this.durationFrames;
    this.durationFrames = Math.max(Math.floor(durationFrames), 1);
    this.fps = Math.max(fps, 0.001);
    this.loop = loop;
    this.applyLoopState();
    this.slider.max = String(this.durationFrames);
    // An out point left at the previous end tracks the new duration.
    const endFrame = this.recordRange.endFrame === previousDuration
      ? this.durationFrames
      : this.recordRange.endFrame;
    this.recordRange = clampRecordRange(
      this.recordRange.startFrame,
      endFrame,
      this.durationFrames,
    );
    this.updateRecordRangeVisuals();
    if (this.frameValue > this.durationFrames) {
      this.setFrame(this.durationFrames);
    } else {
      this.updateLabel();
    }
  }

  reset(): void {
    this.pause();
    this.recordRange = { startFrame: 0, endFrame: this.durationFrames };
    this.updateRecordRangeVisuals();
    this.frameValue = 0;
    this.setFrame(0);
  }

  // Halts playback without touching the marked range, so an offscreen
  // recording can take over the evaluator without the playhead advancing
  // underneath it.
  pausePlayback(): void {
    this.pause();
  }

  dispose(): void {
    this.disposed = true;
    this.pause();
  }

  // Normal playback is confined to the marked range: starting outside it
  // jumps to the range start, and the range end acts as the loop/stop point.
  private togglePlay(): void {
    if (this.disposed) {
      return;
    }
    if (this.playing) {
      this.pause();
    } else {
      const outsideRange =
        this.frame < this.recordRange.startFrame || this.frame >= this.recordRange.endFrame;
      if (outsideRange) {
        this.frameValue = this.recordRange.startFrame;
        this.setFrame(this.recordRange.startFrame);
      }
      this.beginPlayback();
    }
  }

  private beginPlayback(): void {
    this.playing = true;
    this.updatePlayButtonIcon();
    this.lastTickMs = performance.now();
    const playbackGeneration = ++this.playbackGeneration;
    this.tick(playbackGeneration);
  }

  private pause(): void {
    this.playing = false;
    this.playbackGeneration += 1;
    this.updatePlayButtonIcon();
    cancelAnimationFrame(this.animationHandle);
    this.animationHandle = 0;
  }

  private updatePlayButtonIcon(): void {
    if (this.playing) {
      this.playButton.textContent = "⏸";
    } else if (this.frame >= this.recordRange.endFrame) {
      this.playButton.textContent = "↻";
    } else {
      this.playButton.textContent = "▶";
    }
  }

  private tick(playbackGeneration: number): void {
    if (
      !this.playing ||
      this.disposed ||
      playbackGeneration !== this.playbackGeneration
    ) {
      return;
    }
    try {
      const nowMs = performance.now();
      const deltaSeconds = (nowMs - this.lastTickMs) / 1000;
      this.lastTickMs = nowMs;
      let nextFrame = this.frameValue + deltaSeconds * this.fps;

      const endFrame = this.recordRange.endFrame;
      if (nextFrame > endFrame) {
        if (this.loop) {
          nextFrame = this.recordRange.startFrame;
        } else {
          this.setFrame(endFrame);
          this.pause();
          return;
        }
      }
      this.setFrame(nextFrame);
      if (
        this.playing &&
        !this.disposed &&
        playbackGeneration === this.playbackGeneration
      ) {
        this.animationHandle = requestAnimationFrame(
          () => this.tick(playbackGeneration),
        );
      }
    } catch (error) {
      this.pause();
      throw error;
    }
  }

  private createRecordHandle(className: string, isStart: boolean): HTMLDivElement {
    const handle = document.createElement("div");
    handle.className = `record-handle ${className}`;
    handle.addEventListener("pointerdown", (event) => {
      event.preventDefault();
      handle.setPointerCapture(event.pointerId);
    });
    handle.addEventListener("pointermove", (event) => {
      if (handle.hasPointerCapture(event.pointerId)) {
        this.dragRecordHandleTo(isStart, event.clientX);
      }
    });
    return handle;
  }

  private dragRecordHandleTo(isStart: boolean, clientX: number): void {
    const bounds = this.sliderWrap.getBoundingClientRect();
    if (bounds.width > 0) {
      const ratio = Math.min(Math.max((clientX - bounds.left) / bounds.width, 0), 1);
      const frame = Math.round(ratio * this.durationFrames);
      const startFrame = isStart
        ? Math.min(frame, this.recordRange.endFrame - 1)
        : this.recordRange.startFrame;
      const endFrame = isStart
        ? this.recordRange.endFrame
        : Math.max(frame, this.recordRange.startFrame + 1);
      this.recordRange = clampRecordRange(startFrame, endFrame, this.durationFrames);
      this.updateRecordRangeVisuals();
    }
  }

  private updateRecordRangeVisuals(): void {
    const startRatio = this.recordRange.startFrame / this.durationFrames;
    const endRatio = this.recordRange.endFrame / this.durationFrames;
    this.recordBand.style.left = `${startRatio * 100}%`;
    this.recordBand.style.width = `${(endRatio - startRatio) * 100}%`;
    this.recordStartHandle.style.left = `${startRatio * 100}%`;
    this.recordEndHandle.style.left = `${endRatio * 100}%`;
    this.updateRecordFrameLabel(
      this.recordStartLabel,
      startRatio,
      this.recordRange.startFrame,
      this.recordRange.startFrame !== 0,
    );
    this.updateRecordFrameLabel(
      this.recordEndLabel,
      endRatio,
      this.recordRange.endFrame,
      this.recordRange.endFrame !== this.durationFrames,
    );
  }

  // Frame numbers only appear for markers moved away from the timeline ends;
  // the untouched full range stays label-free.
  private updateRecordFrameLabel(
    label: HTMLDivElement,
    ratio: number,
    frame: number,
    visible: boolean,
  ): void {
    label.style.display = visible ? "" : "none";
    label.style.left = `${ratio * 100}%`;
    label.textContent = String(frame);
  }

  private setFrame(frame: number): void {
    const previousFrame = this.frame;
    this.frameValue = frame;
    const currentFrame = this.frame;
    this.slider.value = String(currentFrame);
    this.updateLabel();
    if (currentFrame !== previousFrame) {
      this.onFrame(currentFrame);
    }
    if (!this.playing) {
      this.updatePlayButtonIcon();
    }
  }

  private updateLabel(): void {
    this.frameLabel.textContent = `Frame ${this.frame} / ${this.durationFrames}`;
    this.secondsLabel.textContent = `${(this.frame / this.fps).toFixed(3)}s`;
    const maximumSecondsText = `${(this.durationFrames / this.fps).toFixed(3)}s`;
    this.secondsLabel.style.width = `${Math.max(maximumSecondsText.length, 6)}ch`;
  }
}
