import type { LuaCompletionTarget, LuaHookPhase } from "./scriptingApi";
import {
  luaReturnTypeTargets,
  membersForTarget,
  luaOptionValues,
  type LuaOptionValues,
} from "./scriptingApi";

export interface LuaCompletionContext {
  target: LuaCompletionTarget | "root";
  phase: LuaHookPhase;
}

// Where an unterminated string literal sits, which decides whose enumerated
// values may complete inside it. `field` covers both `ctx.global.h_align = "`
// and a table-constructor key such as `{ order = "`, since the candidates come
// from a named member either way; `argument` covers a positional call argument.
export type LuaStringLiteralContext =
  // `enclosingFunction` is set only for a bare table key, naming the call the
  // table is an argument of; it scopes keys whose meaning depends on the helper.
  | {
      kind: "field";
      receiver: string;
      fieldName: string;
      enclosingFunction?: string;
      phase: LuaHookPhase;
    }
  | { kind: "argument"; receiver: string; functionName: string; argumentIndex: number; phase: LuaHookPhase };

export function resolveLuaCompletionContext(sourceBeforeCursor: string): LuaCompletionContext {
  const phase = resolveHookPhase(sourceBeforeCursor);
  // The trailing separator is "." for field access and ":" for a method call
  // (path:at_distance), so both terminate a receiver.
  const receiverMatch = /([A-Za-z_]\w*(?:\s*\[[^\]\r\n]+\])?(?:\.[A-Za-z_]\w*(?:\s*\[[^\]\r\n]+\])?)*)[.:]\s*$/.exec(
    sourceBeforeCursor,
  );
  const receiver = receiverMatch?.[1].replace(/\s+/g, "") ?? "";
  return { target: resolveReceiver(receiver, sourceBeforeCursor), phase };
}

// Resolves the string literal the cursor sits in, or undefined when the cursor
// is not inside one. Only the literal's opening quote and the code before it
// matter, so the partially typed value itself is ignored -- the editor filters
// the returned candidates against it.
export function resolveLuaStringLiteralContext(
  sourceBeforeCursor: string,
): LuaStringLiteralContext | undefined {
  const openIndex = findOpenStringLiteral(sourceBeforeCursor);
  let result: LuaStringLiteralContext | undefined;
  if (openIndex !== undefined) {
    const phase = resolveHookPhase(sourceBeforeCursor);
    const beforeLiteral = sourceBeforeCursor.slice(0, openIndex);
    result = resolveFieldAssignment(beforeLiteral, phase)
      ?? resolveCallArgument(beforeLiteral, phase);
  }
  return result;
}

// Candidates for the string literal the cursor sits in, or an empty list when
// nothing enumerable applies there. Field and table-key contexts resolve by
// name; an argument context resolves by position within the call's parameters.
export function resolveLuaStringValues(sourceBeforeCursor: string): readonly string[] {
  const context = resolveLuaStringLiteralContext(sourceBeforeCursor);
  let values: readonly string[] = [];
  if (context !== undefined && context.kind === "field") {
    if (context.receiver.length > 0) {
      const target = resolveReceiver(context.receiver, sourceBeforeCursor);
      if (target !== "root") {
        values = membersForTarget(target, context.phase)
          .find(({ name }) => name === context.fieldName)?.values ?? [];
      }
    }
    if (values.length === 0 && context.enclosingFunction !== undefined) {
      // A bare table key. Its meaning can depend on the helper reading it, so
      // only an entry listing the enclosing call contributes candidates.
      const enclosingFunction = context.enclosingFunction;
      const options: readonly LuaOptionValues[] = luaOptionValues;
      values = options.find(
        (option) => option.name === context.fieldName
          && option.functions.includes(enclosingFunction),
      )?.values ?? [];
    }
  } else if (context?.kind === "argument") {
    const target = resolveReceiver(context.receiver, sourceBeforeCursor);
    if (target !== "root") {
      const member = membersForTarget(target, context.phase)
        .find(({ name }) => name === context.functionName);
      const parameterName = member?.parameters?.[context.argumentIndex];
      if (parameterName !== undefined && member?.parameterValues !== undefined) {
        values = member.parameterValues[parameterName]
          // Optional parameters carry a trailing "?" in their declared name.
          ?? member.parameterValues[parameterName.replace(/\?$/, "")]
          ?? [];
      }
    }
  }
  return values;
}

// Walks the source tracking quote state so that a quote inside an already
// closed literal, an escaped quote, or a quote in a comment cannot be mistaken
// for an opening one. Returns the index of the quote that is still open at the
// cursor. Long strings ([[...]]) never carry enumerated values, so a literal
// opened by one is reported as no context rather than as an open quote.
function findOpenStringLiteral(source: string): number | undefined {
  let openIndex: number | undefined;
  let quote: string | undefined;
  let index = 0;
  while (index < source.length) {
    const character = source[index];
    if (quote !== undefined) {
      if (character === "\\") {
        index += 1;
      } else if (character === quote || character === "\n") {
        // Lua forbids a raw newline inside a short literal, so an unterminated
        // one ends at the line break rather than swallowing the rest of the file.
        quote = undefined;
        openIndex = undefined;
      }
    } else if (character === "-" && source.startsWith("--", index)) {
      const lineEnd = source.indexOf("\n", index);
      index = lineEnd === -1 ? source.length : lineEnd;
    } else if (character === "[" && /^\[=*\[/.test(source.slice(index))) {
      const opener = /^\[(=*)\[/.exec(source.slice(index))?.[0] ?? "[[";
      const closer = `]${opener.slice(1, -1)}]`;
      const closeIndex = source.indexOf(closer, index + opener.length);
      index = closeIndex === -1 ? source.length : closeIndex + closer.length - 1;
    } else if (character === '"' || character === "'") {
      quote = character;
      openIndex = index;
    }
    index += 1;
  }
  return quote === undefined ? undefined : openIndex;
}

// `<receiver>.<field> = "` and the table-constructor form `<field> = "`, which
// is how config tables such as bounce_ground's are written. A bare field name
// has no receiver, so the caller resolves its candidates by name alone.
function resolveFieldAssignment(
  beforeLiteral: string,
  phase: LuaHookPhase,
): LuaStringLiteralContext | undefined {
  const assignmentMatch =
    /([A-Za-z_]\w*(?:\s*\[[^\]\r\n]+\])?(?:\.[A-Za-z_]\w*(?:\s*\[[^\]\r\n]+\])?)*)\.([A-Za-z_]\w*)\s*=\s*$/.exec(
      beforeLiteral,
    );
  let result: LuaStringLiteralContext | undefined;
  if (assignmentMatch !== null) {
    result = {
      kind: "field",
      receiver: assignmentMatch[1].replace(/\s+/g, ""),
      fieldName: assignmentMatch[2],
      phase,
    };
  } else {
    const tableKeyMatch = /(?:^|[\s{,;])([A-Za-z_]\w*)\s*=\s*$/.exec(beforeLiteral);
    if (tableKeyMatch !== null) {
      result = {
        kind: "field",
        receiver: "",
        fieldName: tableKeyMatch[1],
        enclosingFunction: findEnclosingFunctionName(beforeLiteral),
        phase,
      };
    }
  }
  return result;
}

// Name of the function whose argument list encloses a table constructor, found
// by stepping out of the table and reading the callee before the open paren.
function findEnclosingFunctionName(beforeLiteral: string): string | undefined {
  // Tables nest -- mt.keyframes takes a list of key tables -- so this steps out
  // through every enclosing table before looking for the call around them.
  let remaining = beforeLiteral;
  let braceIndex = findEnclosingTableStart(remaining);
  while (braceIndex !== undefined) {
    remaining = remaining.slice(0, braceIndex);
    const outerBrace = findEnclosingTableStart(remaining);
    if (outerBrace === undefined) {
      break;
    }
    braceIndex = outerBrace;
  }
  let name: string | undefined;
  if (braceIndex !== undefined) {
    const callStart = findEnclosingCallStart(remaining);
    if (callStart !== undefined) {
      name = /([A-Za-z_]\w*)\s*$/.exec(
        beforeLiteral.slice(0, callStart.parenIndex),
      )?.[1];
    }
  }
  return name;
}

// Scans backwards for the "{" the cursor's key sits directly inside, skipping
// balanced pairs so a nested table or call does not end the search early.
function findEnclosingTableStart(beforeLiteral: string): number | undefined {
  const closers: Record<string, string> = { ")": "(", "]": "[", "}": "{" };
  const pending: string[] = [];
  let index = beforeLiteral.length - 1;
  let found: number | undefined;
  while (index >= 0 && found === undefined) {
    const character = beforeLiteral[index];
    if (closers[character] !== undefined) {
      pending.push(closers[character]);
    } else if (character === "(" || character === "[" || character === "{") {
      if (pending.length > 0) {
        pending.pop();
      } else if (character === "{") {
        found = index;
      } else {
        // An unbalanced "(" or "[" first means the key is not inside a table.
        index = -1;
      }
    }
    index -= 1;
  }
  return found;
}

// `<receiver>.<function>(<arg>, ..., "` -- finds the call the literal is an
// argument of and counts the commas that separate it from the open paren.
function resolveCallArgument(
  beforeLiteral: string,
  phase: LuaHookPhase,
): LuaStringLiteralContext | undefined {
  const callStart = findEnclosingCallStart(beforeLiteral);
  let result: LuaStringLiteralContext | undefined;
  if (callStart !== undefined) {
    const calleeMatch =
      /([A-Za-z_]\w*(?:\s*\[[^\]\r\n]+\])?(?:\.[A-Za-z_]\w*(?:\s*\[[^\]\r\n]+\])?)*)[.:]([A-Za-z_]\w*)\s*$/.exec(
        beforeLiteral.slice(0, callStart.parenIndex),
      );
    if (calleeMatch !== null) {
      result = {
        kind: "argument",
        receiver: calleeMatch[1].replace(/\s+/g, ""),
        functionName: calleeMatch[2],
        argumentIndex: callStart.argumentIndex,
        phase,
      };
    }
  }
  return result;
}

// Scans backwards for the "(" the cursor is directly inside, skipping balanced
// bracket pairs so a nested call or table argument neither ends the search nor
// contributes its commas to the argument count.
function findEnclosingCallStart(
  beforeLiteral: string,
): { parenIndex: number; argumentIndex: number } | undefined {
  const closers: Record<string, string> = { ")": "(", "]": "[", "}": "{" };
  const pending: string[] = [];
  let argumentIndex = 0;
  let index = beforeLiteral.length - 1;
  let found: { parenIndex: number; argumentIndex: number } | undefined;
  while (index >= 0 && found === undefined) {
    const character = beforeLiteral[index];
    if (closers[character] !== undefined) {
      pending.push(closers[character]);
    } else if (character === "(" || character === "[" || character === "{") {
      if (pending.length > 0) {
        pending.pop();
      } else if (character === "(") {
        found = { parenIndex: index, argumentIndex };
      } else {
        // A "[" or "{" opened before any "(" means the literal sits in an index
        // or table constructor, not directly in an argument list.
        index = -1;
      }
    } else if (character === "," && pending.length === 0) {
      argumentIndex += 1;
    }
    index -= 1;
  }
  return found;
}

function resolveHookPhase(source: string): LuaHookPhase {
  const initializeIndex = source.lastIndexOf("function OnInitialize");
  const baseIndex = source.lastIndexOf("function OnPreLayout");
  const layoutIndex = source.lastIndexOf("function OnLayout");
  const pathIndex = source.lastIndexOf("function OnPath");
  const latestIndex = Math.max(initializeIndex, baseIndex, layoutIndex, pathIndex);
  let phase: LuaHookPhase = "layout";
  if (latestIndex >= 0 && latestIndex === initializeIndex) {
    phase = "initialize";
  } else if (latestIndex >= 0 && latestIndex === baseIndex) {
    phase = "pre_layout";
  } else if (latestIndex >= 0 && latestIndex === pathIndex) {
    phase = "path";
  }
  return phase;
}

function resolveReceiver(
  receiver: string,
  sourceBeforeCursor: string,
): LuaCompletionTarget | "root" {
  let target: LuaCompletionTarget | "root" = "root";
  if (receiver === "ctx") {
    target = "ctx";
  } else if (receiver === "ctx.canvas") {
    target = "canvas";
  } else if (receiver === "ctx.timeline") {
    target = "timeline";
  } else if (receiver === "ctx.font") {
    target = "font";
  } else if (receiver === "ctx.meta") {
    target = "meta";
  } else if (receiver === "ctx.meta.capabilities") {
    target = "capabilities";
  } else if (receiver === "ctx.meta.limits") {
    target = "limits";
  } else if (receiver === "ctx.inputs") {
    target = "script_inputs";
  } else if (receiver === "ctx.global") {
    target = "global";
  } else if (receiver === "ctx.global.fill") {
    target = "global_fill";
  } else if (receiver === "ctx.global.gradient") {
    target = "gradient";
  } else if (receiver === "ctx.global.stroke") {
    target = "global_stroke";
  } else if (receiver === "ctx.global.shadow") {
    target = "global_shadow";
  } else if (receiver === "ctx.camera") {
    target = "camera";
  } else if (receiver === "ctx.paths") {
    target = "path_collection";
  } else if (/^ctx\.chars\[[^\]]+\]$/.test(receiver)) {
    target = "character";
  } else if (/^ctx\.chars\[[^\]]+\]\.geometry$/.test(receiver)) {
    target = "character_geometry";
  } else if (/^ctx\.chars\[[^\]]+\]\.fill$/.test(receiver)) {
    target = "individual_fill";
  } else if (/^ctx\.chars\[[^\]]+\]\.stroke$/.test(receiver)) {
    target = "individual_stroke";
  } else if (/^ctx\.chars\[[^\]]+\]\.shadow$/.test(receiver)) {
    target = "individual_shadow";
  } else if (/^ctx\.parts\[[^\]]+\]$/.test(receiver)) {
    target = "part";
  } else if (/^ctx\.parts\[[^\]]+\]\.geometry$/.test(receiver)) {
    target = "part_geometry";
  } else if (/^ctx\.parts\[[^\]]+\]\.fill$/.test(receiver)) {
    target = "individual_fill";
  } else if (/^ctx\.parts\[[^\]]+\]\.stroke$/.test(receiver)) {
    target = "individual_stroke";
  } else if (/^ctx\.parts\[[^\]]+\]\.shadow$/.test(receiver)) {
    target = "individual_shadow";
  } else if (receiver === "ctx.bounding_box") {
    target = "bounding_box";
  } else if (receiver === "ctx.output") {
    target = "output";
  } else if (receiver === "mt") {
    target = "mt";
  } else if (receiver === "mt.ease") {
    target = "ease";
  } else if (receiver === "mt.color") {
    target = "color_utilities";
  } else if (receiver === "mt.path") {
    target = "path_utilities";
  } else if (receiver === "mt.layout") {
    target = "layout_utilities";
  } else if (receiver === "mt.timeline") {
    target = "timeline_utilities";
  } else if (receiver === "mt.text") {
    target = "text_utilities";
  } else if (/^[A-Za-z_]\w*\.path$/.test(receiver)) {
    const aliasTarget = resolveAlias(receiver.slice(0, -".path".length), sourceBeforeCursor);
    if (aliasTarget === "path_part") {
      target = "drawing_path";
    }
  } else if (isColorReceiver(receiver, sourceBeforeCursor)) {
    target = "color";
  } else if (/^[A-Za-z_]\w*\.char$/.test(receiver)) {
    // mt.each_part's info table reaches the owning character through .char.
    const aliasTarget = resolveAlias(receiver.slice(0, -".char".length), sourceBeforeCursor);
    if (aliasTarget === "each_info") {
      target = "character";
    }
  } else if (/^[A-Za-z_]\w*\.geometry$/.test(receiver)) {
    const aliasTarget = resolveAlias(receiver.slice(0, -".geometry".length), sourceBeforeCursor);
    if (aliasTarget === "character") {
      target = "character_geometry";
    } else if (aliasTarget === "part") {
      target = "part_geometry";
    }
  } else if (/^[A-Za-z_]\w*\.(?:fill|stroke|shadow)$/.test(receiver)) {
    const separatorIndex = receiver.lastIndexOf(".");
    const groupName = receiver.slice(separatorIndex + 1);
    const aliasTarget = resolveAlias(receiver.slice(0, separatorIndex), sourceBeforeCursor);
    if (aliasTarget === "character" || aliasTarget === "part") {
      target = groupName === "fill"
        ? "individual_fill"
        : groupName === "stroke"
          ? "individual_stroke"
          : "individual_shadow";
    }
  } else if (/^[A-Za-z_]\w*$/.test(receiver)) {
    target = resolveAlias(receiver, sourceBeforeCursor);
  }
  return target;
}

function isColorReceiver(receiver: string, source: string): boolean {
  const colorSuffix = /(?:\.color|\.end_color|\.fill_color)$/;
  let result = colorSuffix.test(receiver);
  if (!result && /^[A-Za-z_]\w*$/.test(receiver)) {
    const escaped = escapeRegExp(receiver);
    result = new RegExp(
      `local\\s+${escaped}\\s*=\\s*(?:ctx\\.global|ctx\\.chars\\s*\\[[^\\]]+\\]|ctx\\.parts\\s*\\[[^\\]]+\\])\\.(?:fill|stroke|shadow|gradient)\\.(?:color|end_color)\\b`,
    ).test(source);
  }
  return result;
}

// How an alias can come to hold an API object. The last binding to win is the
// one nearest the cursor, so a name rebound part-way through a script resolves
// to whatever it holds at that point.
//
// Two binding forms are recognised: a direct `local x = <expression>`, and a
// generic-for loop variable such as `for _, part in ipairs(<collection>)`,
// which is how scripts normally walk ctx.chars, ctx.parts and the part lists
// returned by ctx.paths.
const kAliasBindings: ReadonlyArray<{
  target: LuaCompletionTarget;
  // Matched against the right-hand side of a `local` binding.
  assigned?: string;
  // Matched against the collection an ipairs() loop iterates over. The loop
  // variable holds one element, so the target is the element's type.
  iterated?: string;
  // Matched against an mt.each_* iterator, which yields three values rather
  // than the two ipairs produces: index, element, info. `slot` picks which of
  // those the target describes.
  eachIterator?: string;
  slot?: 2 | 3;
}> = [
  { target: "character", assigned: "ctx\\.chars\\s*\\[[^\\]]+\\]", iterated: "ctx\\.chars" },
  { target: "part", assigned: "ctx\\.parts\\s*\\[[^\\]]+\\]", iterated: "ctx\\.parts" },
  {
    target: "path_part",
    assigned: "ctx\\.paths:part\\s*\\(",
    // :character() and :select() both return arrays of parts.
    iterated: "ctx\\.paths:(?:character|select)\\s*\\(",
  },
  { target: "character", eachIterator: "mt\\.each_char\\s*\\(", slot: 2 },
  { target: "part", eachIterator: "mt\\.each_part\\s*\\(", slot: 2 },
  { target: "each_info", eachIterator: "mt\\.each_(?:char|part)\\s*\\(", slot: 3 },
];

function resolveAlias(alias: string, source: string): LuaCompletionTarget | "root" {
  const escaped = escapeRegExp(alias);
  let target: LuaCompletionTarget | "root" = "root";
  let latestIndex = -1;
  for (const binding of kAliasBindings) {
    const patterns: string[] = [];
    if (binding.assigned !== undefined) {
      patterns.push(`local\\s+${escaped}\\s*=\\s*${binding.assigned}`);
    }
    if (binding.iterated !== undefined) {
      // The loop variable is the last name before "in"; an optional leading
      // index variable ("for i, char in ...") is skipped.
      patterns.push(
        `for\\s+(?:[A-Za-z_]\\w*\\s*,\\s*)?${escaped}\\s+in\\s+ipairs\\s*\\(\\s*${binding.iterated}`,
      );
    }
    if (binding.eachIterator !== undefined) {
      // "for index, element, info in mt.each_char(...)": the alias must sit in
      // the slot this binding describes. Earlier slots are matched as names so
      // a variable never resolves to the wrong position, and slot 2 allows a
      // trailing info name because the third value is optional at the call
      // site.
      const anyName = "[A-Za-z_]\\w*";
      const leading =
        binding.slot === 2
          ? `${anyName}\\s*,\\s*`
          : `${anyName}\\s*,\\s*${anyName}\\s*,\\s*`;
      const trailing = binding.slot === 2 ? `(?:\\s*,\\s*${anyName})?` : "";
      patterns.push(
        `for\\s+${leading}${escaped}${trailing}\\s+in\\s+${binding.eachIterator}`,
      );
    }
    for (const pattern of patterns) {
      const index = lastMatchIndex(new RegExp(pattern, "g"), source);
      if (index > latestIndex) {
        latestIndex = index;
        target = binding.target;
      }
    }
  }
  const functionAssignmentPattern = new RegExp(
    `local\\s+${escaped}\\s*=\\s*(mt(?:\\.[A-Za-z_]\\w*)*)\\.([A-Za-z_]\\w*)\\s*\\(`,
    "g",
  );
  for (const match of source.matchAll(functionAssignmentPattern)) {
    const receiver = match[1];
    const functionName = match[2];
    const receiverTarget = resolveReceiver(receiver, source.slice(0, match.index));
    if (receiverTarget === "root") {
      continue;
    }
    const member = membersForTarget(receiverTarget, resolveHookPhase(source))
      .find((candidate) => candidate.type === "function" && candidate.name === functionName);
    const firstReturn = member?.returns?.match(/^\s*(\{[^}]*\}|[^,]+)/)?.[1].trim();
    const returnedType = firstReturn?.split("|")
      .map((candidate) => candidate.trim())
      .find((candidate) => candidate in luaReturnTypeTargets);
    if (returnedType !== undefined && match.index > latestIndex) {
      latestIndex = match.index;
      target = luaReturnTypeTargets[returnedType];
    }
  }
  return target;
}

function lastMatchIndex(pattern: RegExp, source: string): number {
  let result = -1;
  for (const match of source.matchAll(pattern)) {
    result = match.index;
  }
  return result;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

export function isMugTypographyScript(source: string): boolean {
  const maxLinesToCheck = 5;
  const lines = source.split(/\r?\n/).slice(0, maxLinesToCheck);
  const magicCommentPattern = /--\s*@(?:mug|mt|mugtypography)\b/i;
  let isMugTypography = false;
  for (const line of lines) {
    if (magicCommentPattern.test(line)) {
      isMugTypography = true;
      break;
    }
  }
  return isMugTypography;
}

// The script's own "-- @title" directive, which names exported files (see
// WebHostAdapter.saveVideo / saveThumbnail) and identifies a gallery entry
// once it is submitted. Kept apart from parseMugMetadata because that
// describes the scene to set up, while this is only a label for the script.
export function parseScriptTitle(source: string): string {
  // Horizontal whitespace only: plain \s would let a valueless "-- @title"
  // swallow the following line as its value.
  const match = /^--[^\S\r\n]*@title[^\S\r\n]+(.+)$/m.exec(source);
  return match === null ? "" : match[1].trim();
}

// Reduces a title to something safe to hand a filesystem: the exported name
// is a download's suggested file name, so path separators and characters
// Windows rejects must not survive it. An empty result means the caller
// should fall back to its own default rather than emit a nameless file.
export function toFileNameSlug(title: string): string {
  return title
    .replace(/[\\/:*?"<>|]+/g, " ")
    .replace(/\s+/g, "_")
    .replace(/^[._]+|[._]+$/g, "")
    .slice(0, 60);
}

import type { Rgba } from "./sceneSchema";
import {
  parseScriptInputMetadataLines,
  type ScriptInputMetadata,
  type ScriptInputMetadataError,
} from "./scriptInputMetadata";

export interface MugMetadata {
  projection3D?: boolean;
  durationSeconds?: number;
  backgroundColor?: Rgba;
  fillColor?: Rgba;
  gradientEndColor?: Rgba;
  checkerboardBackground?: boolean;
  positionX?: number;
  positionY?: number;
  fontLang?: string;
  text?: string;
  scriptInputs?: ScriptInputMetadata;
  scriptInputError?: ScriptInputMetadataError;
}

// Kana and CJK ideographs, i.e. what makes a recommended text need a font with
// CJK coverage. Han alone is shared with Chinese, but the simulator only tells
// "needs a CJK font" from "Latin is enough", so it does not try to separate
// those; anything in these ranges resolves to "ja".
const kCjkTextPattern =
  /[　-〿぀-ヿㇰ-ㇿ㐀-䶿一-鿿豈-﫿＀-￯]/;

// Infers the font language from a recommended text, so `@recommend text` alone
// is enough for Japanese samples and `lang` only has to be spelled out when it
// disagrees with the text (or when no text is recommended at all).
export function inferFontLanguage(text: string): string | undefined {
  let result: string | undefined;
  if (kCjkTextPattern.test(text)) {
    result = "ja";
  }
  return result;
}

export function parseHexColor(hex: string): Rgba | undefined {
  const cleanHex = hex.trim().replace(/^#/, "");
  if (cleanHex.length === 6) {
    const r = parseInt(cleanHex.substring(0, 2), 16) / 255;
    const g = parseInt(cleanHex.substring(2, 4), 16) / 255;
    const b = parseInt(cleanHex.substring(4, 6), 16) / 255;
    if (Number.isFinite(r) && Number.isFinite(g) && Number.isFinite(b)) {
      return { r, g, b, a: 1 };
    }
  } else if (cleanHex.length === 8) {
    const r = parseInt(cleanHex.substring(0, 2), 16) / 255;
    const g = parseInt(cleanHex.substring(2, 4), 16) / 255;
    const b = parseInt(cleanHex.substring(4, 6), 16) / 255;
    const a = parseInt(cleanHex.substring(6, 8), 16) / 255;
    if (Number.isFinite(r) && Number.isFinite(g) && Number.isFinite(b) && Number.isFinite(a)) {
      return { r, g, b, a };
    }
  }
  return undefined;
}

// Resolves the escapes allowed inside a quoted `@recommend text "..."` value:
// `\n` for a line break, plus `\"`, `\'` and `\\` so quotes and backslashes can
// be written literally. Any other escape keeps its backslash, since inventing
// meanings for unknown escapes would silently mangle text.
function unescapeMetadataText(value: string): string {
  return value.replace(/\\(.)/g, (match, character: string) => {
    let result = match;
    if (character === "n") {
      result = "\n";
    } else if (character === '"' || character === "'" || character === "\\") {
      result = character;
    }
    return result;
  });
}

// Directive lines (`-- @MugTypography`, `-- @duration`, `-- @required`, ...)
// live in the header, as consecutive single-line `--` comments at the top of
// the file. The header ends at the first `--[[` block comment (the
// `@description` body) or the first non-comment line, whichever comes first,
// so scripts with a long description still have every directive recognized
// regardless of length.
function collectHeaderDirectiveLines(source: string): string[] {
  const lines = source.split(/\r?\n/);
  const directiveLines: string[] = [];
  for (const line of lines) {
    const trimmed = line.trimStart();
    if (trimmed === "") {
      directiveLines.push("");
      continue;
    }
    if (/^--\[\[/.test(trimmed)) {
      break;
    }
    if (/^--/.test(trimmed)) {
      directiveLines.push(trimmed);
    } else {
      break;
    }
  }
  return directiveLines;
}

export function parseMugMetadata(source: string): MugMetadata {
  const lines = collectHeaderDirectiveLines(source);
  const scriptInputResult = parseScriptInputMetadataLines(lines);
  const requiredPattern = /--\s*@required\s*(?:3d|3dprojection)\b/i;
  const durationPattern = /--\s*@duration\s*(\d+(?:\.\d+)?)\b/i;
  const recommendPattern = /--\s*@recommend(?:\.|\s+)(.*)$/i;

  let projection3D: boolean | undefined;
  let durationSeconds: number | undefined;
  let backgroundColor: Rgba | undefined;
  let fillColor: Rgba | undefined;
  let gradientEndColor: Rgba | undefined;
  let checkerboardBackground: boolean | undefined;
  let positionX: number | undefined;
  let positionY: number | undefined;
  let fontLang: string | undefined;
  let text: string | undefined;

  // A recommended text is quoted, since unlike the other keys its value may
  // contain spaces: `-- @recommend text "うふふふ"`. Either quote style works
  // (the backreference keeps the closing quote matched to the opening one), so
  // the other style can appear literally inside. Within the quotes, a `\n`
  // escape becomes a real newline so multi-line samples stay writable in a
  // single-line comment. The quotes also delimit the value, so this key can
  // share a line with the others.
  const textPattern = /\b(?:text|sample_text)\s+(["'])((?:[^\\]|\\.)*?)\1/i;

  for (const line of lines) {
    if (requiredPattern.test(line)) {
      projection3D = true;
    }
    const durationMatch = durationPattern.exec(line);
    if (durationMatch !== null) {
      const parsed = parseFloat(durationMatch[1]);
      if (Number.isFinite(parsed) && parsed > 0) {
        durationSeconds = parsed;
      }
    }
    const recommendMatch = recommendPattern.exec(line);
    if (recommendMatch !== null) {
      const body = recommendMatch[1].trim();
      const textMatch = textPattern.exec(body);
      if (textMatch !== null) {
        text = unescapeMetadataText(textMatch[2]);
      }
      if (/\b(?:checkerboard|checker)\b/i.test(body)) {
        checkerboardBackground = true;
      }
      if (/\bsolid\b/i.test(body)) {
        checkerboardBackground = false;
      }
      const backgroundColorMatch =
        /\b(?:bg|background)\s+(?:(?:checkerboard|checker|solid)\s+)*(#[0-9a-fA-F]{6,8})\b/i.exec(
          body,
        );
      if (backgroundColorMatch !== null) {
        const parsedColor = parseHexColor(backgroundColorMatch[1]);
        if (parsedColor !== undefined) {
          backgroundColor = parsedColor;
        }
      }
      const fillColorMatch =
        /\b(?:fill|fill_color)\s+(#[0-9a-fA-F]{6,8})\b/i.exec(body);
      if (fillColorMatch !== null) {
        fillColor = parseHexColor(fillColorMatch[1]);
      }
      const gradientColorMatch =
        /\b(?:gradient|gradient_color)\s+(#[0-9a-fA-F]{6,8})\b/i.exec(body);
      if (gradientColorMatch !== null) {
        gradientEndColor = parseHexColor(gradientColorMatch[1]);
      }
      const posMatch = /\b(?:pos|position|global_pos)\s+(-?\d+(?:\.\d+)?)\s+(-?\d+(?:\.\d+)?)\b/i.exec(body);
      if (posMatch !== null) {
        const x = parseFloat(posMatch[1]);
        const y = parseFloat(posMatch[2]);
        if (Number.isFinite(x) && Number.isFinite(y)) {
          positionX = x;
          positionY = y;
        }
      }
      const langMatch = /\b(?:lang|font_lang|fontLang)\s+([a-zA-Z0-9_-]+)\b/i.exec(body);
      if (langMatch !== null) {
        fontLang = langMatch[1];
      }
    }
  }

  // An explicit `lang` always wins; otherwise the recommended text implies it.
  if (fontLang === undefined && text !== undefined) {
    fontLang = inferFontLanguage(text);
  }

  const hasScriptInputs = [
    ...scriptInputResult.inputs.numbers,
    ...scriptInputResult.inputs.colors,
    ...scriptInputResult.inputs.texts,
  ].some((declaration) => declaration !== undefined);
  return {
    projection3D,
    durationSeconds,
    backgroundColor,
    fillColor,
    gradientEndColor,
    checkerboardBackground,
    positionX,
    positionY,
    fontLang,
    text,
    ...(hasScriptInputs ? { scriptInputs: scriptInputResult.inputs } : {}),
    ...(scriptInputResult.error === undefined ? {} : { scriptInputError: scriptInputResult.error }),
  };
}

export interface LuaLocalVariableHoverInfo {
  name: string;
  signature: string;
  type: string;
  value?: string;
  documentation?: string;
}

/**
 * Finds hover information for a local variable, function parameter, or loop variable at or above the cursor.
 */
export function findLocalVariableHover(
  source: string,
  word: string,
  lineIndex?: number,
): LuaLocalVariableHoverInfo | undefined {
  if (!/^[A-Za-z_]\w*$/.test(word)) {
    return undefined;
  }

  const reserved = new Set([
    "and", "break", "do", "else", "elseif", "end", "false", "for", "function",
    "goto", "if", "in", "local", "nil", "not", "or", "repeat", "return",
    "then", "true", "until", "while",
  ]);
  if (reserved.has(word)) {
    return undefined;
  }

  if (word === "mt") {
    return {
      name: "mt",
      signature: "mt: MugTypographyUtilities",
      type: "MugTypographyUtilities",
      documentation: "Mug Typography animation and scripting utility functions",
    };
  }

  const lines = source.split(/\r?\n/);
  const maxLine = lineIndex !== undefined ? Math.min(lineIndex, lines.length - 1) : lines.length - 1;

  for (let i = maxLine; i >= 0; i--) {
    const line = lines[i];

    // Pattern 1: `local function name(...)`
    const localFuncMatch = /^\s*local\s+function\s+([A-Za-z_]\w*)\s*\(([^)]*)\)/.exec(line);
    if (localFuncMatch !== null && localFuncMatch[1] === word) {
      return {
        name: word,
        signature: `local function ${word}(${localFuncMatch[2]})`,
        type: "function",
      };
    }

    // Pattern 2: `local var1, var2 = expr1, expr2`
    const localAssignMatch = /^\s*local\s+([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)\s*=\s*(.+)$/.exec(line);
    if (localAssignMatch !== null) {
      const vars = localAssignMatch[1].split(",").map((v) => v.trim());
      const varIndex = vars.indexOf(word);
      if (varIndex !== -1) {
        const rawExprs = splitLuaExpressions(localAssignMatch[2]);
        const expr = rawExprs[varIndex] ?? rawExprs[0] ?? "";
        return inferExpressionHover(word, expr.trim());
      }
    }

    // Pattern 3: `local var1, var2` (unassigned declaration)
    const localDeclMatch = /^\s*local\s+([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)\s*$/.exec(line);
    if (localDeclMatch !== null) {
      const vars = localDeclMatch[1].split(",").map((v) => v.trim());
      if (vars.includes(word)) {
        return {
          name: word,
          signature: `local ${word}: any`,
          type: "any",
        };
      }
    }

    // Pattern 4: `for i, char in ipairs(...)` or `mt.each_*(...)` or `pairs(...)`
    const forMatch = /^\s*for\s+([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)\s+in\s+(.+)\s+do/.exec(line);
    if (forMatch !== null) {
      const loopVars = forMatch[1].split(",").map((v) => v.trim());
      const varIdx = loopVars.indexOf(word);
      if (varIdx !== -1) {
        const iterExpr = forMatch[2].trim();
        return inferLoopVariableHover(word, varIdx, loopVars.length, iterExpr);
      }
    }

    // Pattern 5: Function parameter: `function OnPreLayout(ctx)` or `function(ctx, path)`
    const funcHeaderMatch = /function\s*(?:[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*)?\s*\(([^)]*)\)/.exec(line);
    if (funcHeaderMatch !== null) {
      const params = funcHeaderMatch[1].split(",").map((p) => p.trim());
      if (params.includes(word)) {
        if (word === "ctx") {
          return {
            name: word,
            signature: "ctx: HostContext",
            type: "HostContext",
            documentation: "Mug Typography host context object",
          };
        }
        if (word === "path") {
          return {
            name: word,
            signature: "path: DrawingPath",
            type: "DrawingPath",
            documentation: "Custom SVG path builder and evaluator",
          };
        }
        return {
          name: word,
          signature: `${word}: any (parameter)`,
          type: "any",
        };
      }
    }
  }

  return undefined;
}

function splitLuaExpressions(exprList: string): string[] {
  const result: string[] = [];
  let depth = 0;
  let quote: string | undefined;
  let start = 0;
  for (let i = 0; i < exprList.length; i++) {
    const ch = exprList[i];
    if (quote !== undefined) {
      if (ch === "\\") {
        i++;
      } else if (ch === quote) {
        quote = undefined;
      }
    } else if (ch === '"' || ch === "'") {
      quote = ch;
    } else if (ch === "(" || ch === "{" || ch === "[") {
      depth++;
    } else if (ch === ")" || ch === "}" || ch === "]") {
      depth--;
    } else if (ch === "," && depth === 0) {
      result.push(exprList.slice(start, i).trim());
      start = i + 1;
    }
  }
  if (start < exprList.length) {
    result.push(exprList.slice(start).trim());
  }
  return result;
}

function inferExpressionHover(word: string, expr: string): LuaLocalVariableHoverInfo {
  // Integer / Hex / Float
  if (/^-?(?:0[xX][0-9a-fA-F]+|\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)$/.test(expr)) {
    return {
      name: word,
      signature: `local ${word}: number = ${expr}`,
      type: "number",
      value: expr,
    };
  }

  // String literals
  if (/^"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|^\[\[.*\]\]$/s.test(expr)) {
    return {
      name: word,
      signature: `local ${word}: string = ${expr}`,
      type: "string",
      value: expr,
    };
  }

  // Boolean
  if (/^(?:true|false)$/.test(expr)) {
    return {
      name: word,
      signature: `local ${word}: boolean = ${expr}`,
      type: "boolean",
      value: expr,
    };
  }

  // Nil
  if (expr === "nil") {
    return {
      name: word,
      signature: `local ${word}: nil`,
      type: "nil",
    };
  }

  // Table
  if (/^\{.*\}$/s.test(expr)) {
    return {
      name: word,
      signature: `local ${word}: table`,
      type: "table",
    };
  }

  // Function
  if (/^function\s*\(/.test(expr)) {
    const params = /^function\s*\(([^)]*)\)/.exec(expr)?.[1] ?? "";
    return {
      name: word,
      signature: `local ${word}: function(${params})`,
      type: "function",
    };
  }

  // API Objects & Properties
  if (expr.includes("ctx.timeline.progress")) {
    return {
      name: word,
      signature: `local ${word}: number (ctx.timeline.progress)`,
      type: "number",
      documentation: "Normalized animation progress (0.0 to 1.0)",
    };
  }
  if (expr.includes("ctx.timeline.frame")) {
    return {
      name: word,
      signature: `local ${word}: integer (ctx.timeline.frame)`,
      type: "integer",
      documentation: "Current frame number (0-indexed)",
    };
  }
  if (expr.includes("ctx.timeline.fps") || expr.includes("ctx.timeline.duration")) {
    return { name: word, signature: `local ${word}: number`, type: "number" };
  }
  if (expr.includes("ctx.canvas.width") || expr.includes("ctx.canvas.height")) {
    return { name: word, signature: `local ${word}: number`, type: "number" };
  }
  if (/^ctx\.chars\s*\[/.test(expr)) {
    return {
      name: word,
      signature: `local ${word}: Character`,
      type: "Character",
      documentation: "Character layout & styling object",
    };
  }
  if (/^ctx\.parts\s*\[/.test(expr)) {
    return {
      name: word,
      signature: `local ${word}: Part`,
      type: "Part",
      documentation: "Part layout & styling object",
    };
  }
  if (/\.geometry$/.test(expr)) {
    return {
      name: word,
      signature: `local ${word}: Geometry`,
      type: "Geometry",
      documentation: "Position, scale, rotation and pivot settings",
    };
  }
  if (/\.fill$/.test(expr)) {
    return { name: word, signature: `local ${word}: IndividualFill`, type: "IndividualFill" };
  }
  if (/\.stroke$/.test(expr)) {
    return { name: word, signature: `local ${word}: IndividualStroke`, type: "IndividualStroke" };
  }
  if (/\.shadow$/.test(expr)) {
    return { name: word, signature: `local ${word}: IndividualShadow`, type: "IndividualShadow" };
  }
  if (expr === "ctx.timeline") {
    return {
      name: word,
      signature: `local ${word}: TimelineState`,
      type: "TimelineState",
      documentation: "Host timeline and playback state",
    };
  }
  if (expr === "ctx.canvas") {
    return {
      name: word,
      signature: `local ${word}: Canvas`,
      type: "Canvas",
      documentation: "Canvas dimensions and center coordinates",
    };
  }
  if (expr === "ctx.camera") {
    return { name: word, signature: `local ${word}: Camera3D`, type: "Camera3D" };
  }
  if (expr === "ctx.bounding_box") {
    return { name: word, signature: `local ${word}: BoundingBox`, type: "BoundingBox" };
  }
  if (expr === "ctx.global") {
    return { name: word, signature: `local ${word}: GlobalSettings`, type: "GlobalSettings" };
  }
  if (expr === "mt.ease") {
    return {
      name: word,
      signature: `local ${word}: EaseUtilities`,
      type: "EaseUtilities",
      documentation: "Easing and animation curve utilities",
    };
  }
  if (expr === "mt.color") {
    return {
      name: word,
      signature: `local ${word}: ColorUtilities`,
      type: "ColorUtilities",
      documentation: "Color conversions and gradients",
    };
  }
  if (expr === "mt.path") {
    return {
      name: word,
      signature: `local ${word}: PathUtilities`,
      type: "PathUtilities",
      documentation: "Path length and sampling utilities",
    };
  }
  if (expr === "mt.layout") {
    return { name: word, signature: `local ${word}: LayoutUtilities`, type: "LayoutUtilities" };
  }

  // Fallback to raw expression assignment
  return {
    name: word,
    signature: `local ${word} = ${expr}`,
    type: "any",
    value: expr,
  };
}

function inferLoopVariableHover(
  word: string,
  varIndex: number,
  totalVars: number,
  iterExpr: string,
): LuaLocalVariableHoverInfo {
  if (/^ipairs\s*\(\s*ctx\.chars\s*\)/.test(iterExpr)) {
    if (varIndex === 0 && totalVars > 1) {
      return { name: word, signature: `${word}: integer (character index)`, type: "integer" };
    }
    return {
      name: word,
      signature: `${word}: Character`,
      type: "Character",
      documentation: "Character layout & styling object",
    };
  }

  if (/^ipairs\s*\(\s*ctx\.parts\s*\)/.test(iterExpr)) {
    if (varIndex === 0 && totalVars > 1) {
      return { name: word, signature: `${word}: integer (part index)`, type: "integer" };
    }
    return {
      name: word,
      signature: `${word}: Part`,
      type: "Part",
      documentation: "Part layout & styling object",
    };
  }

  if (/^mt\.each_char\s*\(/.test(iterExpr)) {
    if (varIndex === 0) return { name: word, signature: `${word}: integer (index)`, type: "integer" };
    if (varIndex === 1) return { name: word, signature: `${word}: Character`, type: "Character" };
    if (varIndex === 2) {
      return {
        name: word,
        signature: `${word}: EachInfo`,
        type: "EachInfo",
        documentation: "Progress and layout information for current character",
      };
    }
  }

  if (/^mt\.each_part\s*\(/.test(iterExpr)) {
    if (varIndex === 0) return { name: word, signature: `${word}: integer (index)`, type: "integer" };
    if (varIndex === 1) return { name: word, signature: `${word}: Part`, type: "Part" };
    if (varIndex === 2) {
      return {
        name: word,
        signature: `${word}: EachInfo`,
        type: "EachInfo",
        documentation: "Progress and layout information for current part",
      };
    }
  }

  if (/^pairs\s*\(/.test(iterExpr)) {
    if (varIndex === 0) return { name: word, signature: `${word}: any (key)`, type: "any" };
    return { name: word, signature: `${word}: any (value)`, type: "any" };
  }

  if (/^ipairs\s*\(/.test(iterExpr)) {
    if (varIndex === 0 && totalVars > 1) return { name: word, signature: `${word}: integer (index)`, type: "integer" };
    return { name: word, signature: `${word}: any (element)`, type: "any" };
  }

  return {
    name: word,
    signature: `${word}: any (loop variable)`,
    type: "any",
  };
}
