export interface LuaMetadataCandidate {
  label: string;
  kind: "directive" | "subKey";
  insertText: string;
  detail?: string;
  description: string;
  descriptionJa: string;
  example?: string;
  tag?: string;
  replaceRange?: { startColumn: number; endColumn: number };
}

export interface LuaMetadataCompletionResult {
  candidates: readonly LuaMetadataCandidate[];
}

/**
 * Resolves metadata directive completion candidates from the entire line and 1-indexed column.
 */
export function resolveLuaMetadataCompletion(
  line: string,
  column: number,
): LuaMetadataCompletionResult | undefined {
  const lineBeforeCursor = line.slice(0, column - 1);
  const lineAfterCursor = line.slice(column - 1);

  if (!/^\s*--/.test(lineBeforeCursor)) {
    return undefined;
  }

  const inputDefaultMatch = /--\s*@input\s+(number|color|text)\s+\d+\s+"(?:\\.|[^"\\])*"\s+([A-Za-z=]*)$/i.exec(
    lineBeforeCursor,
  );
  if (inputDefaultMatch !== null) {
    const inputType = inputDefaultMatch[1].toLowerCase();
    const prefixLength = inputDefaultMatch[2].length;
    const startColumn = column - prefixLength;
    const defaultInsertText = inputType === "color"
      ? "default={${1:1.0}, ${2:1.0}, ${3:1.0}, ${4:1.0}}"
      : inputType === "text"
        ? 'default="${1:Text}"'
        : kInputDefaultSubKey.insertText;
    return {
      candidates: [{
        ...kInputDefaultSubKey,
        kind: "subKey",
        insertText: defaultInsertText,
        replaceRange: { startColumn, endColumn: column },
      }],
    };
  }

  const inputSlotMatch = /--\s*@input\s+(number|color|text)\s+(\d*)$/i.exec(lineBeforeCursor);
  if (inputSlotMatch !== null) {
    const inputType = inputSlotMatch[1].toLowerCase() as "number" | "color" | "text";
    const prefixLength = inputSlotMatch[2].length;
    const startColumn = column - prefixLength;
    return {
      candidates: makeInputSlotCandidates(inputType).map((candidate) => ({
        ...candidate,
        kind: "subKey",
        replaceRange: { startColumn, endColumn: column },
      })),
    };
  }

  const inputTypeMatch = /--\s*@input\s+([A-Za-z]*)$/i.exec(lineBeforeCursor);
  if (inputTypeMatch !== null) {
    const prefixLength = inputTypeMatch[1].length;
    const startColumn = column - prefixLength;
    return {
      candidates: kInputTypeSubKeys.map((candidate) => ({
        ...candidate,
        kind: "subKey",
        replaceRange: { startColumn, endColumn: column },
      })),
    };
  }

  const bgMatch = /--\s*@recommend\s+bg\s+([A-Za-z0-9_#-]*)$/i.exec(lineBeforeCursor);
  if (bgMatch !== null) {
    const prefixLen = bgMatch[1].length;
    const startColumn = column - prefixLen;
    return {
      candidates: kRecommendBgSubKeys.map((item) => ({
        label: item.label,
        kind: "subKey",
        insertText: item.insertText,
        detail: item.label,
        description: item.description,
        descriptionJa: item.descriptionJa,
        replaceRange: { startColumn, endColumn: column },
      })),
    };
  }

  const langMatch = /--\s*@recommend\s+lang\s+([A-Za-z0-9_-]*)$/i.exec(lineBeforeCursor);
  if (langMatch !== null) {
    const prefixLen = langMatch[1].length;
    const startColumn = column - prefixLen;
    return {
      candidates: kRecommendLangSubKeys.map((item) => ({
        label: item.label,
        kind: "subKey",
        insertText: item.insertText,
        detail: item.label,
        description: item.description,
        descriptionJa: item.descriptionJa,
        replaceRange: { startColumn, endColumn: column },
      })),
    };
  }

  const recommendMatch = /--\s*@recommend\s+([A-Za-z0-9_-]*)$/i.exec(lineBeforeCursor);
  if (recommendMatch !== null) {
    const prefixLen = recommendMatch[1].length;
    const startColumn = column - prefixLen;
    return {
      candidates: kRecommendSubKeys.map((item) => ({
        label: item.label,
        kind: "subKey",
        insertText: item.insertText,
        detail: item.label,
        description: item.description,
        descriptionJa: item.descriptionJa,
        replaceRange: { startColumn, endColumn: column },
      })),
    };
  }

  const requiredMatch = /--\s*@required\s+([A-Za-z0-9_-]*)$/i.exec(lineBeforeCursor);
  if (requiredMatch !== null) {
    const prefixLen = requiredMatch[1].length;
    const startColumn = column - prefixLen;
    return {
      candidates: kRequiredSubKeys.map((item) => ({
        label: item.label,
        kind: "subKey",
        insertText: item.insertText,
        detail: item.label,
        description: item.description,
        descriptionJa: item.descriptionJa,
        replaceRange: { startColumn, endColumn: column },
      })),
    };
  }

  // Block comment opening: `--[[` or `--[[ @` or `--[[ @desc`
  const blockCommentMatch = /^(\s*--\[\[\s*)(@?[A-Za-z0-9_]*)$/.exec(lineBeforeCursor);
  if (blockCommentMatch !== null) {
    const prefixLen = blockCommentMatch[2].length;
    const startColumn = column - prefixLen;
    const hasClosingBrackets = /^\s*\]\]/.test(lineAfterCursor);
    const descDirective = kMetadataDirectives.find((item) => item.tag === "description");
    if (descDirective !== undefined) {
      const insertText = hasClosingBrackets
        ? "@description\n${1:Description of the script}\n"
        : "@description\n${1:Description of the script}\n]]";
      return {
        candidates: [
          {
            label: descDirective.name,
            kind: "directive",
            tag: descDirective.tag,
            insertText,
            detail: `-- ${descDirective.name}`,
            description: descDirective.description,
            descriptionJa: descDirective.descriptionJa,
            example: descDirective.example,
            replaceRange: { startColumn, endColumn: column },
          },
        ],
      };
    }
  }

  // Single-line comment header directive: `--`, `-- `, `--@`, `-- @`, `-- @tit`, etc.
  const directiveLineMatch = /^(\s*--\s*)(@?[A-Za-z0-9_]*)$/.exec(lineBeforeCursor);
  if (directiveLineMatch !== null) {
    const dashIdx = lineBeforeCursor.indexOf("--");
    const dashEndCol = dashIdx + 3; // 1-indexed column right after `--`
    const prefixLen = directiveLineMatch[2].length;
    const prefixStartCol = column - prefixLen;
    const hasSpaceAfterDash = lineBeforeCursor.slice(dashIdx + 2).startsWith(" ");

    return {
      candidates: kMetadataDirectives.map((directive) => {
        if (directive.tag === "description") {
          // Replace from right after `--` so `--@` or `-- ` cleanly turns into `--[[ @description ... ]]`
          return {
            label: directive.name,
            kind: "directive" as const,
            tag: directive.tag,
            insertText: "[[ @description\n${1:Description of the script}\n]]",
            detail: `-- ${directive.name}`,
            description: directive.description,
            descriptionJa: directive.descriptionJa,
            example: directive.example,
            replaceRange: { startColumn: dashEndCol, endColumn: column },
          };
        }

        if (!hasSpaceAfterDash) {
          // e.g. `--@` -> replace `@` with ` @title ${1:Untitled}` (adds leading space)
          return {
            label: directive.name,
            kind: "directive" as const,
            tag: directive.tag,
            insertText: ` @${directive.tag} ${directive.insertText.slice(directive.name.length + 1)}`,
            detail: `-- ${directive.name}`,
            description: directive.description,
            descriptionJa: directive.descriptionJa,
            example: directive.example,
            replaceRange: { startColumn: dashEndCol, endColumn: column },
          };
        }

        // e.g. `-- ` or `-- @`
        return {
          label: directive.name,
          kind: "directive" as const,
          tag: directive.tag,
          insertText: directive.insertText,
          detail: `-- ${directive.name}`,
          description: directive.description,
          descriptionJa: directive.descriptionJa,
          example: directive.example,
          replaceRange: { startColumn: prefixStartCol, endColumn: column },
        };
      }),
    };
  }

  return undefined;
}

export interface LuaMetadataHoverInfo {
  name: string;
  signature: string;
  description: string;
  example: string;
}

/**
 * Finds hover documentation for a metadata directive keyword under the cursor.
 */
export function findMetadataDirectiveHover(word: string, isJapanese: boolean): LuaMetadataHoverInfo | undefined {
  const normalized = word.startsWith("@") ? word : `@${word}`;
  const directive = kMetadataDirectives.find(
    (item) => item.name.toLowerCase() === normalized.toLowerCase() || item.tag.toLowerCase() === word.toLowerCase(),
  );
  if (directive !== undefined) {
    return {
      name: directive.name,
      signature: `-- ${directive.name}`,
      description: isJapanese ? directive.descriptionJa : directive.description,
      example: directive.example,
    };
  }

  const allSubCandidates: readonly LuaMetadataSubCandidate[] = [
    ...kRecommendSubKeys,
    ...kRecommendBgSubKeys,
    ...kRecommendLangSubKeys,
    ...kRequiredSubKeys,
    ...kInputTypeSubKeys,
    kInputDefaultSubKey,
  ];
  const subKey = allSubCandidates.find((item) => item.label.toLowerCase() === word.toLowerCase());
  if (subKey !== undefined) {
    return {
      name: subKey.label,
      signature: `-- @recommend ${subKey.label}`,
      description: isJapanese ? subKey.descriptionJa : subKey.description,
      example: `-- @recommend ${subKey.insertText.replace(/\$\{\d+:?([^}]*)\}/g, "$1")}`,
    };
  }

  return undefined;
}

function numberSequence(count: number): number[] {
  return Array.from({ length: count }, (_, index) => index + 1);
}

function makeInputSlotCandidates(
  inputType: "number" | "color" | "text",
): LuaMetadataSubCandidate[] {
  const count = inputType === "number"
    ? kScriptInputNumberCount
    : inputType === "color"
      ? kScriptInputColorCount
      : kScriptInputTextCount;
  return numberSequence(count).map((slot) => {
    let insertText = `${slot} "\${1:Number}" default=\${2:0.0}`;
    if (inputType === "color") {
      insertText = `${slot} "\${1:Color}" default={\${2:1.0}, \${3:1.0}, \${4:1.0}, \${5:1.0}}`;
    } else if (inputType === "text") {
      insertText = `${slot} "\${1:Text}" default="\${2:}"`;
    }
    return {
      label: String(slot),
      insertText,
      description: `${inputType} input slot ${slot}.`,
      descriptionJa: `${inputType}入力のslot ${slot}。`,
    };
  });
}
