import type { SystemFontEntry } from "../shared/messages";
import { onLocaleChange, t } from "../shared/i18n";
import {
  applyMetadataToScene,
  synchronizeScriptInputMetadata,
  type Scene,
} from "../shared/sceneSchema";
import { parseMugMetadata, type MugMetadata } from "../shared/luaCompletionContext";
import type { ScriptInputMetadata } from "../shared/scriptInputMetadata";
import { FrameEvaluator, type SceneTopology } from "../core/frameEvaluator";
import { HarfBuzzApi, TextLayoutEngine } from "../core/layout";
import { ScriptEngine } from "../core/luaEngine";
import { ScriptReloadQueue } from "../core/scriptReloadQueue";
import type { FontBytesResult, HostAdapter, InitPayload, TargetPayload } from "../platform/host";
import { PreviewCanvas } from "../webview/previewCanvas";
import { Inspector } from "../webview/inspector";
import { Timeline } from "../webview/timeline";
import { Toolbar } from "../webview/toolbar";
import { OutputValuesView } from "../webview/outputValuesView";
import type { VideoRecorder, VideoRecorderFormat } from "../webview/videoRecorder";
import { mountPluginCompatibilityNotice } from "../webview/pluginCompatibilityNotice";
import { renderFrame as drawFrame } from "../core/renderer";

// Sash drags may only consume the preview area's shrinkable space; clamping to
// a viewport-derived maximum keeps the sash glued to the cursor instead of
// letting the panel stack overflow below the window.
const kMinPreviewAreaHeight = 100;
const kMinPanelHeight = 100;
const kMinInspectorWidth = 180;
const kMaxInspectorWidth = 600;
// High enough that the compression is not visible at card size, while still
// landing far below the 500 KB a gallery thumbnail may occupy.
const kThumbnailWebpQuality = 0.92;

export interface SimulatorLayoutAdapter {
  mount(app: HTMLElement): void;
  reset(): void;
}

export interface SimulatorAppOptions {
  showPluginCompatibilityNotice?: boolean;
}

// Owns the simulator UI: preview canvas, inspector, timeline, and the Lua
// engine wired through them. Platform differences (VSCode webview vs. a
// standalone web page) are confined entirely to the injected HostAdapter;
// this class never talks to acquireVsCodeApi(), postMessage, or the DOM APIs
// that only exist in one of the two environments (aside from lazily loading
// the recording-only VideoRecorder module, gated on host.capabilities.recording).
export class SimulatorApp {
  private engine: ScriptEngine | undefined;
  private evaluator: FrameEvaluator | undefined;
  private hb: HarfBuzzApi | undefined;
  private scene: Scene | undefined;
  private timeline: Timeline | undefined;
  private toolbar: Toolbar | undefined;
  private preview: PreviewCanvas | undefined;
  private inspector: Inspector | undefined;
  private outputValues: OutputValuesView | undefined;
  private topology: SceneTopology | undefined;
  private statusBar: HTMLElement | undefined;
  private fontList: SystemFontEntry[] = [];
  private readonly loadingFontFamilies = new Set<string>();
  private luaUri = "";
  // Hook errors/warnings repeat every frame during playback; report each
  // distinct message once per script load.
  private reportedMessages = new Set<string>();
  private globalLoop = true;
  private recorder: VideoRecorder | undefined;
  private recordingOverlay: HTMLElement | undefined;
  private recordingProgress: HTMLElement | undefined;
  private recordingStartFrame = 0;
  private recordingEndFrame = 0;
  private lastRecordedFrame = 0;
  private recordingRun: Promise<boolean> | undefined;
  private recordingAborted = false;
  private recordingDiscarded = false;
  private finishingRecording = false;
  private inspectorWidth = Number(localStorage.getItem("mt-inspector-width") ?? "280");
  private inspectorCollapsed = localStorage.getItem("mt-inspector-collapsed") === "true";
  private inspectorHeight = Number(localStorage.getItem("mt-inspector-height") ?? "300");
  private outputValuesHeight = Number(localStorage.getItem("mt-output-values-height") ?? "200");
  private readonly scriptReloadQueue: ScriptReloadQueue;
  private layoutResizeHandler: (() => void) | undefined;
  private layoutResizeObserver: ResizeObserver | undefined;
  private metadata?: MugMetadata;
  private validScriptInputMetadata?: ScriptInputMetadata;
  private appElement: HTMLElement | undefined;
  private compatibilityNoticeDispose: (() => void) | undefined;

  constructor(
    private readonly host: HostAdapter,
    private readonly layoutAdapter?: SimulatorLayoutAdapter,
    private readonly options: SimulatorAppOptions = {},
  ) {
    this.scriptReloadQueue = new ScriptReloadQueue(
      (source, scriptGeneration) => this.reloadScript(source, scriptGeneration),
      (error) => showFatalError(error),
    );
  }

  // Narrow-layout switches (inspector/output panel stacking) key off the #app
  // container's own width, not window.innerWidth: in the VSCode webview build
  // #app fills the whole panel so the two were equivalent, but the web build
  // places #app beside an editor pane, so window.innerWidth includes space
  // #app doesn't actually have.
  private isNarrowLayout(): boolean {
    return (this.appElement?.getBoundingClientRect().width ?? window.innerWidth) <= 760;
  }

  async start(message: InitPayload): Promise<void> {
    this.luaUri = message.luaUri;
    this.scene = message.scene;
    this.globalLoop = message.globalLoop;
    this.fontList = message.fontList;
    this.validScriptInputMetadata = undefined;
    this.metadata = this.synchronizeMetadata(parseMugMetadata(message.luaSource), false);
    const harfBuzzPromise = import(/* @vite-ignore */ message.hbModuleUri)
      .then((api) => ({ api }))
      .catch((error: unknown) => ({ error }));
    this.engine = await ScriptEngine.create({
      wasmUri: message.wasmUri,
      preludeSource: message.preludeSource,
      log: (text) => this.host.log(text),
    });
    this.evaluator = new FrameEvaluator(this.engine);
    this.evaluator.setFontNames([...new Set(message.fontList.map((font) => font.family))]);
    const harfBuzzResult = await harfBuzzPromise;
    if ("api" in harfBuzzResult) {
      this.hb = harfBuzzResult.api as HarfBuzzApi;
    } else {
      this.host.warn(
        `HarfBuzz failed to load; falling back to box layout (${String(harfBuzzResult.error)})`,
      );
    }
    if (this.hb !== undefined && message.fontBytes !== undefined && message.fontPath !== undefined) {
      const layoutEngine = new TextLayoutEngine(this.hb, message.fontBytes);
      this.evaluator.setLayoutEngine(layoutEngine);
      this.scene.global.fontName = layoutEngine.familyName();
      this.scene.settings.fontPath = message.fontPath;
    }
    this.buildUi();
    await this.reloadScript(message.luaSource);
  }

  private buildUi(): void {
    if (this.scene === undefined) {
      return;
    }
    const scene = this.scene;
    this.topology = this.evaluator?.synchronizeSceneTopology(scene) ?? {
      characterCount: 0,
      partCount: 0,
    };
    const app = document.getElementById("app");
    if (app === null) {
      return;
    }
    this.disposeUi();
    this.appElement = app;
    app.replaceChildren();
    if (this.options.showPluginCompatibilityNotice === true) {
      this.compatibilityNoticeDispose = mountPluginCompatibilityNotice(document.body);
    }
    this.toolbar = new Toolbar(
      app,
      {
        displayMode: scene.settings.displayMode,
        partMode: scene.settings.partMode,
        partsPerCharacter: scene.settings.partsPerCharacter,
      },
      {
        onSettingsChanged: (state) => {
          const activeScene = this.scene;
          if (activeScene !== undefined) {
            activeScene.settings.displayMode = state.displayMode;
            activeScene.settings.partMode = state.partMode;
            activeScene.settings.partsPerCharacter = state.partsPerCharacter;
            // Part configuration changes part_count, which is an init input.
            this.reinitialize();
            this.timeline?.refresh();
            this.postSceneChanged(activeScene);
          }
        },
        onCopyScript: () => this.host.copyScript(this.luaUri),
        onResetLayout: () => this.resetLayout(),
      },
    );
    this.toolbar.setTopology(this.topology.characterCount, this.topology.partCount);
    const simulatorBody = document.createElement("div");
    simulatorBody.className = "simulator-body";
    app.appendChild(simulatorBody);
    const previewColumn = document.createElement("div");
    previewColumn.className = "preview-column";
    simulatorBody.appendChild(previewColumn);

    const openButton = document.createElement("button");
    openButton.type = "button";
    openButton.className = "inspector-open-button";
    openButton.title = t("inspector.expand");
    openButton.textContent = t("inspector.expandLabel");
    openButton.style.display = "none";
    openButton.addEventListener("click", () => {
      this.toggleInspectorCollapse(false);
    });
    previewColumn.appendChild(openButton);
    onLocaleChange(() => {
      openButton.title = t("inspector.expand");
      openButton.textContent = t("inspector.expandLabel");
    });

    const previewArea = document.createElement("div");
    previewArea.className = "preview-area";
    previewColumn.appendChild(previewArea);
    this.preview = new PreviewCanvas(previewArea, (control) => this.toolbar?.addLeadingControl(control));
    this.statusBar = document.createElement("div");
    this.statusBar.className = "status-bar";
    previewColumn.appendChild(this.statusBar);
    this.timeline = new Timeline(
      previewColumn,
      scene.settings.durationFrames,
      scene.settings.fps,
      this.globalLoop,
      (frame) => this.renderFrame(frame),
      (loop) => {
        this.globalLoop = loop;
        this.host.setLoopPreference(loop);
      },
      (startFrame, endFrame) => void this.startRecording(startFrame, endFrame),
      this.host.saveThumbnail === undefined ? undefined : () => void this.saveThumbnail(),
    );

    const sashVertical = document.createElement("div");
    sashVertical.className = "sash-vertical";
    simulatorBody.appendChild(sashVertical);

    let startVertX = 0;
    let startVertY = 0;
    let startVertWidth = 0;
    let startVertHeight = 0;
    let maxVertHeight = 0;
    let verticalPreviewSlack = 0;
    let verticalOutputSlack = 0;
    let verticalStartOutputHeight = 0;
    let verticalOutputStacked = false;
    const onMouseMoveVertical = (e: MouseEvent) => {
      const inspectorEl = simulatorBody.querySelector(".inspector") as HTMLElement | null;
      if (inspectorEl === null) {
        return;
      }
      if (this.isNarrowLayout()) {
        const deltaY = startVertY - e.clientY;
        const newHeight = Math.max(kMinPanelHeight, Math.min(maxVertHeight, startVertHeight + deltaY));
        this.inspectorHeight = newHeight;
        localStorage.setItem("mt-inspector-height", String(newHeight));
        inspectorEl.style.height = `${newHeight}px`;
        inspectorEl.style.minHeight = "";
        inspectorEl.style.maxHeight = "none";
        if (verticalOutputStacked) {
          // Pin the stacked output panel to an explicit height during the
          // drag: growth beyond the preview's slack comes out of it directly,
          // and it never shrinks as a flexbox side effect.
          const consumedFromOutput = Math.min(
            verticalOutputSlack,
            Math.max(0, newHeight - startVertHeight - verticalPreviewSlack),
          );
          const outputValuesEl = app.querySelector(".output-values") as HTMLElement | null;
          if (outputValuesEl !== null) {
            const newOutputHeight = verticalStartOutputHeight - consumedFromOutput;
            this.outputValuesHeight = newOutputHeight;
            localStorage.setItem("mt-output-values-height", String(newOutputHeight));
            outputValuesEl.style.height = `${newOutputHeight}px`;
            outputValuesEl.style.maxHeight = "none";
            outputValuesEl.style.minHeight = "0";
          }
        }
      } else {
        const deltaX = startVertX - e.clientX;
        const newWidth = Math.max(kMinInspectorWidth, Math.min(kMaxInspectorWidth, startVertWidth + deltaX));
        this.inspectorWidth = newWidth;
        localStorage.setItem("mt-inspector-width", String(newWidth));
        inspectorEl.style.width = `${newWidth}px`;
        inspectorEl.style.minHeight = "";
      }
    };
    const endVerticalDrag = () => {
      document.body.classList.remove("is-dragging-vertical");
      document.body.classList.remove("is-dragging-horizontal");
    };
    // Pointer capture keeps move/up events flowing to the sash even when the
    // button is released outside the webview, so a drag can never get stuck.
    sashVertical.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      if (this.inspectorCollapsed) {
        this.toggleInspectorCollapse(false);
      }
      startVertX = e.clientX;
      startVertY = e.clientY;
      startVertWidth = this.inspectorWidth;
      // Measure the rendered heights: flexbox may have shrunk the panel below
      // its stored height, and the drag must start from what the user sees.
      const inspectorEl = simulatorBody.querySelector(".inspector") as HTMLElement | null;
      startVertHeight = inspectorEl?.getBoundingClientRect().height ?? this.inspectorHeight;
      verticalPreviewSlack = Math.max(0, previewArea.getBoundingClientRect().height - kMinPreviewAreaHeight);
      const outputValuesEl = app.querySelector(".output-values") as HTMLElement | null;
      verticalOutputStacked = this.isNarrowLayout()
        && outputValuesEl !== null
        && !outputValuesEl.classList.contains("collapsed");
      verticalStartOutputHeight = verticalOutputStacked && outputValuesEl !== null
        ? outputValuesEl.getBoundingClientRect().height
        : 0;
      verticalOutputSlack = Math.max(0, verticalStartOutputHeight - kMinPanelHeight);
      maxVertHeight = startVertHeight + verticalPreviewSlack + verticalOutputSlack;
      if (this.isNarrowLayout()) {
        document.body.classList.add("is-dragging-horizontal");
      } else {
        document.body.classList.add("is-dragging-vertical");
      }
      sashVertical.setPointerCapture(e.pointerId);
    });
    sashVertical.addEventListener("pointermove", (e) => {
      if (!sashVertical.hasPointerCapture(e.pointerId)) {
        return;
      }
      onMouseMoveVertical(e);
    });
    sashVertical.addEventListener("pointerup", endVerticalDrag);
    sashVertical.addEventListener("pointercancel", endVerticalDrag);

    this.inspector = new Inspector(
      simulatorBody,
      scene,
      this.topology.characterCount,
      this.topology.partCount,
      () => {
        const activeScene = this.scene;
        if (activeScene !== undefined) {
          this.reinitialize();
          this.timeline?.updateConfiguration(
            activeScene.settings.durationFrames,
            activeScene.settings.fps,
            this.globalLoop,
          );
          this.timeline?.refresh();
          this.postSceneChanged(activeScene);
        }
      },
      {
        fonts: this.fontList,
        onSelected: (path) => this.host.requestFont(path, this.luaUri, "selected"),
      },
      () => this.toggleInspectorCollapse(!this.inspectorCollapsed),
      this.metadata,
    );

    const sashHorizontal = document.createElement("div");
    sashHorizontal.className = "sash-horizontal";
    app.appendChild(sashHorizontal);

    let startY = 0;
    let startHeight = 0;
    let maxHorizontalHeight = 0;
    let horizontalPreviewSlack = 0;
    let horizontalInspectorSlack = 0;
    let horizontalStartInspectorHeight = 0;
    let horizontalInspectorStacked = false;
    const onMouseMoveHorizontal = (e: MouseEvent) => {
      const deltaY = startY - e.clientY;
      const newHeight = Math.max(kMinPanelHeight, Math.min(maxHorizontalHeight, startHeight + deltaY));
      this.outputValuesHeight = newHeight;
      localStorage.setItem("mt-output-values-height", String(newHeight));
      const outputValuesEl = app.querySelector(".output-values") as HTMLElement | null;
      if (outputValuesEl !== null) {
        outputValuesEl.style.height = `${newHeight}px`;
        outputValuesEl.style.maxHeight = "none";
        outputValuesEl.style.minHeight = "0";
      }
      if (horizontalInspectorStacked) {
        // Pin the stacked inspector to an explicit height during the drag:
        // growth beyond the preview's slack comes out of it directly, and it
        // never shrinks as a flexbox side effect (which would detach the sash
        // from the cursor).
        const consumedFromInspector = Math.min(
          horizontalInspectorSlack,
          Math.max(0, newHeight - startHeight - horizontalPreviewSlack),
        );
        const inspectorEl = app.querySelector(".inspector") as HTMLElement | null;
        if (inspectorEl !== null) {
          const newInspectorHeight = horizontalStartInspectorHeight - consumedFromInspector;
          this.inspectorHeight = newInspectorHeight;
          localStorage.setItem("mt-inspector-height", String(newInspectorHeight));
          inspectorEl.style.height = `${newInspectorHeight}px`;
          inspectorEl.style.minHeight = "";
          inspectorEl.style.maxHeight = "none";
        }
      }
    };
    const endHorizontalDrag = () => {
      document.body.classList.remove("is-dragging-horizontal");
    };
    sashHorizontal.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      const outputValuesEl = app.querySelector(".output-values") as HTMLElement | null;
      if (outputValuesEl !== null && outputValuesEl.classList.contains("collapsed")) {
        return;
      }
      startY = e.clientY;
      startHeight = outputValuesEl?.getBoundingClientRect().height ?? this.outputValuesHeight;
      horizontalPreviewSlack = Math.max(0, previewArea.getBoundingClientRect().height - kMinPreviewAreaHeight);
      const inspectorEl = app.querySelector(".inspector") as HTMLElement | null;
      horizontalInspectorStacked = this.isNarrowLayout()
        && inspectorEl !== null
        && !inspectorEl.classList.contains("collapsed");
      horizontalStartInspectorHeight = horizontalInspectorStacked && inspectorEl !== null
        ? inspectorEl.getBoundingClientRect().height
        : 0;
      horizontalInspectorSlack = Math.max(0, horizontalStartInspectorHeight - kMinPanelHeight);
      maxHorizontalHeight = startHeight + horizontalPreviewSlack + horizontalInspectorSlack;
      document.body.classList.add("is-dragging-horizontal");
      sashHorizontal.setPointerCapture(e.pointerId);
    });
    sashHorizontal.addEventListener("pointermove", (e) => {
      if (!sashHorizontal.hasPointerCapture(e.pointerId)) {
        return;
      }
      onMouseMoveHorizontal(e);
    });
    sashHorizontal.addEventListener("pointerup", endHorizontalDrag);
    sashHorizontal.addEventListener("pointercancel", endHorizontalDrag);

    this.outputValues = new OutputValuesView(app);

    if (this.inspectorCollapsed) {
      this.toggleInspectorCollapse(true);
    } else {
      this.toggleInspectorCollapse(false);
      const inspectorEl = simulatorBody.querySelector(".inspector") as HTMLElement | null;
      if (inspectorEl !== null) {
        if (this.isNarrowLayout()) {
          inspectorEl.style.width = "auto";
          inspectorEl.style.height = `${this.inspectorHeight}px`;
          inspectorEl.style.minHeight = "";
          inspectorEl.style.maxHeight = "none";
        } else {
          inspectorEl.style.width = `${this.inspectorWidth}px`;
          inspectorEl.style.height = "";
          inspectorEl.style.minHeight = "";
          inspectorEl.style.maxHeight = "";
        }
      }
    }

    const outputValuesEl = app.querySelector(".output-values") as HTMLElement | null;
    if (outputValuesEl !== null) {
      outputValuesEl.style.height = `${this.outputValuesHeight}px`;
      outputValuesEl.style.maxHeight = "none";
      outputValuesEl.style.minHeight = "0";
    }

    const applyLayoutForCurrentWidth = () => {
      const inspectorEl = simulatorBody.querySelector(".inspector") as HTMLElement | null;
      if (inspectorEl !== null) {
        if (this.isNarrowLayout()) {
          if (!this.inspectorCollapsed) {
            inspectorEl.style.height = `${this.inspectorHeight}px`;
            inspectorEl.style.minHeight = "";
            inspectorEl.style.maxHeight = "none";
          }
        } else {
          inspectorEl.style.height = "";
          inspectorEl.style.minHeight = "";
          inspectorEl.style.maxHeight = "";
        }
      }
      this.timeline?.refresh();
    };
    this.layoutResizeHandler = applyLayoutForCurrentWidth;
    window.addEventListener("resize", this.layoutResizeHandler);
    // The web build's #app can also change width without the window itself
    // resizing (dragging the editor/preview split sash), which "resize"
    // never fires for; ResizeObserver catches both cases uniformly.
    this.layoutResizeObserver = new ResizeObserver(applyLayoutForCurrentWidth);
    this.layoutResizeObserver.observe(app);
    this.layoutAdapter?.mount(app);
  }

  async switchTarget(message: TargetPayload): Promise<void> {
    if (this.evaluator === undefined) {
      return;
    }
    const scriptGeneration = this.scriptReloadQueue.advanceTarget();
    // Stop playback before the first await so the previous target cannot
    // continue rendering during an asynchronous recording shutdown.
    this.timeline?.reset();
    // A recording in progress belongs to the previous target; discard it and
    // wait for its loop to unwind before the new script touches the evaluator.
    await this.abandonRecording();
    if (!this.scriptReloadQueue.isCurrent(scriptGeneration)) {
      return;
    }
    this.luaUri = message.luaUri;
    this.loadingFontFamilies.clear();
    this.scene = message.scene;
    this.globalLoop = message.globalLoop;
    if (this.hb !== undefined && message.fontBytes !== undefined && message.fontPath !== undefined) {
      const layoutEngine = new TextLayoutEngine(this.hb, message.fontBytes);
      this.evaluator.setLayoutEngine(layoutEngine);
      message.scene.global.fontName = layoutEngine.familyName();
      message.scene.settings.fontPath = message.fontPath;
    } else {
      this.evaluator.setLayoutEngine(undefined);
    }
    this.toolbar?.applyState({
      displayMode: message.scene.settings.displayMode,
      partMode: message.scene.settings.partMode,
      partsPerCharacter: message.scene.settings.partsPerCharacter,
    });
    const topology = this.evaluator.synchronizeSceneTopology(message.scene);
    this.topology = topology;
    this.validScriptInputMetadata = undefined;
    const metadata = parseMugMetadata(message.luaSource);
    applyMetadataToScene(message.scene, metadata, { applyScriptInputDefaults: false });
    this.metadata = this.synchronizeMetadata(metadata, false);
    this.toolbar?.setTopology(topology.characterCount, topology.partCount);
    this.inspector?.refresh(message.scene, topology.characterCount, topology.partCount, this.metadata);
    this.timeline?.updateConfiguration(
      message.scene.settings.durationFrames,
      message.scene.settings.fps,
      this.globalLoop,
    );
    await this.scriptReloadQueue.enqueue(message.luaSource, scriptGeneration);
  }

  applyFont(result: FontBytesResult): void {
    if (this.scene === undefined || this.evaluator === undefined || this.hb === undefined) {
      return;
    }
    const { path, bytes, purpose, requestedFamily } = result;
    try {
      const layoutEngine = new TextLayoutEngine(this.hb, bytes);
      const familyName = layoutEngine.familyName();
      if (purpose === "script") {
        this.evaluator.registerLayoutEngine(layoutEngine, requestedFamily);
        if (requestedFamily !== undefined) {
          this.loadingFontFamilies.delete(requestedFamily);
        }
      } else {
        this.scene.settings.fontPath = path;
        this.scene.global.fontName = familyName;
        this.evaluator.setLayoutEngine(layoutEngine);
        this.inspector?.refresh(this.scene, this.topology?.characterCount ?? 0, this.topology?.partCount ?? 0, this.metadata);
        // The selected font is an init input and can change both topology counts.
        this.reinitialize();
        this.postSceneChanged(this.scene);
      }
      this.timeline?.refresh();
    } catch (error) {
      const message = `Font failed to load: ${path} (${String(error)})`;
      this.setStatus(message);
      this.host.warn(message);
    }
  }

  async reloadScript(
    source: string,
    scriptGeneration = this.scriptReloadQueue.currentGeneration,
  ): Promise<void> {
    if (this.engine === undefined || this.evaluator === undefined || this.scene === undefined) {
      return;
    }
    if (!this.scriptReloadQueue.isCurrent(scriptGeneration)) {
      return;
    }
    const metadata = parseMugMetadata(source);
    applyMetadataToScene(this.scene, metadata, { applyScriptInputDefaults: false });
    this.metadata = this.synchronizeMetadata(metadata, true);
    this.timeline?.updateConfiguration(
      this.scene.settings.durationFrames,
      this.scene.settings.fps,
      this.globalLoop,
    );
    this.inspector?.refresh(
      this.scene,
      this.topology?.characterCount ?? 0,
      this.topology?.partCount ?? 0,
      this.metadata,
    );
    this.reportedMessages.clear();
    this.loadingFontFamilies.clear();
    const loadResult = await this.engine.loadScript(source);
    if (!this.scriptReloadQueue.isCurrent(scriptGeneration)) {
      return;
    }
    if (!loadResult.ok) {
      this.reportError(loadResult.message ?? "script load failed");
      this.setStatus(`script error: ${loadResult.message ?? "unknown"}`);
    } else {
      this.reinitialize();
      const metadataError = this.metadata?.scriptInputError;
      if (metadataError === undefined) {
        this.setStatus("script loaded");
      } else {
        const message = `input metadata error at line ${metadataError.line}: ${metadataError.message}`;
        this.setStatus(message);
        this.host.warn(message);
      }
      this.host.log("[simulator] script reloaded");
    }
    this.timeline?.refresh();
  }

  // Every edit and target switch shares one queue, so ScriptEngine.loadScript
  // can never race another candidate runtime. A target generation change
  // invalidates queued edits that belonged to the previous script.
  enqueueReload(source: string): void {
    void this.scriptReloadQueue.enqueue(source);
  }

  private synchronizeMetadata(metadata: MugMetadata, applyChangedDefaults: boolean): MugMetadata {
    let result = metadata;
    if (this.scene !== undefined) {
      const scriptInputs = synchronizeScriptInputMetadata(
        this.scene,
        metadata,
        this.validScriptInputMetadata,
        applyChangedDefaults,
      );
      if (metadata.scriptInputError === undefined) {
        this.validScriptInputMetadata = scriptInputs;
      }
      result = { ...metadata, scriptInputs };
    }
    return result;
  }

  private reinitialize(): void {
    if (this.evaluator === undefined || this.scene === undefined) {
      return;
    }
    const topology = this.evaluator.synchronizeSceneTopology(this.scene);
    this.toolbar?.setTopology(topology.characterCount, topology.partCount);
    if (
      this.topology?.characterCount !== topology.characterCount ||
      this.topology?.partCount !== topology.partCount
    ) {
      this.topology = topology;
      this.inspector?.refresh(this.scene, topology.characterCount, topology.partCount, this.metadata);
    }
    const initResult = this.evaluator.initialize(this.scene);
    for (const error of initResult.errors) {
      this.reportError(error);
    }
  }

  private renderFrame(frame: number): void {
    if (this.evaluator === undefined || this.scene === undefined || this.preview === undefined) {
      return;
    }
    const evaluated = this.evaluator.evaluate(this.scene, frame);
    if (evaluated.requestedFontName !== undefined) {
      this.requestScriptFont(evaluated.requestedFontName);
    }
    this.preview.render(evaluated, this.scene.settings.displayMode, this.scene.settings.showIndexLabels);
    this.toolbar?.setTopology(evaluated.characters.length, evaluated.parts.length);
    this.outputValues?.render(evaluated);
    for (const error of evaluated.errors) {
      this.reportError(error);
    }
    for (const warning of evaluated.warnings) {
      this.reportWarning(warning);
    }
    if (evaluated.errors.length > 0) {
      this.setStatus(`frame ${frame}: ${evaluated.errors[0]}`);
    } else {
      this.setStatus("");
    }
  }

  exportMp4Video(): void {
    void this.exportVideo("mp4");
  }

  async exportVideo(format: VideoRecorderFormat): Promise<boolean> {
    let exported = false;
    if (this.timeline !== undefined) {
      const range = this.timeline.recordRangeValue;
      exported = await this.startRecording(range.startFrame, range.endFrame, format);
    }
    return exported;
  }

  // Locks the UI behind an overlay (stop only) and renders the range offscreen
  // as fast as the evaluator allows -- the recording is no longer tied to
  // realtime playback, and the preview is left untouched so the frame is drawn
  // once per frame instead of twice. The finished video is sent to the host for
  // the save dialog.
  private async startRecording(
    startFrame: number,
    endFrame: number,
    format: VideoRecorderFormat = "webm",
  ): Promise<boolean> {
    let exported = false;
    if (!this.host.capabilities.recording) {
      this.host.warn("recording is not available in this build");
    } else if (this.recorder !== undefined || this.recordingRun !== undefined) {
      this.host.warn("a recording is already in progress");
    } else if (this.scene === undefined) {
      this.host.warn("recording is unavailable before the scene is initialized");
    } else {
      this.recordingStartFrame = startFrame;
      this.recordingEndFrame = endFrame;
      this.recordingAborted = false;
      this.recordingDiscarded = false;
      this.finishingRecording = false;
      this.lastRecordedFrame = startFrame;
      this.timeline?.pausePlayback();
      this.showRecordingOverlay();
      const recordingRun = this.runRecording(startFrame, endFrame, format);
      this.recordingRun = recordingRun;
      exported = await recordingRun;
    }
    return exported;
  }

  private async runRecording(
    startFrame: number,
    endFrame: number,
    format: VideoRecorderFormat = "webm",
  ): Promise<boolean> {
    const scene = this.scene;
    const evaluator = this.evaluator;
    let saved = false;
    try {
      if (scene === undefined || evaluator === undefined) {
        throw new Error("scene is not initialized");
      }
      // Imported on demand: the video muxer is a sizeable dependency that only
      // matters once the user actually records something.
      const { VideoRecorder } = await import("../webview/videoRecorder");
      this.recorder = await VideoRecorder.create(
        scene.settings.canvasWidth,
        scene.settings.canvasHeight,
        scene.settings.fps,
        format,
      );
      const recorder = this.recorder;
      // Integer frame steps: the recording samples the same instants the
      // scene is authored on, rather than wherever a realtime clock landed.
      for (let frame = startFrame; frame <= endFrame && !this.recordingAborted; frame += 1) {
        const evaluated = evaluator.evaluate(scene, frame);
        await recorder.captureFrame(
          evaluated,
          scene.settings.displayMode,
          scene.settings.showIndexLabels,
        );
        this.updateRecordingProgress(frame);
        await yieldToUi();
      }
      if (!this.recordingDiscarded) {
        const blob = await recorder.stop();
        this.recorder = undefined;
        this.host.saveVideo(
          await blob.arrayBuffer(),
          this.luaUri,
          startFrame,
          Math.min(endFrame, this.lastRecordedFrame),
          blob.type,
        );
        saved = true;
      }
    } catch (error) {
      const message = `recording failed: ${String(error)}`;
      this.setStatus(message);
      this.host.warn(message);
    } finally {
      await this.recorder?.dispose();
      this.recorder = undefined;
      this.recordingRun = undefined;
      this.finishingRecording = false;
      this.recordingOverlay?.remove();
      this.recordingOverlay = undefined;
      this.recordingProgress = undefined;
      if (saved) {
        this.setStatus("");
      }
      // The playhead moved through the range offscreen; restore what the
      // preview was showing before the recording started.
      this.timeline?.refresh();
    }
    return saved;
  }

  // Requests that the offscreen loop stop after the current frame. Frames
  // already encoded are still muxed and saved.
  private finishRecording(): void {
    if (this.recordingRun === undefined || this.finishingRecording) {
      return;
    }
    this.finishingRecording = true;
    this.recordingAborted = true;
  }

  // Stops a recording and throws away what it produced, then waits for the
  // loop to unwind. Used when the script being recorded is replaced: the
  // partial file belongs to a scene that no longer exists.
  private async abandonRecording(): Promise<void> {
    if (this.recordingRun === undefined) {
      return;
    }
    this.recordingAborted = true;
    this.recordingDiscarded = true;
    await this.recordingRun;
  }

  private showRecordingOverlay(): void {
    const overlay = document.createElement("div");
    overlay.className = "recording-overlay";
    const dialog = document.createElement("div");
    dialog.className = "recording-dialog";
    this.recordingProgress = document.createElement("div");
    this.recordingProgress.className = "recording-progress";
    const stopButton = document.createElement("button");
    stopButton.textContent = t("timeline.stop");
    stopButton.addEventListener("click", () => {
      this.finishRecording();
    });
    dialog.append(this.recordingProgress, stopButton);
    overlay.appendChild(dialog);
    document.body.appendChild(overlay);
    this.recordingOverlay = overlay;
    this.updateRecordingProgress(this.recordingStartFrame);
  }

  private updateRecordingProgress(frame: number): void {
    this.lastRecordedFrame = frame;
    if (this.recordingProgress !== undefined) {
      this.recordingProgress.textContent =
        `Recording frame ${frame} / ${this.recordingEndFrame}`;
    }
  }

  private requestScriptFont(familyName: string): void {
    if (this.loadingFontFamilies.has(familyName)) {
      return;
    }
    const font = this.fontList.find((candidate) => candidate.family === familyName);
    if (font === undefined) {
      this.reportWarning(`layout.font_name '${familyName}' is not available in the simulator font list`);
    } else {
      this.loadingFontFamilies.add(familyName);
      this.host.requestFont(font.path, this.luaUri, "script", familyName);
    }
  }

  private reportError(message: string): void {
    if (!this.reportedMessages.has(message)) {
      this.reportedMessages.add(message);
      this.host.reportLuaError(message, extractLine(message));
    }
  }

  private reportWarning(message: string): void {
    if (!this.reportedMessages.has(message)) {
      this.reportedMessages.add(message);
      this.host.warn(message);
    }
  }

  private setStatus(text: string): void {
    if (this.statusBar !== undefined) {
      this.statusBar.textContent = text;
    }
  }

  isTarget(luaUri: string): boolean {
    return luaUri === this.luaUri;
  }

  // Renders the frame currently on screen into an offscreen canvas at the
  // scene's native pixel size and returns it as an encoded still.
  //
  // This deliberately does not read back the preview canvas: that one is
  // sized to the panel and carries the viewer's zoom and pan, so capturing it
  // would bake the current view into the image. Rendering afresh through the
  // same path the recorder uses (renderFrame at scale 1) makes the still
  // match the recording frame for frame.
  //
  // WebP is preferred over PNG because the still is destined for a gallery
  // card, where a 500 KB cap applies; PNG is the fallback for browsers
  // that cannot encode WebP. The blob's own type is reported back so the
  // caller names the file after what was actually produced -- toBlob silently
  // falls back to PNG for a type it does not support, which would otherwise
  // yield a .webp file containing PNG bytes.
  //
  // Hands the captured still to the host, which decides where it goes. Only
  // called when the host implements saveThumbnail, since the preview shows
  // its capture button only in that case.
  private async saveThumbnail(): Promise<void> {
    try {
      const blob = await this.captureCurrentFrameImage();
      if (blob === undefined) {
        this.setStatus("could not capture the current frame");
      } else {
        this.host.saveThumbnail?.(blob, this.luaUri);
      }
    } catch (error) {
      const message = `thumbnail capture failed: ${String(error)}`;
      this.setStatus(message);
      this.host.warn(message);
    }
  }

  // Resolves to undefined when there is nothing to render or the browser
  // cannot produce a blob, leaving the caller to report it.
  async captureCurrentFrameImage(): Promise<Blob | undefined> {
    let result: Blob | undefined;
    if (this.evaluator !== undefined && this.scene !== undefined) {
      const { canvasWidth, canvasHeight, displayMode, showIndexLabels } = this.scene.settings;
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(Math.round(canvasWidth), 1);
      canvas.height = Math.max(Math.round(canvasHeight), 1);
      const context = canvas.getContext("2d");
      if (context !== null) {
        const evaluated = this.evaluator.evaluate(this.scene, this.timeline?.frame ?? 0);
        drawFrame(context, evaluated, 1, { displayMode, showIndexLabels });
        result = await new Promise<Blob | undefined>((resolve) => {
          canvas.toBlob((blob) => resolve(blob ?? undefined), "image/webp", kThumbnailWebpQuality);
        });
      }
    }
    return result;
  }

  showScriptCopyResult(success: boolean): void {
    this.toolbar?.showCopyResult(success);
  }

  private toggleInspectorCollapse(collapsed: boolean): void {
    this.inspectorCollapsed = collapsed;
    localStorage.setItem("mt-inspector-collapsed", String(collapsed));
    const appContainer = document.getElementById("app");
    const inspectorEl = appContainer?.querySelector(".inspector") as HTMLElement | null;
    const sashVertical = appContainer?.querySelector(".sash-vertical") as HTMLElement | null;
    const openButton = appContainer?.querySelector(".inspector-open-button") as HTMLElement | null;
    if (inspectorEl !== null) {
      inspectorEl.classList.toggle("collapsed", collapsed);
      if (!collapsed) {
        if (this.isNarrowLayout()) {
          inspectorEl.style.width = "auto";
          inspectorEl.style.height = `${this.inspectorHeight}px`;
          inspectorEl.style.minHeight = "";
          inspectorEl.style.maxHeight = "none";
        } else {
          inspectorEl.style.width = `${this.inspectorWidth}px`;
          inspectorEl.style.height = "";
          inspectorEl.style.minHeight = "";
          inspectorEl.style.maxHeight = "";
        }
      } else {
        inspectorEl.style.height = "";
        inspectorEl.style.minHeight = "";
      }
    }
    if (sashVertical !== null) {
      sashVertical.style.display = collapsed ? "none" : "";
    }
    if (openButton !== null) {
      openButton.style.display = collapsed ? "" : "none";
    }
    this.timeline?.refresh();
  }

  private postSceneChanged(scene: Scene): void {
    this.host.notifySceneChanged(scene, this.luaUri);
  }

  private resetLayout(): void {
    localStorage.removeItem("mt-inspector-width");
    localStorage.removeItem("mt-inspector-height");
    localStorage.removeItem("mt-output-values-height");
    localStorage.removeItem("mt-inspector-collapsed");
    localStorage.removeItem("mt-output-values-collapsed");

    this.inspectorWidth = 280;
    this.inspectorHeight = 300;
    this.outputValuesHeight = 200;
    this.inspectorCollapsed = false;

    this.layoutAdapter?.reset();
    this.buildUi();

    if (this.timeline !== undefined) {
      this.renderFrame(this.timeline.frame);
    }
  }

  private disposeUi(): void {
    this.compatibilityNoticeDispose?.();
    this.compatibilityNoticeDispose = undefined;
    this.timeline?.dispose();
    this.timeline = undefined;
    this.toolbar?.dispose();
    this.toolbar = undefined;
    this.preview?.dispose();
    this.preview = undefined;
    if (this.layoutResizeHandler !== undefined) {
      window.removeEventListener("resize", this.layoutResizeHandler);
      this.layoutResizeHandler = undefined;
    }
    this.layoutResizeObserver?.disconnect();
    this.layoutResizeObserver = undefined;
  }
}

// User chunks are explicitly named by ScriptEngine. Prefer their location
// over prelude/diagnostic frames, while retaining the legacy wasmoon pattern
// for syntax errors produced before a named chunk can execute.
function extractLine(message: string): number | undefined {
  const match = /user-script\.lua:(\d+):/.exec(message) ?? /\]:(\d+):/.exec(message);
  return match !== null ? Number(match[1]) : undefined;
}

// Returns control to the event loop between recorded frames. The offscreen
// loop is otherwise a tight await chain that can starve rendering of the
// progress overlay and its stop button.
function yieldToUi(): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, 0);
  });
}

export function showFatalError(error: unknown): void {
  const message = `Simulator failed to initialize: ${String(error)}`;
  const errorElement = document.createElement("pre");
  errorElement.className = "fatal-error";
  errorElement.textContent = message;
  document.getElementById("app")?.replaceChildren(errorElement);
  console.error(message);
}
