import type { CtxCharacterData, CtxGlobalData, CtxPartData } from "./ctxBindings";
import type { TextLayoutEngine } from "./layout";
import { approximateParts, pathBounds } from "./parts";
import { composeAnchored, type Mat2D } from "./transform";
import {
  kDaVinciNormalizedCenter,
  type GlobalScene,
  type PartMode,
  type Scene,
} from "../shared/sceneSchema";
import { fontSizePixels } from "./renderUnits";

export interface LocalRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface NaturalCharacter {
  text: string;
  lineIndex: number;
  originX: number;
  originY: number;
  verticalOriginX: number;
  verticalOriginY: number;
  advanceX: number;
  advanceY: number;
  centerX: number;
  centerY: number;
  width: number;
  height: number;
  boundingCenterX: number;
  boundingCenterY: number;
  // Concatenated glyph outlines, character-center-relative.
  pathData?: string;
}

export interface PartGeometry {
  // Ink-bounds centre of the part.
  centerX: number;
  centerY: number;
  // Origin the part's outline is drawn around, matching the host's natural
  // position. Distinct from the ink centre whenever the glyph is not centred on
  // it, which is the usual case for text without descenders.
  originX: number;
  originY: number;
  width: number;
  height: number;
  pathData?: string;
  clipRect?: LocalRect;
}

const kNaiveAdvanceRatio = 1.05;
const kNaiveLineAdvanceRatio = 1.2;
const kNaiveAscentRatio = 0.8;

export class SceneGeometry {
  private layoutEngine: TextLayoutEngine | undefined;

  setLayoutEngine(layoutEngine: TextLayoutEngine | undefined): void {
    this.layoutEngine = layoutEngine;
  }

  fontFamilyName(): string | undefined {
    return this.layoutEngine?.familyName();
  }

  fontMetrics(fontSize: number): { ascent: number; descent: number; lineHeight: number; unitsPerEm: number } {
    return this.layoutEngine?.fontMetrics(fontSize) ?? {
      ascent: fontSize * kNaiveAscentRatio,
      descent: fontSize * (1 - kNaiveAscentRatio),
      lineHeight: fontSize * kNaiveLineAdvanceRatio,
      unitsPerEm: 1000,
    };
  }

  // Global scale is intentionally NOT applied here: it scales the finished
  // layout through the global matrix, exactly once.
  layoutCharacters(layout: GlobalScene, scene: Scene): NaturalCharacter[] {
    const fontSize = fontSizePixels(scene.settings.canvasHeight);
    let result: NaturalCharacter[];
    if (this.layoutEngine !== undefined) {
      result = this.layoutEngine
        .layout(layout, {
          canvasWidth: scene.settings.canvasWidth,
          canvasHeight: scene.settings.canvasHeight,
          fontSize,
        })
        .map((shaped) => {
          const pathData = shaped.glyphs.map((glyph) => glyph.pathData).join("") || undefined;
          const bounds = pathData === undefined ? undefined : pathBounds(pathData);
          return {
            text: shaped.text,
            lineIndex: shaped.lineIndex,
            originX: shaped.originX,
            originY: shaped.originY,
            verticalOriginX: shaped.verticalOriginX,
            verticalOriginY: shaped.verticalOriginY,
            advanceX: shaped.advanceX,
            advanceY: shaped.advanceY,
            centerX: shaped.centerX,
            centerY: shaped.centerY,
            width: shaped.width,
            height: shaped.height,
            boundingCenterX: shaped.centerX + (bounds?.centerX ?? 0),
            boundingCenterY: shaped.centerY + (bounds?.centerY ?? 0),
            pathData,
          };
        });
    } else {
      result = layoutNaively(layout, fontSize);
    }
    return result;
  }

  buildPartGeometry(characters: NaturalCharacter[], scene: Scene): PartGeometry[][] {
    const partMode: PartMode = scene.settings.partMode;
    return characters.map((natural) => {
      let parts: PartGeometry[];
      if (partMode === "contour" && natural.pathData !== undefined) {
        parts = approximateParts(natural.pathData).map((glyphPart) => ({
          centerX: natural.centerX + glyphPart.centerX,
          centerY: natural.centerY + glyphPart.centerY,
          originX: natural.centerX,
          originY: natural.centerY,
          width: glyphPart.width,
          height: glyphPart.height,
          pathData: glyphPart.pathData,
        }));
      } else {
        const isWhitespaceOnly = natural.text.trim().length === 0;
        const count = (natural.pathData === undefined && isWhitespaceOnly) ? 1 : scene.settings.partsPerCharacter;
        parts = equalSlices(natural, count);
      }
      return parts;
    });
  }
}

export function globalMatrix(
  global: CtxGlobalData,
  canvasWidth: number,
  canvasHeight: number,
): Mat2D {
  return composeAnchored({
    anchorX: (global.pivot_x - kDaVinciNormalizedCenter) * canvasWidth,
    anchorY: -(global.pivot_y - kDaVinciNormalizedCenter) * canvasHeight,
    offsetX: global.position_x * canvasWidth,
    offsetY: (1 - global.position_y) * canvasHeight,
    rotationDegrees: global.rotation,
    scaleX: global.scale * global.stretch_x,
    scaleY: global.scale * global.stretch_y,
  });
}

export function characterMatrix(
  character: CtxCharacterData,
  natural: NaturalCharacter,
  canvasWidth: number,
  canvasHeight: number,
): Mat2D {
  return composeAnchored({
    anchorX: natural.boundingCenterX + (character.pivot_x - kDaVinciNormalizedCenter) * canvasWidth,
    anchorY: natural.boundingCenterY - (character.pivot_y - kDaVinciNormalizedCenter) * canvasHeight,
    offsetX: (character.offset_x - kDaVinciNormalizedCenter) * canvasWidth,
    offsetY: -(character.offset_y - kDaVinciNormalizedCenter) * canvasHeight,
    rotationDegrees: character.rotation,
    scaleX: character.scale * character.stretch_x,
    scaleY: character.scale * character.stretch_y,
  });
}

export function partMatrix(
  part: CtxPartData,
  centerX: number,
  centerY: number,
  canvasWidth: number,
  canvasHeight: number,
): Mat2D {
  return composeAnchored({
    anchorX: centerX + (part.pivot_x - kDaVinciNormalizedCenter) * canvasWidth,
    anchorY: centerY - (part.pivot_y - kDaVinciNormalizedCenter) * canvasHeight,
    offsetX: (part.offset_x - kDaVinciNormalizedCenter) * canvasWidth,
    offsetY: -(part.offset_y - kDaVinciNormalizedCenter) * canvasHeight,
    rotationDegrees: part.rotation,
    scaleX: part.scale * part.stretch_x,
    scaleY: part.scale * part.stretch_y,
  });
}

// Vertical slices of the character cell; used in fixed part mode and as the
// fallback when no outline exists (spaces, or no font loaded).
function equalSlices(natural: NaturalCharacter, count: number): PartGeometry[] {
  const sliceWidth = natural.width / count;
  const result: PartGeometry[] = [];
  for (let slice = 0; slice < count; slice += 1) {
    const localX = -natural.width / 2 + sliceWidth * slice;
    result.push({
      centerX: natural.centerX + localX + sliceWidth / 2,
      centerY: natural.centerY,
      originX: natural.centerX,
      originY: natural.centerY,
      width: sliceWidth,
      height: natural.height,
      pathData: natural.pathData,
      clipRect: { x: localX, y: -natural.height / 2, width: sliceWidth, height: natural.height },
    });
  }
  return result;
}

// Fixed-advance fallback layout used when no font is available.
function layoutNaively(layout: GlobalScene, fontSize: number): NaturalCharacter[] {
  const lineAdvance = fontSize * kNaiveLineAdvanceRatio * layout.lineSpacing;
  const lines = layout.text.split("\n").map((line) => Array.from(line));
  const result: NaturalCharacter[] = [];
  let characterOffset = 0;
  for (const [lineIndex, line] of lines.entries()) {
    const advances = line.map(
      (_character, index) =>
        fontSize * kNaiveAdvanceRatio +
        (layout.tracking + (layout.margins[characterOffset + index] ?? 0)) * fontSize,
    );
    const lineExtent = Math.max(advances.reduce((sum, advance) => sum + advance, 0), fontSize);
    const blockExtent = (lines.length - 1) * lineAdvance + fontSize;
    for (const [columnIndex, character] of line.entries()) {
      let centerX: number;
      let centerY: number;
      if (layout.vertical) {
        centerX =
          localAlignmentStart(layout.hAlign, blockExtent) +
          (lines.length - 1 - lineIndex) * lineAdvance +
          fontSize / 2;
        centerY =
          localAlignmentStart(verticalAsLinear(layout.vAlign), lineExtent) +
          advances.slice(0, columnIndex).reduce((sum, advance) => sum + advance, 0) +
          fontSize / 2;
      } else {
        centerX =
          localAlignmentStart(layout.hAlign, lineExtent) +
          advances.slice(0, columnIndex).reduce((sum, advance) => sum + advance, 0) +
          fontSize / 2;
        centerY =
          naiveVerticalBlockStart(layout.vAlign, blockExtent, fontSize) +
          lineIndex * lineAdvance +
          fontSize / 2;
      }
      result.push({
        text: character,
        lineIndex,
        originX: centerX - fontSize / 2,
        originY: centerY + fontSize * (kNaiveAscentRatio - 0.5),
        verticalOriginX: centerX,
        verticalOriginY: centerY - fontSize / 2,
        advanceX: layout.vertical ? fontSize : fontSize * kNaiveAdvanceRatio,
        advanceY: layout.vertical ? fontSize * kNaiveAdvanceRatio : fontSize,
        centerX,
        centerY,
        width: fontSize,
        height: fontSize,
        boundingCenterX: centerX,
        boundingCenterY: centerY,
      });
    }
    characterOffset += line.length;
  }
  return result;
}

function localAlignmentStart(align: "left" | "center" | "right", extent: number): number {
  let result = -extent / 2;
  if (align === "left") {
    result = 0;
  } else if (align === "right") {
    result = -extent;
  }
  return result;
}

function naiveVerticalBlockStart(
  align: "top" | "center" | "bottom" | "baseline",
  blockHeight: number,
  fontSize: number,
): number {
  let result = localAlignmentStart(verticalAsLinear(align), blockHeight);
  if (align === "baseline") {
    result = -fontSize * kNaiveAscentRatio;
  }
  return result;
}

function verticalAsLinear(
  align: "top" | "center" | "bottom" | "baseline",
): "left" | "center" | "right" {
  let result: "left" | "center" | "right" = "center";
  if (align === "top") {
    result = "left";
  } else if (align === "bottom") {
    result = "right";
  }
  return result;
}
