export const kLuaMonarchLanguage: Monaco.languages.IMonarchLanguage = {
  defaultToken: "",
  tokenPostfix: ".lua",

  keywords: [
    "and",
    "break",
    "do",
    "else",
    "elseif",
    "end",
    "for",
    "function",
    "goto",
    "if",
    "in",
    "local",
    "not",
    "or",
    "repeat",
    "return",
    "then",
    "until",
    "while",
  ],

  constants: ["true", "false", "nil"],

  mugGlobals: ["ctx", "mt"],

  mugHooks: kLuaHooks.map((hook) => hook.name),

  builtinFunctions: [
    "assert",
    "collectgarbage",
    "dofile",
    "error",
    "getmetatable",
    "ipairs",
    "load",
    "loadfile",
    "next",
    "pairs",
    "pcall",
    "print",
    "rawequal",
    "rawget",
    "rawlen",
    "rawset",
    "require",
    "select",
    "setmetatable",
    "tonumber",
    "tostring",
    "type",
    "warn",
    "xpcall",
  ],

  builtinModules: [
    "math",
    "table",
    "string",
    "utf8",
    "os",
    "io",
    "debug",
    "package",
    "coroutine",
  ],

  brackets: [
    { token: "delimiter.bracket", open: "{", close: "}" },
    { token: "delimiter.array", open: "[", close: "]" },
    { token: "delimiter.parenthesis", open: "(", close: ")" },
  ],

  operators: [
    "+",
    "-",
    "*",
    "/",
    "//",
    "^",
    "%",
    "&",
    "~",
    "|",
    ">>",
    "<<",
    "..",
    "<",
    "<=",
    ">",
    ">=",
    "==",
    "~=",
    "#",
    "=",
  ],

  symbols: /[=><!~?:&|+\-*/^%#|]+/,
  escapes: /\\(?:[abfnrtvz\\"'\n]|x[0-9A-Fa-f]{2}|u\{[0-9A-Fa-f]+\}|[0-9]{1,3})/,

  tokenizer: {
    root: [
      // Directives in comments: -- @title, -- @author, etc.
      [/--\s*@\w+.*$/, "comment.directive"],

      // Multi-line comments: --[[ ... ]] or --[=[ ... ]=]
      [/--\[([=]*)\[/, "comment", "@commentBlock.$1"],

      // Single line comments
      [/--.*$/, "comment"],

      // Function declaration: function name(...) or function obj:name(...)
      [
        /(function\s+)([a-zA-Z_]\w*)(\s*\()/,
        ["keyword", "entity.name.function", "delimiter.parenthesis"],
      ],

      // Method call via colon: :method_name(...)
      [
        /(:)([a-zA-Z_]\w*)(\s*)(?=\()/,
        ["delimiter", "entity.name.function", ""],
      ],

      // Method name via colon: :method_name
      [
        /(:)([a-zA-Z_]\w*)/,
        ["delimiter", "entity.name.function"],
      ],

      // Member call via dot: .function_name(...)
      [
        /(\.)([a-zA-Z_]\w*)(\s*)(?=\()/,
        ["delimiter", "entity.name.function", ""],
      ],

      // Property access via dot: .property_name
      [
        /(\.)([a-zA-Z_]\w*)/,
        ["delimiter", "variable.property"],
      ],

      // Function calls: name(...)
      [
        /([a-zA-Z_]\w*)(\s*)(?=\()/,
        {
          cases: {
            "@mugGlobals": ["type.predefined", ""],
            "@mugHooks": ["entity.name.function", ""],
            "@builtinFunctions": ["support.function", ""],
            "@builtinModules": ["type.predefined", ""],
            "@keywords": ["keyword", ""],
            "@constants": ["constant.language", ""],
            "@default": ["entity.name.function", ""],
          },
        },
      ],

      // Identifiers and keywords
      [
        /[a-zA-Z_]\w*/,
        {
          cases: {
            "@mugGlobals": "type.predefined",
            "@mugHooks": "entity.name.function",
            "@builtinFunctions": "support.function",
            "@builtinModules": "type.predefined",
            "@keywords": "keyword",
            "@constants": "constant.language",
            "@default": "variable",
          },
        },
      ],

      // Whitespace
      { include: "@whitespace" },

      // Delimiters and brackets
      [/[{}()[\]]/, "@brackets"],
      [
        /@symbols/,
        {
          cases: {
            "@operators": "operator",
            "@default": "delimiter",
          },
        },
      ],

      // Numbers: hex, float, exponent, int
      [/0[xX][0-9a-fA-F]+(\.[0-9a-fA-F]*)?([eE][+-]?[0-9]+)?/, "number"],
      [/\d+(\.\d+)?([eE][+-]?[0-9]+)?/, "number"],

      // Strings
      [/"([^"\\]|\\.)*$/, "string.invalid"],
      [/'([^'\\]|\\.)*$/, "string.invalid"],
      [/"/, "string", "@stringDouble"],
      [/'/, "string", "@stringSingle"],
      [/\[([=]*)\[/, "string", "@stringBlock.$1"],
    ],

    whitespace: [[/[ \t\r\n]+/, ""]],

    commentBlock: [
      [/@\w+/, "comment.directive"],
      [/[^\]@]+/, "comment"],
      [
        /\]([=]*)\]/,
        {
          cases: {
            "$1==$S2": { token: "comment", next: "@pop" },
            "@default": "comment",
          },
        },
      ],
      [/./, "comment"],
    ],

    stringDouble: [
      [/[^\\"]+/, "string"],
      [/@escapes/, "string.escape"],
      [/\\./, "string.escape.invalid"],
      [/"/, "string", "@pop"],
    ],

    stringSingle: [
      [/[^\\']+/, "string"],
      [/@escapes/, "string.escape"],
      [/\\./, "string.escape.invalid"],
      [/'/, "string", "@pop"],
    ],

    stringBlock: [
      [/[^\]]+/, "string"],
      [
        /\]([=]*)\]/,
        {
          cases: {
            "$1==$S2": { token: "string", next: "@pop" },
            "@default": "string",
          },
        },
      ],
      [/./, "string"],
    ],
  },
};

export function registerMonacoLuaLanguage(monaco: typeof Monaco): void {
  monaco.languages.setMonarchTokensProvider("lua", kLuaMonarchLanguage);
  monaco.editor.defineTheme(kMonacoMtDarkThemeName, kMonacoMtDarkTheme);

  monaco.languages.registerCompletionItemProvider("lua", {
    // Both quote styles open a string literal, where enumerated values complete; @ for metadata directives.
    triggerCharacters: [".", ":", "O", "f", "@", "\"", "'"],
    provideCompletionItems(model, position) {
      return provideCompletionItems(monaco, model, position);
    },
  });
  monaco.languages.registerHoverProvider("lua", {
    provideHover(model, position) {
      return provideHover(monaco, model, position);
    },
  });
  monaco.languages.registerColorProvider("lua", {
    provideDocumentColors(model) {
      const source = model.getValue();
      if (!isMugTypographyScript(source)) {
        return [];
      }
      return findRecommendedColorCodes(source).map(({ startOffset, endOffset, color }) => {
        const start = model.getPositionAt(startOffset);
        const end = model.getPositionAt(endOffset);
        return {
          range: new monaco.Range(
            start.lineNumber,
            start.column,
            end.lineNumber,
            end.column,
          ),
          color: {
            red: color.r,
            green: color.g,
            blue: color.b,
            alpha: color.a,
          },
        };
      });
    },
    provideColorPresentations(model, colorInformation) {
      const original = model.getValueInRange(colorInformation.range);
      const color = colorInformation.color;
      const hex = formatHexColor(
        { r: color.red, g: color.green, b: color.blue, a: color.alpha },
        original.length === 9 || color.alpha < 1,
      );
      return [{
        label: hex,
        textEdit: { range: colorInformation.range, text: hex },
      }];
    },
  });
}

function provideCompletionItems(
  monaco: typeof Monaco,
  model: Monaco.editor.ITextModel,
  position: Monaco.Position,
): Monaco.languages.CompletionList | undefined {
  if (!isMugTypographyScript(model.getValue())) {
    return undefined;
  }
  const wordInfo = model.getWordUntilPosition(position);
  const range = new monaco.Range(
    position.lineNumber,
    wordInfo.startColumn,
    position.lineNumber,
    wordInfo.endColumn,
  );

  const currentLine = model.getLineContent(position.lineNumber);
  const metadataResult = resolveLuaMetadataCompletion(currentLine, position.column);
  if (metadataResult !== undefined) {
    const isJapanese = isJapaneseLocale();
    return {
      suggestions: metadataResult.candidates.map((candidate) => {
        const itemRange = candidate.replaceRange !== undefined
          ? new monaco.Range(
              position.lineNumber,
              candidate.replaceRange.startColumn,
              position.lineNumber,
              candidate.replaceRange.endColumn,
            )
          : range;
        const isDirective = candidate.kind === "directive";
        return {
          label: candidate.label,
          kind: isDirective
            ? monaco.languages.CompletionItemKind.Keyword
            : monaco.languages.CompletionItemKind.Value,
          detail: candidate.detail ?? candidate.label,
          documentation: {
            value:
              (isJapanese ? candidate.descriptionJa : candidate.description) +
              (candidate.example !== undefined ? `\n\n\`\`\`lua\n${candidate.example}\n\`\`\`` : ""),
          },
          insertText: candidate.insertText,
          insertTextRules: monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet,
          range: itemRange,
        };
      }),
    };
  }

  const source = model.getValueInRange({
    startLineNumber: 1,
    startColumn: 1,
    endLineNumber: position.lineNumber,
    endColumn: position.column,
  });
  // A cursor inside a string literal can only take enumerated values, never a
  // member, so a literal suppresses the member list even when nothing is
  // enumerated there -- offering ctx fields inside quotes would be noise.
  if (resolveLuaStringLiteralContext(source) !== undefined) {
    return {
      suggestions: resolveLuaStringValues(source).map((value) => ({
        label: value,
        kind: monaco.languages.CompletionItemKind.EnumMember,
        insertText: value,
        range,
      })),
    };
  }
  const resolved = resolveLuaCompletionContext(source);
  let suggestions: Monaco.languages.CompletionItem[];
  if (resolved.target === "root") {
    suggestions = makeRootCompletionItems(monaco, wordInfo.word, range);
  } else {
    const section = targetToSection(resolved.target);
    suggestions = membersForTarget(resolved.target, resolved.phase).map((member) =>
      makeMemberCompletionItem(monaco, member, range, section),
    );
  }
  return { suggestions };
}

function provideHover(
  monaco: typeof Monaco,
  model: Monaco.editor.ITextModel,
  position: Monaco.Position,
): Monaco.languages.Hover | undefined {
  if (!isMugTypographyScript(model.getValue())) {
    return undefined;
  }
  const line = model.getLineContent(position.lineNumber);

  const wordAtPosition = model.getWordAtPosition(position);
  if (wordAtPosition !== null) {
    const col = wordAtPosition.startColumn;
    const hasAt = col > 1 && line[col - 2] === "@";
    const queryWord = hasAt ? `@${wordAtPosition.word}` : wordAtPosition.word;
    const metadataHover = findMetadataDirectiveHover(queryWord, isJapaneseLocale());
    if (metadataHover !== undefined) {
      const range = new monaco.Range(
        position.lineNumber,
        hasAt ? col - 1 : col,
        position.lineNumber,
        wordAtPosition.endColumn,
      );
      return {
        range,
        contents: [
          { value: `\`\`\`lua\n${metadataHover.signature}\n\`\`\`` },
          { value: `${metadataHover.description}\n\n\`\`\`lua\n${metadataHover.example}\n\`\`\`` },
        ],
      };
    }
  }

  const expressionRange = expressionRangeAt(line, position.column - 1);
  let result: Monaco.languages.Hover | undefined;
  if (expressionRange !== undefined) {
    const expression = line.slice(expressionRange.start, expressionRange.end);
    const range = new monaco.Range(
      position.lineNumber,
      expressionRange.start + 1,
      position.lineNumber,
      expressionRange.end + 1,
    );
    const parsed = parseHoverExpression(expression);
    if (parsed !== undefined) {
      const sourceEndColumn = expressionRange.start + parsed.receiverEnd + 1;
      const source = model.getValueInRange({
        startLineNumber: 1,
        startColumn: 1,
        endLineNumber: position.lineNumber,
        endColumn: sourceEndColumn,
      });
      const resolved = resolveLuaCompletionContext(`${source}.`);
      if (resolved.target !== "root") {
        const apiMember = membersForTarget(resolved.target, resolved.phase).find(
          ({ name }) => name === parsed.memberName,
        );
        if (apiMember !== undefined) {
          const description = getApiMemberDescription(apiMember, isJapaneseLocale());
          const section = targetToSection(resolved.target);
          result = {
            range,
            contents: [
              {
                value: `\`\`\`lua\n${memberSignature(parsed.receiver, apiMember, parsed.separator)}\n\`\`\``,
              },
              { value: description + getApiReferenceLink(section, apiMember) },
            ],
          };
        }
      }
    } else {
      // Bare identifier: host callbacks or local variables.
      const hook = findLuaHook(expression);
      if (hook !== undefined) {
        const description = getLuaHookDescription(hook, isJapaneseLocale());
        result = {
          range,
          contents: [
            { value: `\`\`\`lua\n${hook.signature}\n\`\`\`` },
            { value: description + getApiReferenceLink("callback") },
          ],
        };
      } else {
        const localHover = findLocalVariableHover(model.getValue(), expression, position.lineNumber - 1);
        if (localHover !== undefined) {
          result = {
            range,
            contents: [
              { value: `\`\`\`lua\n${localHover.signature}\n\`\`\`` },
              ...(localHover.documentation !== undefined ? [{ value: localHover.documentation }] : []),
            ],
          };
        }
      }
    }
  }
  return result;
}

function makeMemberCompletionItem(
  monaco: typeof Monaco,
  apiMember: LuaApiMember,
  range: Monaco.Range,
  section?: string,
): Monaco.languages.CompletionItem {
  const isFunction = apiMember.parameters !== undefined;
  const description = getApiMemberDescription(apiMember, isJapaneseLocale());
  const insertText = isFunction
    ? `${apiMember.name}(${apiMember.parameters?.map((parameter, index) => `\${${index + 1}:${parameter}}`).join(", ") ?? ""})`
    : apiMember.name;
  return {
    label: apiMember.name,
    kind: isFunction ? monaco.languages.CompletionItemKind.Method : monaco.languages.CompletionItemKind.Field,
    detail: memberSignature("", apiMember),
    documentation: { value: description + getApiReferenceLink(section, apiMember) },
    insertText,
    insertTextRules: isFunction
      ? monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet
      : undefined,
    tags: apiMember.deprecated === true ? [monaco.languages.CompletionItemTag.Deprecated] : undefined,
    range,
  };
}

function makeRootCompletionItems(
  monaco: typeof Monaco,
  prefix: string,
  range: Monaco.Range,
): Monaco.languages.CompletionItem[] {
  const normalizedPrefix = prefix.toLowerCase();
  return kLuaHooks
    .filter((hook) => {
      const name = hook.name.toLowerCase();
      const functionForm = `function ${name}`;
      return (
        normalizedPrefix.length === 0 ||
        name.startsWith(normalizedPrefix) ||
        functionForm.startsWith(normalizedPrefix) ||
        normalizedPrefix === "function" ||
        normalizedPrefix.startsWith("function ")
      );
    })
    .map((hook) => {
      const description = getLuaHookDescription(hook, isJapaneseLocale());
      return {
        label: hook.name,
        kind: monaco.languages.CompletionItemKind.Function,
        detail: hook.signature,
        documentation: { value: description + getApiReferenceLink("callback") },
        insertText: `function ${hook.name}(ctx)\n\t\${1:${hook.bodyComment}}\nend`,
        insertTextRules: monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet,
        filterText: `${hook.name} function ${hook.name}`,
        range,
      };
    });
}

// VSCode links to a "command:" URI that opens the bundled Markdown; the web
// build has no bundled copy, so it links out to the published user manual
// instead. A function's own anchor wins when the hovered/completed member is
// known; otherwise the link falls back to the section the category maps to.
function getApiReferenceLink(section?: string, apiMember?: LuaApiMember): string {
  const anchor =
    apiMember?.reference?.anchor ??
    (section === undefined ? undefined : apiReferenceLocation(section)?.fragment);
  const url = publishedApiReferenceUrl(getLocale(), anchor);
  return isJapaneseLocale()
    ? `\n\n[📖 詳細はこちら (APIリファレンス)](${url})`
    : `\n\n[📖 Open Full API Reference](${url})`;
}

function memberSignature(
  receiver: string,
  apiMember: LuaApiMember,
  separator = ".",
): string {
  const qualifiedName =
    receiver.length > 0 ? `${receiver}${separator}${apiMember.name}` : apiMember.name;
  let signature = `${qualifiedName}: ${apiMember.type}`;
  if (apiMember.parameters !== undefined) {
    signature = `${qualifiedName}(${apiMember.parameters.join(", ")})`;
    if (apiMember.returns !== undefined) {
      signature += `: ${apiMember.returns}`;
    }
  }
  return signature;
}

function expressionRangeAt(line: string, character: number): { start: number; end: number } | undefined {
  // ":" so a method call such as path:at_distance hovers as one expression.
  const isExpressionCharacter = (value: string): boolean => /[A-Za-z0-9_.:[\]]/.test(value);
  let start = character;
  let end = character;
  while (start > 0 && isExpressionCharacter(line[start - 1])) {
    start -= 1;
  }
  while (end < line.length && isExpressionCharacter(line[end])) {
    end += 1;
  }
  return end > start ? { start, end } : undefined;
}
