import {
  createGridview,
  GridviewPanel,
  Orientation,
  type CreateComponentOptions,
  type GridviewApi,
  type IFrameworkPart,
  type SerializedGridviewComponent,
} from "dockview";
import "dockview/dist/styles/dockview.css";
import type { SimulatorLayoutAdapter } from "./simulatorApp";

const kSimulatorNarrowWidth = 760;
const kOuterWideStorageKey = "mt-web-grid-outer-wide";
const kEditorStorageKey = "mt-web-grid-editor";
const kSimulatorWideStorageKey = "mt-web-grid-simulator-wide";
const kSimulatorNarrowStorageKey = "mt-web-grid-simulator-narrow";

interface PanelDefinition {
  id: string;
  element: HTMLElement;
  minimumWidth?: number;
  minimumHeight?: number;
  defaultWidth?: number;
  defaultHeight?: number;
}

interface GridLayoutPreset {
  orientation: Orientation;
  storageKey: string;
  addPanels: (api: GridviewApi) => void;
}

class ElementGridviewPanel extends GridviewPanel {
  constructor(
    options: CreateComponentOptions,
    definition: PanelDefinition,
  ) {
    super(options.id, options.name, {
      minimumWidth: definition.minimumWidth,
      minimumHeight: definition.minimumHeight,
    });
    this.element.classList.add("mt-grid-panel");
    this.element.appendChild(definition.element);
  }

  protected getComponent(): IFrameworkPart {
    return {
      update: () => undefined,
      dispose: () => undefined,
    };
  }
}

function readStoredLayout(storageKey: string): SerializedGridviewComponent | undefined {
  let result: SerializedGridviewComponent | undefined;
  const storedValue = localStorage.getItem(storageKey);
  if (storedValue !== null) {
    try {
      result = JSON.parse(storedValue) as SerializedGridviewComponent;
    } catch {
      localStorage.removeItem(storageKey);
    }
  }
  return result;
}

class ElementGrid {
  private readonly api: GridviewApi;
  private readonly resizeObserver: ResizeObserver;
  private storageKey: string;
  private restoring = false;
  private initialSizePending = false;

  constructor(
    host: HTMLElement,
    private readonly definitions: Map<string, PanelDefinition>,
    preset: GridLayoutPreset,
  ) {
    this.storageKey = preset.storageKey;
    host.replaceChildren();
    host.classList.add("mt-grid-host");
    this.api = createGridview(host, {
      orientation: preset.orientation,
      proportionalLayout: true,
      className: "mt-gridview",
      createComponent: (options) => {
        const definition = this.definitions.get(options.name);
        if (definition === undefined) {
          throw new Error(`unknown grid component: ${options.name}`);
        }
        return new ElementGridviewPanel(options, definition);
      },
    });
    this.restoreOrBuild(preset);
    this.api.onDidLayoutChange(() => {
      if (!this.restoring) {
        localStorage.setItem(this.storageKey, JSON.stringify(this.api.toJSON()));
      }
    });
    this.resizeObserver = new ResizeObserver(() => this.applyInitialSizes(host));
    this.resizeObserver.observe(host);
  }

  applyPreset(preset: GridLayoutPreset): void {
    if (preset.storageKey === this.storageKey) {
      return;
    }
    this.storageKey = preset.storageKey;
    this.api.updateOptions({ orientation: preset.orientation });
    this.restoreOrBuild(preset);
  }

  reset(preset: GridLayoutPreset): void {
    localStorage.removeItem(preset.storageKey);
    this.storageKey = preset.storageKey;
    this.api.updateOptions({ orientation: preset.orientation });
    this.buildDefault(preset);
  }

  dispose(): void {
    this.resizeObserver.disconnect();
    this.api.dispose();
  }

  private restoreOrBuild(preset: GridLayoutPreset): void {
    const storedLayout = readStoredLayout(preset.storageKey);
    if (storedLayout === undefined) {
      this.buildDefault(preset);
    } else {
      this.restoring = true;
      try {
        this.api.fromJSON(storedLayout);
      } catch {
        localStorage.removeItem(preset.storageKey);
        this.buildDefault(preset);
      } finally {
        this.restoring = false;
      }
    }
  }

  private buildDefault(preset: GridLayoutPreset): void {
    this.restoring = true;
    this.api.clear();
    preset.addPanels(this.api);
    this.restoring = false;
    this.initialSizePending = true;
    localStorage.setItem(this.storageKey, JSON.stringify(this.api.toJSON()));
  }

  private applyInitialSizes(host: HTMLElement): void {
    if (!this.initialSizePending || host.clientWidth === 0 || host.clientHeight === 0) {
      return;
    }
    this.initialSizePending = false;
    requestAnimationFrame(() => {
      for (const definition of this.definitions.values()) {
        this.api.getPanel(definition.id)?.api.setSize({
          width: definition.defaultWidth,
          height: definition.defaultHeight,
        });
      }
    });
  }
}

function addPanel(
  api: GridviewApi,
  definition: PanelDefinition,
  options: {
    direction?: "right" | "below";
    referencePanel?: string;
    size?: number;
  } = {},
): void {
  api.addPanel({
    id: definition.id,
    component: definition.id,
    minimumWidth: definition.minimumWidth,
    minimumHeight: definition.minimumHeight,
    size: options.size,
    position: options.direction === undefined || options.referencePanel === undefined
      ? undefined
      : {
          direction: options.direction,
          referencePanel: options.referencePanel,
        },
  });
}

function outerPreset(definitions: Map<string, PanelDefinition>): GridLayoutPreset {
  const editor = definitions.get("editor");
  const simulator = definitions.get("simulator");
  if (editor === undefined || simulator === undefined) {
    throw new Error("outer web grid is missing a panel definition");
  }
  return {
    orientation: Orientation.HORIZONTAL,
    storageKey: kOuterWideStorageKey,
    addPanels: (api) => {
      addPanel(api, editor);
      addPanel(api, simulator, {
        direction: "right",
        referencePanel: editor.id,
      });
    },
  };
}

function simulatorPreset(
  narrow: boolean,
  definitions: Map<string, PanelDefinition>,
): GridLayoutPreset {
  const preview = definitions.get("preview");
  const inspector = definitions.get("inspector");
  const output = definitions.get("output");
  if (preview === undefined || inspector === undefined || output === undefined) {
    throw new Error("simulator web grid is missing a panel definition");
  }
  return {
    orientation: narrow ? Orientation.VERTICAL : Orientation.HORIZONTAL,
    storageKey: narrow ? kSimulatorNarrowStorageKey : kSimulatorWideStorageKey,
    addPanels: (api) => {
      addPanel(api, preview);
      if (narrow) {
        addPanel(api, inspector, {
          direction: "below",
          referencePanel: preview.id,
          size: 240,
        });
        addPanel(api, output, {
          direction: "below",
          referencePanel: inspector.id,
          size: 180,
        });
      } else {
        // Create the full-width lower row before splitting the upper row.
        // Adding Output after Inspector would nest it under Preview only.
        addPanel(api, output, {
          direction: "below",
          referencePanel: preview.id,
          size: 200,
        });
        addPanel(api, inspector, {
          direction: "right",
          referencePanel: preview.id,
          size: 300,
        });
      }
    },
  };
}

export class WebGridLayout implements SimulatorLayoutAdapter {
  private readonly outerGrid: ElementGrid;
  private readonly editorGrid: ElementGrid;
  private readonly editorPreset: GridLayoutPreset;
  private readonly outerDefinitions: Map<string, PanelDefinition>;
  private simulatorGrid: ElementGrid | undefined;
  private simulatorDefinitions: Map<string, PanelDefinition> | undefined;
  private simulatorNarrow = false;
  private simulatorResizeObserver: ResizeObserver | undefined;

  constructor(
    shell: HTMLElement,
    editorPane: HTMLElement,
    editorContainer: HTMLElement,
    logPanel: HTMLElement,
    simulator: HTMLElement,
    private readonly onEditorLayout: () => void,
  ) {
    const editorGridHost = document.createElement("div");
    editorGridHost.className = "mt-editor-grid";
    editorPane.replaceChildren(editorGridHost);
    const editorDefinitions = new Map<string, PanelDefinition>([
      ["code", { id: "code", element: editorContainer, minimumWidth: 180, minimumHeight: 100 }],
      [
        "log",
        {
          id: "log",
          element: logPanel,
          minimumWidth: 180,
          minimumHeight: 60,
          defaultHeight: 140,
        },
      ],
    ]);
    this.editorPreset = {
      orientation: Orientation.VERTICAL,
      storageKey: kEditorStorageKey,
      addPanels: (api) => {
        const code = editorDefinitions.get("code");
        const log = editorDefinitions.get("log");
        if (code !== undefined && log !== undefined) {
          addPanel(api, code);
          addPanel(api, log, {
            direction: "below",
            referencePanel: code.id,
            size: 140,
          });
        }
      },
    };
    this.editorGrid = new ElementGrid(editorGridHost, editorDefinitions, this.editorPreset);

    this.outerDefinitions = new Map<string, PanelDefinition>([
      ["editor", { id: "editor", element: editorPane, minimumWidth: 220, minimumHeight: 180 }],
      ["simulator", { id: "simulator", element: simulator, minimumWidth: 280, minimumHeight: 280 }],
    ]);
    this.outerGrid = new ElementGrid(
      shell,
      this.outerDefinitions,
      outerPreset(this.outerDefinitions),
    );
    const outerResizeObserver = new ResizeObserver(() => {
      this.onEditorLayout();
    });
    outerResizeObserver.observe(shell);
  }

  mount(app: HTMLElement): void {
    this.simulatorResizeObserver?.disconnect();
    this.simulatorGrid?.dispose();

    const toolbar = app.querySelector<HTMLElement>(".toolbar");
    const preview = app.querySelector<HTMLElement>(".preview-column");
    const inspector = app.querySelector<HTMLElement>(".inspector");
    const output = app.querySelector<HTMLElement>(".output-values");
    if (toolbar === null || preview === null || inspector === null || output === null) {
      throw new Error("simulator UI is missing one or more grid panels");
    }

    app.querySelectorAll(".sash-vertical, .sash-horizontal").forEach((sash) => sash.remove());
    preview.querySelector(".inspector-open-button")?.remove();
    inspector.classList.remove("collapsed");
    output.classList.remove("collapsed");
    inspector.removeAttribute("style");
    output.removeAttribute("style");
    app.classList.add("mt-managed-layout");

    const simulatorGridHost = document.createElement("div");
    simulatorGridHost.className = "mt-simulator-grid";
    app.replaceChildren(toolbar, simulatorGridHost);
    this.simulatorDefinitions = new Map<string, PanelDefinition>([
      ["preview", { id: "preview", element: preview, minimumWidth: 180, minimumHeight: 100 }],
      [
        "inspector",
        {
          id: "inspector",
          element: inspector,
          minimumWidth: 180,
          minimumHeight: 80,
          defaultWidth: 300,
          defaultHeight: 240,
        },
      ],
      [
        "output",
        {
          id: "output",
          element: output,
          minimumWidth: 180,
          minimumHeight: 60,
          defaultHeight: 200,
        },
      ],
    ]);
    this.simulatorNarrow = app.getBoundingClientRect().width <= kSimulatorNarrowWidth;
    this.simulatorGrid = new ElementGrid(
      simulatorGridHost,
      this.simulatorDefinitions,
      simulatorPreset(this.simulatorNarrow, this.simulatorDefinitions),
    );
    this.simulatorResizeObserver = new ResizeObserver(() => {
      if (this.simulatorDefinitions === undefined || this.simulatorGrid === undefined) {
        return;
      }
      const narrow = app.getBoundingClientRect().width <= kSimulatorNarrowWidth;
      if (narrow !== this.simulatorNarrow) {
        this.simulatorNarrow = narrow;
        this.simulatorGrid.applyPreset(simulatorPreset(narrow, this.simulatorDefinitions));
      }
    });
    this.simulatorResizeObserver.observe(app);
  }

  reset(): void {
    localStorage.removeItem(kOuterWideStorageKey);
    localStorage.removeItem(kEditorStorageKey);
    localStorage.removeItem(kSimulatorWideStorageKey);
    localStorage.removeItem(kSimulatorNarrowStorageKey);
    this.outerGrid.reset(outerPreset(this.outerDefinitions));
    this.editorGrid.reset(this.editorPreset);
    if (this.simulatorGrid !== undefined && this.simulatorDefinitions !== undefined) {
      this.simulatorGrid.reset(
        simulatorPreset(this.simulatorNarrow, this.simulatorDefinitions),
      );
    }
    this.onEditorLayout();
  }
}
