import type { Rgba } from "./sceneSchema";

export const kScriptInputNumberCount = 10;
export const kScriptInputColorCount = 4;
export const kScriptInputTextCount = 2;
export const kScriptInputNumberMinimum = -1000000;
export const kScriptInputNumberMaximum = 1000000;

const kMaximumLabelBytes = 64;
const kMaximumTextBytes = 4096;
const kMaximumDirectiveBytes = 8192;
const kNumberPattern = /^-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;

export interface ScriptInputDeclaration<Value> {
  label: string;
  defaultValue: Value;
}

export interface ScriptInputMetadata {
  numbers: Array<ScriptInputDeclaration<number> | undefined>;
  colors: Array<ScriptInputDeclaration<Rgba> | undefined>;
  texts: Array<ScriptInputDeclaration<string> | undefined>;
}

export interface ScriptInputMetadataError {
  line: number;
  column: number;
  message: string;
}

export interface ScriptInputMetadataResult {
  inputs: ScriptInputMetadata;
  error?: ScriptInputMetadataError;
}

interface ParsedDeclaration {
  type: "number" | "color" | "text";
  index: number;
  label: string;
  defaultValue: number | Rgba | string;
}

export function createEmptyScriptInputMetadata(): ScriptInputMetadata {
  return {
    numbers: Array.from({ length: kScriptInputNumberCount }),
    colors: Array.from({ length: kScriptInputColorCount }),
    texts: Array.from({ length: kScriptInputTextCount }),
  };
}

export function parseScriptInputMetadataLines(lines: readonly string[]): ScriptInputMetadataResult {
  const inputs = createEmptyScriptInputMetadata();
  let error: ScriptInputMetadataError | undefined;
  for (const [lineIndex, line] of lines.entries()) {
    if (error !== undefined) {
      break;
    }
    const match = /^--[ \t\v\f]*@input(?:$|[ \t\v\f])(.*)$/.exec(line);
    if (match === null) {
      continue;
    }
    const body = match[1];
    if (body.length > kMaximumDirectiveBytes || utf8ByteLength(body) > kMaximumDirectiveBytes) {
      error = { line: lineIndex + 1, column: 3, message: "input declaration is too long" };
      continue;
    }
    const parser = new InputDirectiveParser(body);
    const declaration = parser.parse();
    if (declaration === undefined) {
      error = {
        line: lineIndex + 1,
        column: match.index + line.indexOf("@input") + "@input".length + parser.errorColumn,
        message: parser.error,
      };
      continue;
    }
    const duplicate = applyDeclaration(inputs, declaration);
    if (duplicate) {
      error = { line: lineIndex + 1, column: 1, message: "duplicate input declaration" };
    }
  }
  return error === undefined ? { inputs } : { inputs, error };
}

class InputDirectiveParser {
  private cursor = 0;
  private failed = false;
  error = "";
  errorColumn = 1;

  constructor(private readonly body: string) {}

  parse(): ParsedDeclaration | undefined {
    this.skipSeparators();
    const typeToken = asciiLower(this.parseToken());
    if (typeToken !== "number" && typeToken !== "color" && typeToken !== "text") {
      this.fail("unknown input type");
    }

    this.skipSeparators();
    const indexToken = this.parseToken();
    const parsedIndex = /^-?\d+$/.test(indexToken) ? Number(indexToken) : Number.NaN;
    if (!this.failed && !Number.isInteger(parsedIndex)) {
      this.fail("input index must be an integer");
    }
    const maximumIndex =
      typeToken === "number"
        ? kScriptInputNumberCount
        : typeToken === "color"
          ? kScriptInputColorCount
          : kScriptInputTextCount;
    if (!this.failed && (parsedIndex < 1 || parsedIndex > maximumIndex)) {
      this.fail("input index is out of range");
    }

    this.skipSeparators();
    const label = this.parseQuoted();
    if (
      !this.failed &&
      (label.length === 0 ||
        utf8ByteLength(label) > kMaximumLabelBytes ||
        !isValidUnicode(label) ||
        label.includes("\0"))
    ) {
      this.fail("input label must be valid UTF-8 between 1 and 64 bytes");
    }

    let defaultValue: number | Rgba | string =
      typeToken === "number" ? 0 : typeToken === "color" ? { r: 1, g: 1, b: 1, a: 1 } : "";
    this.skipSeparators();
    if (!this.failed && this.cursor < this.body.length) {
      const defaultPrefix = "default=";
      if (!this.body.startsWith(defaultPrefix, this.cursor)) {
        this.fail("expected default=<value>");
      } else {
        this.cursor += defaultPrefix.length;
        if (typeToken === "number") {
          defaultValue = this.parseNumberDefault();
        } else if (typeToken === "color") {
          defaultValue = this.parseColorDefault();
        } else {
          const text = this.parseQuoted();
          if (
            !this.failed &&
            (utf8ByteLength(text) > kMaximumTextBytes || !isValidUnicode(text) || text.includes("\0"))
          ) {
            this.fail("text default must be valid UTF-8 without NUL and at most 4096 bytes");
          }
          defaultValue = text;
        }
        this.skipSeparators();
        if (!this.failed && this.cursor !== this.body.length) {
          this.fail("unexpected trailing token");
        }
      }
    }

    let result: ParsedDeclaration | undefined;
    if (!this.failed && (typeToken === "number" || typeToken === "color" || typeToken === "text")) {
      result = {
        type: typeToken,
        index: parsedIndex - 1,
        label,
        defaultValue,
      };
    }
    return result;
  }

  private skipSeparators(): void {
    while (this.cursor < this.body.length && isDirectiveSeparator(this.body[this.cursor])) {
      this.cursor += 1;
    }
  }

  private parseToken(): string {
    const start = this.cursor;
    while (this.cursor < this.body.length && !isDirectiveSeparator(this.body[this.cursor])) {
      this.cursor += 1;
    }
    return this.body.slice(start, this.cursor);
  }

  private parseQuoted(): string {
    let result = "";
    if (this.cursor >= this.body.length || this.body[this.cursor] !== '"') {
      this.fail("expected a quoted string");
    } else {
      this.cursor += 1;
      let closed = false;
      while (!this.failed && !closed && this.cursor < this.body.length) {
        const character = this.body[this.cursor];
        this.cursor += 1;
        if (character === '"') {
          closed = true;
        } else if (character === "\\") {
          if (
            this.cursor >= this.body.length ||
            (this.body[this.cursor] !== '"' && this.body[this.cursor] !== "\\")
          ) {
            this.fail("unknown string escape");
          } else {
            result += this.body[this.cursor];
            this.cursor += 1;
          }
        } else {
          result += character;
        }
      }
      if (!this.failed && !closed) {
        this.fail("unterminated quoted string");
      }
    }
    return result;
  }

  private parseNumberDefault(): number {
    const start = this.cursor;
    while (
      this.cursor < this.body.length &&
      !isDirectiveSeparator(this.body[this.cursor]) &&
      this.body[this.cursor] !== "," &&
      this.body[this.cursor] !== "}"
    ) {
      this.cursor += 1;
    }
    const token = this.body.slice(start, this.cursor);
    const value = kNumberPattern.test(token) ? Number(token) : Number.NaN;
    if (!Number.isFinite(value)) {
      this.fail("number default must be finite");
    } else if (value < kScriptInputNumberMinimum || value > kScriptInputNumberMaximum) {
      this.fail("number default is out of range");
    }
    return value;
  }

  private parseColorDefault(): Rgba {
    const color: Rgba = { r: 1, g: 1, b: 1, a: 1 };
    const channels: Array<keyof Rgba> = ["r", "g", "b", "a"];
    if (this.cursor >= this.body.length || this.body[this.cursor] !== "{") {
      this.fail("color default must contain four RGBA values");
    } else {
      this.cursor += 1;
      for (const [channelIndex, channel] of channels.entries()) {
        if (this.failed) {
          break;
        }
        this.skipSeparators();
        const value = this.parseNumberDefault();
        if (!this.failed && (value < 0 || value > 1)) {
          this.fail("color channels must be between 0 and 1");
        }
        color[channel] = value;
        this.skipSeparators();
        const delimiter = channelIndex + 1 === channels.length ? "}" : ",";
        if (!this.failed && (this.cursor >= this.body.length || this.body[this.cursor] !== delimiter)) {
          this.fail("color default must contain four RGBA values");
        } else if (!this.failed) {
          this.cursor += 1;
        }
      }
    }
    return color;
  }

  private fail(message: string): void {
    if (!this.failed) {
      this.failed = true;
      this.errorColumn = this.cursor + 1;
      this.error = message;
    }
  }
}

function applyDeclaration(inputs: ScriptInputMetadata, declaration: ParsedDeclaration): boolean {
  let duplicate = false;
  if (declaration.type === "number") {
    duplicate = inputs.numbers[declaration.index] !== undefined;
    inputs.numbers[declaration.index] = {
      label: declaration.label,
      defaultValue: declaration.defaultValue as number,
    };
  } else if (declaration.type === "color") {
    duplicate = inputs.colors[declaration.index] !== undefined;
    inputs.colors[declaration.index] = {
      label: declaration.label,
      defaultValue: declaration.defaultValue as Rgba,
    };
  } else {
    duplicate = inputs.texts[declaration.index] !== undefined;
    inputs.texts[declaration.index] = {
      label: declaration.label,
      defaultValue: declaration.defaultValue as string,
    };
  }
  return duplicate;
}

function isDirectiveSeparator(character: string): boolean {
  return character === " " || character === "\t" || character === "\v" || character === "\f";
}

function asciiLower(value: string): string {
  return value.replace(/[A-Z]/g, (character) => character.toLowerCase());
}

function utf8ByteLength(value: string): number {
  return new TextEncoder().encode(value).length;
}

function isValidUnicode(value: string): boolean {
  let valid = true;
  for (let index = 0; valid && index < value.length; index += 1) {
    const codeUnit = value.charCodeAt(index);
    if (codeUnit >= 0xd800 && codeUnit <= 0xdbff) {
      const nextCodeUnit = value.charCodeAt(index + 1);
      if (!(nextCodeUnit >= 0xdc00 && nextCodeUnit <= 0xdfff)) {
        valid = false;
      } else {
        index += 1;
      }
    } else if (codeUnit >= 0xdc00 && codeUnit <= 0xdfff) {
      valid = false;
    }
  }
  return valid;
}
