import type { Scene } from "../../shared/sceneSchema";
import type { SystemFontEntry, FontLoadPurpose } from "../../shared/messages";
import { appendScriptAttachment } from "../../shared/webmAttachment";
import { getThumbnailFileName, getVideoFileName } from "../../shared/mediaExport";
import type { FontBytesResult, HostAdapter, InitPayload, TargetPayload } from "../host";
import { computeSourceHash, saveStoredScene } from "./sceneStorage";

export type LogLevel = "log" | "warn" | "error";

export interface WebLogLine {
  level: LogLevel;
  text: string;
  lineNumber?: number;
}

export interface WebHostAdapterOptions {
  fontList: SystemFontEntry[];
  // Resolves a font path (as listed in fontList) to its bytes. The web build
  // has no filesystem, so bundled fonts are fetched over HTTP and Local Font
  // Access API fonts are read through queryLocalFonts()'s FontData handles
  // (see fontSources.ts).
  loadFontBytes: (path: string) => Promise<ArrayBuffer>;
  // webMain.ts owns the Monaco editor model and is the single source of
  // truth for "current script text" in the web build.
  getCurrentScriptSource: () => string;
  // The web build has no devtools-console-equivalent panel of its own by
  // default, so script print() output (routed here through log/warn/
  // reportLuaError) needs an in-page sink; webMain.ts wires this to the log
  // panel under the editor.
  onLogLine: (line: WebLogLine) => void;
}

// HostAdapter implementation for the standalone web build: every call
// resolves in-process (no postMessage round-trip), scene persistence uses
// localStorage instead of a workspace file, and recording / local file
// browsing are simply unavailable (capabilities flags gate their UI).
//
// Unlike the VSCode adapter, the web build never receives a push-style
// `init`/`targetChanged` message from a host process: webMain.ts constructs
// the SimulatorApp and calls start()/switchTarget() directly. onInit and
// onTargetChanged exist only to satisfy the HostAdapter interface and are
// never invoked.
export class WebHostAdapter implements HostAdapter {
  readonly capabilities = {
    recording: true,
    localFontAccessApi: typeof window !== "undefined" && "queryLocalFonts" in window,
  };

  private fontBytesHandler: ((result: FontBytesResult) => void) | undefined;
  private scriptCopyResultHandler: ((success: boolean) => void) | undefined;

  constructor(private readonly options: WebHostAdapterOptions) {}

  onLuaSourceChanged(): void {}

  copyScript(): void {
    // navigator.clipboard only exists in secure contexts (https:// or
    // localhost); serving the page over a plain IP address or non-localhost
    // hostname over http:// leaves it undefined, with no exception to catch.
    // There is no non-deprecated fallback for that case, so this just fails
    // loudly instead of silently doing nothing.
    if (typeof navigator.clipboard?.writeText !== "function") {
      this.warn("clipboard access requires a secure context (https:// or localhost)");
      this.scriptCopyResultHandler?.(false);
      return;
    }
    navigator.clipboard
      .writeText(this.options.getCurrentScriptSource())
      .then(() => this.scriptCopyResultHandler?.(true))
      .catch((error: unknown) => {
        this.warn(`clipboard write failed: ${String(error)}`);
        this.scriptCopyResultHandler?.(false);
      });
  }

  log(text: string): void {
    console.log(text);
    this.options.onLogLine({ level: "log", text });
  }

  warn(text: string): void {
    console.warn(text);
    this.options.onLogLine({ level: "warn", text });
  }

  reportLuaError(message: string, line?: number): void {
    const text = line !== undefined ? `line ${line}: ${message}` : message;
    console.error(text);
    this.options.onLogLine({ level: "error", text, lineNumber: line });
  }

  notifySceneChanged(scene: Scene, luaUri: string): void {
    try {
      const source = this.options.getCurrentScriptSource?.();
      const sourceHash = source !== undefined ? computeSourceHash(source) : undefined;
      saveStoredScene(luaUri, scene, sourceHash);
    } catch (error) {
      this.warn(`failed to persist simulator scene: ${String(error)}`);
    }
  }

  requestFont(path: string, luaUri: string, purpose: FontLoadPurpose, requestedFamily?: string): void {
    this.options
      .loadFontBytes(path)
      .then((bytes) => {
        this.fontBytesHandler?.({ path, bytes, luaUri, purpose, requestedFamily });
      })
      .catch((error: unknown) => {
        this.warn(`failed to load font: ${path} (${String(error)})`);
      });
  }

  browseFont(): void {
    // The web build offers Local Font Access API fonts through the same
    // fontList + requestFont path (see fontSources.ts); there is no
    // OS-level file-open dialog to fall back to.
    this.warn("browsing arbitrary local font files is not available in the web build");
  }

  revealLine(): void {
    // No editor-agnostic notion of "reveal" outside VSCode; Monaco's own
    // cursor/scroll APIs are driven directly from webMain.ts instead.
  }

  setLoopPreference(loop: boolean): void {
    try {
      localStorage.setItem("mt-web-loop-playback", String(loop));
    } catch {
      // Loop preference is a nicety; ignore storage failures (e.g. private
      // browsing quota errors).
    }
  }

  saveVideo(
    bytes: ArrayBuffer,
    luaUri: string,
    startFrame: number,
    endFrame: number,
    mimeType: string = "video/webm",
  ): void {
    const scriptSource = this.options.getCurrentScriptSource();
    const scriptName = luaUri.replace(/\.lua$/, "") || "script";
    const fileName = getVideoFileName(scriptSource, luaUri, startFrame, endFrame, mimeType);
    const isMp4 = mimeType === "video/mp4" || mimeType === "mp4";
    let finalBlob: Blob;
    if (isMp4) {
      finalBlob = new Blob([bytes], { type: "video/mp4" });
    } else {
      const videoBytes = appendScriptAttachment(
        new Uint8Array(bytes),
        // The embedded attachment keeps the script's own identity rather than
        // its title: loading the recording back has to restore the script it
        // came from, whatever the author happened to call it.
        `${scriptName}.lua`,
        scriptSource,
      );
      finalBlob = new Blob([videoBytes], { type: "video/webm" });
    }
    const url = URL.createObjectURL(finalBlob);
    const link = document.createElement("a");
    link.href = url;
    link.download = fileName;
    link.click();
    // click() only needs to hand the URL to the browser's download manager
    // synchronously; revoking on the next tick (rather than immediately)
    // avoids racing that hand-off without holding the object URL open
    // indefinitely.
    setTimeout(() => URL.revokeObjectURL(url), 0);
  }

  // The extension follows the blob's own type: SimulatorApp asks for WebP but
  // falls back to PNG on browsers that cannot encode it, and the file name
  // must not claim otherwise.
  saveThumbnail(blob: Blob, luaUri: string): void {
    const fileName = getThumbnailFileName(this.options.getCurrentScriptSource(), luaUri, blob.type);
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.download = fileName;
    link.href = url;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 0);
  }

  onInit(): void {}

  onTargetChanged(): void {}

  onFontBytes(handler: (result: FontBytesResult) => void): void {
    this.fontBytesHandler = handler;
  }

  onScriptCopyResult(handler: (success: boolean) => void): void {
    this.scriptCopyResultHandler = handler;
  }

  ready(): void {
    // No host process to signal readiness to.
  }
}

export type { InitPayload, TargetPayload };
