export interface LuaApiMember {
  name: string;
  type: string;
  description: string;
  descriptionJa: string;
  readIn: readonly LuaHookPhase[];
  writeIn: readonly LuaHookPhase[];
  // Lua API level this member has been available since (schema "since").
  since: number;
  values?: readonly string[];
  parameters?: readonly string[];
  // Enumerated values a string argument accepts, keyed by the parameter name as
  // it appears in `parameters` (including any optional "?" mark).
  parameterValues?: Readonly<Record<string, readonly string[]>>;
  returns?: string;
  deprecated?: boolean;
  reference?: {
    file: string;
    anchor: string;
  };
  // Lower/upper bounds the host clamps a written number to before use, if any
  // (schema "min"/"max"). Fields with no configured bound omit these.
  min?: number;
  max?: number;
}

