export function membersForTarget(
  target: LuaCompletionTarget,
  phase: LuaHookPhase,
): readonly LuaApiMember[] {
  let members: readonly LuaApiMember[];
  switch (target) {
    case "ctx":
      members = contextMembers(phase);
      break;
    case "canvas": members = canvasMembers; break;
    case "timeline": members = timelineMembers; break;
    case "font": members = fontMetricMembers; break;
    case "meta": members = metaMembers; break;
    case "capabilities": members = capabilityMembers; break;
    case "limits": members = limitMembers; break;
    case "script_inputs": members = scriptInputMembers; break;
    case "global": members = globalMembers; break;
    case "global_fill": members = globalFillMembers; break;
    case "gradient": members = gradientMembers; break;
    case "global_stroke": members = globalStrokeMembers; break;
    case "global_shadow": members = globalShadowMembers; break;
    case "camera": members = cameraMembers; break;
    case "character": members = characterMembers; break;
    case "character_geometry": members = characterGeometryMembers; break;
    case "part": members = partMembers; break;
    case "part_geometry": members = partGeometryMembers; break;
    case "path_collection": members = pathCollectionMembers; break;
    case "each_info": members = eachInfoMembers; break;
    case "path_part": members = pathPartMembers; break;
    case "drawing_path": members = drawingPathMembers; break;
    case "individual_fill": members = individualFillMembers; break;
    case "individual_stroke": members = individualStrokeMembers; break;
    case "individual_shadow": members = individualShadowMembers; break;
    case "bounding_box": members = boundingBoxMembers; break;
    case "output": members = outputMembers; break;
    case "color": members = colorMembers; break;
    case "oklab_components": members = oklabComponentMembers; break;
    case "oklch_components": members = oklchComponentMembers; break;
    case "okhsv_components": members = okhsvComponentMembers; break;
    case "okhsl_components": members = okhslComponentMembers; break;
    case "mt": members = mtMembers; break;
    case "ease": members = easeMembers; break;
    case "color_utilities": members = colorUtilityMembers; break;
    case "layout_utilities": members = layoutUtilityMembers; break;
    case "path_utilities": members = pathUtilityMembers; break;
    case "arc_length_path": members = arcLengthPathMembers; break;
    case "timeline_utilities": members = timelineUtilityMembers; break;
    case "text_utilities": members = textUtilityMembers; break;
  }
  return members;
}

function contextMembers(phase: LuaHookPhase): readonly LuaApiMember[] {
  const members: readonly LuaApiMember[] = contextFieldMembers;
  return members.filter(({ readIn }) => readIn.includes(phase));
}

export function writableMembers(
  members: readonly LuaApiMember[],
  phase: LuaHookPhase,
): readonly LuaApiMember[] {
  return members.filter(({ writeIn }) => writeIn.includes(phase));
}

export const writableGlobalFieldNames = writableMembers(globalMembers, "pre_layout").map(({ name }) => name);
